      await prisma.article.create({ data: { slug: artAi2, authorId: author.id, categoryId: catAi.id, status: "PUBLISHED", imageUrl: "https://images.unsplash.com/photo-1507668077129-56e32842fceb?q=80&w=1200&auto=format&fit=crop", translations: { create: [{ lang: "en", title: "Chinese Geo-Tech Giants Deploy Neural Networks for Basra Subsurface Seismic Surveys", excerpt: "Artificial Intelligence: Advanced machine learning algorithms map underground structures with high precision, minimizing experimental test drilling.", content: "Basra \u2014 In a breakthrough for digital geology, Chinese petroleum engineering teams in Basra have successfully deployed advanced artificial neural networks for subsurface mapping. By processing decades of seismic soundwave data through deep-learning models, the AI can construct high-definition three-dimensional models of underground layers. This neural network mapping achieves high precision without the need for destructive exploratory drilling, drastically reducing cost and minimizing environmental impacts." }, { lang: "ar", title: "\u0634\u0631\u0643\u0627\u062A \u062C\u064A\u0648\u062A\u0643\u0646\u0648\u0644\u0648\u062C\u064A\u0629 \u0635\u064A\u0646\u064A\u0629 \u062A\u0646\u0634\u0631 \u0634\u0628\u0643\u0627\u062A \u0639\u0635\u0628\u064A\u0629 \u0644\u0644\u0645\u0633\u0648\u062D \u0627\u0644\u0632\u0644\u0632\u0627\u0644\u064A\u0629 \u062A\u062D\u062A \u0627\u0644\u0633\u0637\u062D \u0641\u064A \u0627\u0644\u0628\u0635\u0631\u0629", excerpt: "\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A: \u062E\u0648\u0627\u0631\u0632\u0645\u064A\u0627\u062A \u062A\u0639\u0644\u0645 \u0627\u0644\u0622\u0644\u0629 \u0627\u0644\u0645\u062A\u0642\u062F\u0645\u0629 \u062A\u0631\u0633\u0645 \u062E\u0631\u0627\u0626\u0637 \u0644\u0644\u0647\u064A\u0627\u0643\u0644 \u0627\u0644\u0623\u0631\u0636\u064A\u0629 \u0628\u062F\u0642\u0629 \u0639\u0627\u0644\u064A\u0629\u060C \u0645\u0645\u0627 \u064A\u0642\u0644\u0644 \u0645\u0646 \u0627\u0644\u062D\u0641\u0631 \u0627\u0644\u062A\u062C\u0631\u064A\u0628\u064A.", content: "\u0627\u0644\u0628\u0635\u0631\u0629 \u2014 \u0641\u064A \u0637\u0641\u0631\u0629 \u0646\u0648\u0639\u064A\u0629 \u0644\u0644\u062C\u064A\u0648\u0644\u0648\u062C\u064A\u0627 \u0627\u0644\u0631\u0642\u0645\u064A\u0629\u060C \u0646\u062C\u062D\u062A \u0641\u0631\u0642 \u0627\u0644\u0647\u0646\u062F\u0633\u0629 \u0627\u0644\u0628\u062A\u0631\u0648\u0644\u064A\u0629 \u0627\u0644\u0635\u064A\u0646\u064A\u0629 \u0641\u064A \u0627\u0644\u0628\u0635\u0631\u0629 \u0641\u064A \u0646\u0634\u0631 \u0634\u0628\u0643\u0627\u062A \u0639\u0635\u0628\u064A\u0629 \u0627\u0635\u0637\u0646\u0627\u0639\u064A\u0629 \u0645\u062A\u0642\u062F\u0645\u0629 \u0644\u0644\u0645\u0633\u062D \u0648\u0631\u0633\u0645 \u0627\u0644\u062E\u0631\u0627\u0626\u0637 \u062A\u062D\u062A \u0627\u0644\u0633\u0637\u062D. \u0648\u0645\u0646 \u062E\u0644\u0627\u0644 \u0645\u0639\u0627\u0644\u062C\u0629 \u0639\u0642\u0648\u062F \u0645\u0646 \u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0645\u0648\u062C\u0627\u062A \u0627\u0644\u0635\u0648\u062A\u064A\u0629 \u0627\u0644\u0632\u0644\u0632\u0627\u0644\u064A\u0629 \u0639\u0628\u0631 \u0646\u0645\u0627\u0630\u062C \u0627\u0644\u062A\u0639\u0644\u0645 \u0627\u0644\u0639\u0645\u064A\u0642\u060C \u064A\u0633\u062A\u0637\u064A\u0639 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A \u0628\u0646\u0627\u0621 \u0646\u0645\u0627\u0630\u062C \u062B\u0644\u0627\u062B\u064A\u0629 \u0627\u0644\u0623\u0628\u0639\u0627\u062F \u0639\u0627\u0644\u064A\u0629 \u0627\u0644\u062F\u0642\u0629 \u0644\u0644\u0637\u0628\u0642\u0627\u062A \u0627\u0644\u062C\u0648\u0641\u064A\u0629." }, { lang: "zh", title: "\u4E2D\u5730\u8D28\u79D1\u6280\u56E2\u961F\u5728\u5DF4\u58EB\u62C9\u90E8\u7F72\u4EBA\u5DE5\u795E\u7ECF\u7F51\u7EDC\u8FDB\u884C\u7CBE\u7EC6\u5316\u5730\u4E0B\u4E09\u7EF4\u5730\u9707\u52D8\u63A2", excerpt: "\u4EBA\u5DE5\u667A\u80FD\uFF1A\u9AD8\u9636\u673A\u5668\u5B66\u4E60\u7B97\u6CD5\u5BF9\u5730\u8868\u6DF1\u5C42\u7ED3\u6784\u5B9E\u65BD\u9AD8\u7CBE\u5EA6\u8FD8\u539F\u6210\u50CF\uFF0C\u6700\u5927\u9650\u5EA6\u51CF\u5C11\u4E86\u8BD5\u9A8C\u6027\u52D8\u63A2\u6253\u4E95\u3002", content: "\u5DF4\u58EB\u62C9 \u2014 \u6570\u5B57\u5316\u5730\u8D28\u52D8\u63A2\u7814\u7A76\u8FCE\u6765\u91CD\u8981\u7A81\u7834\u3002\u4E2D\u65B9\u9A7B\u5DF4\u58EB\u62C9\u7684\u77F3\u6CB9\u52D8\u6D4B\u5DE5\u7A0B\u56E2\u961F\u6210\u529F\u5C06\u5148\u8FDB\u7684\u4EBA\u5DE5\u795E\u7ECF\u7F51\u7EDC\uFF08ANN\uFF09\u5F15\u5165\u6CB9\u6C14\u5730\u4E0B\u7269\u7406\u52D8\u63A2\u4E2D\u3002\u901A\u8FC7\u5C06\u8FC7\u53BB\u6570\u5341\u5E74\u79EF\u7D2F\u7684\u591A\u7EF4\u5730\u9707\u6CE2\u6BB5\u6D77\u91CF\u6570\u636E\uFF0C\u8F93\u5165\u6DF1\u5EA6\u5B66\u4E60\u5927\u6A21\u578B\uFF0CAI\u80FD\u81EA\u52A8\u5254\u9664\u6742\u6CE2\u5E72\u6270\u5E76\u5FEB\u901F\u6784\u5EFA\u51FA\u9AD8\u7CBE\u5EA6\u4E09\u7EF4\u5730\u5C42\u89E3\u6784\u6A21\u578B\u3002\u8BE5\u6280\u672F\u7684\u5E94\u7528\u4F7F\u5730\u4E0B\u591A\u4ECB\u8D28\u8BC6\u522B\u7CBE\u5EA6\u8FBE\u5386\u53F2\u65B0\u9AD8\uFF0C\u5F7B\u5E95\u89C4\u907F\u4E86\u4F20\u7EDF\u9AD8\u5BC6\u5EA6\u8BD5\u9A8C\u6253\u4E95\u5BF9\u5730\u8868\u751F\u6001\u7684\u6270\u52A8\uFF0C\u5927\u5E45\u964D\u4F4E\u4E86\u52D8\u5BDF\u6210\u672C\u3002" }, { lang: "ckb", title: "\u06A9\u06C6\u0645\u067E\u0627\u0646\u06CC\u0627 \u0686\u06CC\u0646\u06CC\u06CC\u06D5\u06A9\u0627\u0646 \u0645\u06C6\u062F\u06CE\u0644\u06CC \u062F\u06D5\u0645\u0627\u0631\u06CC \u0698\u06CC\u0631\u06CC \u062F\u06D5\u0633\u062A\u06A9\u0631\u062F \u0628\u06C6 \u0695\u0648\u0648\u067E\u06CE\u0648\u06CC \u0628\u0648\u0648\u0645\u06D5\u0644\u06D5\u0631\u0632\u06D5\u06CC\u06CC \u0644\u06D5 \u0628\u06D5\u0633\u0631\u06D5 \u0628\u06D5\u06A9\u0627\u0631\u062F\u06D5\u0647\u06CE\u0646\u0646", excerpt: "\u0698\u06CC\u0631\u06CC \u062F\u06D5\u0633\u062A\u06A9\u0631\u062F: \u067E\u0695\u06C6\u06AF\u0631\u0627\u0645\u06D5 \u067E\u06CE\u0634\u06A9\u06D5\u0648\u062A\u0648\u0648\u06D5\u06A9\u0627\u0646 \u0646\u06D5\u062E\u0634\u06D5\u06CC \u0632\u06D5\u0648\u06CC \u0628\u06D5 \u0648\u0631\u062F\u06CC \u062F\u06D5\u06A9\u06CE\u0634\u0646 \u0628\u06D5\u0628\u06CE \u067E\u06CE\u0648\u06CC\u0633\u062A\u06CC \u0628\u06D5 \u0644\u06CE\u062F\u0627\u0646\u06CC \u0686\u0627\u06B5 \u0644\u06D5 \u0632\u06D5\u0648\u06CC\u062F\u0627.", content: "\u0628\u06D5\u0633\u0631\u06D5 \u2014 \u0644\u06D5 \u062F\u06D5\u0633\u062A\u06A9\u06D5\u0648\u062A\u06CE\u06A9\u06CC \u0646\u0648\u06CE\u06CC \u0628\u0648\u0627\u0631\u06CC \u062C\u06CC\u06C6\u0644\u06C6\u062C\u06CC\u060C \u0626\u06D5\u0646\u062F\u0627\u0632\u06CC\u0627\u0631\u0627\u0646\u06CC \u0686\u06CC\u0646 \u0644\u06D5 \u0628\u06D5\u0633\u0631\u06D5 \u0628\u06D5 \u0633\u06D5\u0631\u06A9\u06D5\u0648\u062A\u0648\u0648\u06CC\u06CC \u062A\u06C6\u0695\u06D5 \u062F\u06D5\u0645\u0627\u0631\u06CC\u06CC\u06D5 \u062F\u06D5\u0633\u062A\u06A9\u0631\u062F\u06D5\u06A9\u0627\u0646\u06CC\u0627\u0646 \u0628\u06C6 \u0695\u0648\u0648\u067E\u06CE\u0648\u06CC \u0698\u06CE\u0631 \u0632\u06D5\u0648\u06CC \u0628\u06D5\u06A9\u0627\u0631\u0647\u06CE\u0646\u0627 \u0628\u06C6 \u062F\u06C6\u0632\u06CC\u0646\u06D5\u0648\u06D5\u06CC \u0633\u06D5\u0631\u0686\u0627\u0648\u06D5\u06A9\u0627\u0646." }] } } });
