      await prisma.article.create({ data: { slug: artExp2, authorId: author.id, categoryId: catExpo.id, status: "PUBLISHED", imageUrl: "https://images.unsplash.com/photo-1511578314322-379afb476865?q=80&w=1200&auto=format&fit=crop", translations: { create: [{ lang: "en", title: "Iraqi Trade Delegation Secures $420M in Purchase Agreements at 139th Canton Fair", excerpt: "Trade Fairs: Private sector buyers finalize procurement of electrical goods and renewable energy components in Guangzhou.", content: "Guangzhou \u2014 A large delegation of Iraqi private sector importers has successfully concluded negotiations at the 139th Canton Fair in Guangzhou, securing $420 million in purchasing agreements. The procurement contracts focus heavily on modern household appliances, high-grade electrical distribution gear, and solar photovoltaic hardware. Industry leaders noted that direct bank-to-bank settlements in Chinese Yuan greatly accelerated transactions, reducing currency exchange risks for Iraqi traders." }, { lang: "ar", title: "\u0648\u0641\u062F \u062A\u062C\u0627\u0631\u064A \u0639\u0631\u0627\u0642\u064A \u064A\u0636\u0645\u0646 \u0627\u062A\u0641\u0627\u0642\u064A\u0627\u062A \u0634\u0631\u0627\u0621 \u0628\u0642\u064A\u0645\u0629 420 \u0645\u0644\u064A\u0648\u0646 \u062F\u0648\u0644\u0627\u0631 \u0641\u064A \u0645\u0639\u0631\u0636 \u0643\u0627\u0646\u062A\u0648\u0646 \u0627\u0644\u0640 139", excerpt: "\u0627\u0644\u0645\u0639\u0627\u0631\u0636 \u0627\u0644\u062A\u062C\u0627\u0631\u064A\u0629: \u064A\u0646\u0647\u064A \u0645\u0634\u062A\u0631\u064A \u0627\u0644\u0642\u0637\u0627\u0639 \u0627\u0644\u062E\u0627\u0635 \u0639\u0642\u0648\u062F \u062A\u0648\u0631\u064A\u062F \u0627\u0644\u0633\u0644\u0639 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0626\u064A\u0629 \u0648\u0645\u0643\u0648\u0646\u0627\u062A \u0627\u0644\u0637\u0627\u0642\u0629 \u0627\u0644\u0645\u062A\u062C\u062F\u062F\u0629 \u0641\u064A \u063A\u0648\u0627\u0646\u063A\u062A\u0634\u0648.", content: "\u063A\u0648\u0627\u0646\u063A\u062A\u0634\u0648 \u2014 \u0627\u062E\u062A\u062A\u0645 \u0648\u0641\u062F \u0643\u0628\u064A\u0631 \u0645\u0646 \u0645\u0633\u062A\u0648\u0631\u062F\u064A \u0627\u0644\u0642\u0637\u0627\u0639 \u0627\u0644\u062E\u0627\u0635 \u0627\u0644\u0639\u0631\u0627\u0642\u064A \u0628\u0646\u062C\u0627\u062D \u0645\u0641\u0627\u0648\u0636\u0627\u062A\u0647\u0645 \u0641\u064A \u0645\u0639\u0631\u0636 \u0643\u0627\u0646\u062A\u0648\u0646 \u0627\u0644\u0640 139 \u0641\u064A \u063A\u0648\u0627\u0646\u063A\u062A\u0634\u0648\u060C \u062D\u064A\u062B \u062D\u0635\u0644\u0648\u0627 \u0639\u0644\u0649 \u0627\u062A\u0641\u0627\u0642\u064A\u0627\u062A \u0634\u0631\u0627\u0621 \u0628\u0642\u064A\u0645\u0629 420 \u0645\u0644\u064A\u0648\u0646 \u062F\u0648\u0644\u0627\u0631. \u0648\u062A\u0631\u0643\u0632 \u0639\u0642\u0648\u062F \u0627\u0644\u0634\u0631\u0627\u0621 \u0628\u0634\u0643\u0644 \u0645\u0643\u062B\u0641 \u0639\u0644\u0649 \u0627\u0644\u0623\u062C\u0647\u0632\u0629 \u0627\u0644\u0645\u0646\u0632\u0644\u064A\u0629 \u0627\u0644\u062D\u062F\u064A\u062B\u0629\u060C \u0648\u0645\u0639\u062F\u0627\u062A \u0627\u0644\u062A\u0648\u0632\u064A\u0639 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0626\u064A \u0639\u0627\u0644\u064A\u0629 \u0627\u0644\u062C\u0648\u062F\u0629\u060C \u0648\u0645\u0639\u062F\u0627\u062A \u0627\u0644\u0637\u0627\u0642\u0629 \u0627\u0644\u0634\u0645\u0633\u064A\u0629 \u0627\u0644\u0643\u0647\u0631\u0648\u0636\u0648\u0626\u064A\u0629." }, { lang: "zh", title: "\u4F0A\u62C9\u514B\u91C7\u8D2D\u56E2\u5728\u7B2C139\u5C4A\u5E7F\u4EA4\u4F1A\u73B0\u573A\u7B7E\u4E0B\u8FBE4.2\u4EBF\u7F8E\u5143\u91C7\u8D2D\u8BA2\u5355", excerpt: "\u5C55\u4F1A\u52A8\u6001\uFF1A\u5927\u6279\u4F0A\u62C9\u514B\u79C1\u8425\u4F01\u4E1A\u4E70\u5BB6\u5728\u5E7F\u5DDE\u5B8C\u6210\u5BF9\u7535\u529B\u6210\u5957\u8BBE\u5907\u53CA\u65B0\u80FD\u6E90\u5149\u4F0F\u786C\u4EF6\u7EC4\u4EF6\u7684\u76F4\u63A5\u7B7E\u5355\u3002", content: "\u5E7F\u5DDE \u2014 \u4F34\u968F\u7740\u7B2C139\u5C4A\u4E2D\u56FD\u8FDB\u51FA\u53E3\u5546\u54C1\u4EA4\u6613\u4F1A\uFF08\u5E7F\u4EA4\u4F1A\uFF09\u5728\u5E7F\u5DDE\u987A\u5229\u95ED\u5E55\uFF0C\u7531\u767E\u4F59\u5BB6\u4F0A\u62C9\u514B\u6C11\u8425\u9AA8\u5E72\u8FDB\u53E3\u5546\u7EC4\u6210\u7684\u91C7\u8D2D\u56E2\u6210\u679C\u4E30\u7855\uFF0C\u73B0\u573A\u8FBE\u6210\u4E86\u603B\u989D\u7EA64.2\u4EBF\u7F8E\u5143\u7684\u5546\u54C1\u91C7\u8D2D\u8BA2\u5355\u3002\u672C\u6B21\u5927\u5B97\u8BA2\u8D27\u5408\u540C\u4E3B\u8981\u96C6\u4E2D\u5728\u9AD8\u7AEF\u667A\u80FD\u5BB6\u7535\u3001\u9AD8\u7B49\u7EA7\u5DE5\u4E1A\u914D\u7535\u7BB1\u67DC\u3001\u4EE5\u53CA\u53EF\u6EE1\u8DB3\u4E2D\u4E1C\u6781\u7AEF\u9AD8\u6E29\u5DE5\u4F5C\u7684\u5206\u5E03\u5F0F\u5149\u4F0F\u9006\u53D8\u7EC4\u4EF6\u3002" }, { lang: "ckb", title: "\u0634\u0627\u0646\u062F\u06CC \u0639\u06CE\u0631\u0627\u0642 \u0628\u06D5 \u0628\u0695\u06CC \u0664\u0662\u0660 \u0645\u0644\u06CC\u06C6\u0646 \u062F\u06C6\u0644\u0627\u0631 \u0695\u06CE\u06A9\u06A9\u06D5\u0648\u062A\u0646 \u0644\u06D5 \u067E\u06CE\u0634\u0627\u0646\u06AF\u0627\u06CC \u0643\u0627\u0646\u062A\u06C6\u0646 \u0648\u0627\u0698\u06C6 \u062F\u06D5\u06A9\u06D5\u0646", excerpt: "\u067E\u06CC\u0634\u0627\u0646\u06AF\u0627\u06CC \u0628\u0627\u0632\u0631\u06AF\u0627\u0646\u06CC: \u0628\u0627\u0632\u0631\u06AF\u0627\u0646\u0627\u0646\u06CC \u06A9\u06D5\u0631\u062A\u06CC \u062A\u0627\u06CC\u0628\u06D5\u062A\u06CC \u0639\u06CE\u0631\u0627\u0642 \u06AF\u0631\u06CE\u0628\u06D5\u0633\u062A\u06CC \u06AF\u06D5\u0648\u0631\u06D5\u06CC \u06A9\u0695\u06CC\u0646\u06CC \u06A9\u06D5\u0644\u0648\u067E\u06D5\u0644\u06CC \u0648\u0632\u06D5\u06CC \u062E\u06C6\u0631 \u0644\u06D5 \u06AF\u0648\u0627\u0646\u06AF\u0698\u06C6 \u0626\u06D5\u0646\u062C\u0627\u0645 \u062F\u06D5\u062F\u06D5\u0646.", content: "\u06AF\u0648\u0627\u0646\u06AF\u0698\u06C6 \u2014 \u0634\u0627\u0646\u062F\u06CE\u06A9\u06CC \u06AF\u06D5\u0648\u0631\u06D5\u06CC \u0628\u0627\u0632\u0631\u06AF\u0627\u0646\u0627\u0646\u06CC \u06A9\u06D5\u0631\u062A\u06CC \u062A\u0627\u06CC\u0628\u06D5\u062A\u06CC \u0639\u06CE\u0631\u0627\u0642 \u062A\u0648\u0627\u0646\u06CC\u0627\u0646 \u0644\u06D5 \u0661\u0663\u0669\u0647\u06D5\u0645\u06CC\u0646 \u067E\u06CE\u0634\u0627\u0646\u06AF\u0627\u06CC \u0646\u06CE\u0648\u062F\u06D5\u0648\u06B5\u06D5\u062A\u06CC \u0643\u0627\u0646\u062A\u06C6\u0646 \u0644\u06D5 \u06AF\u0648\u0627\u0646\u06AF\u0698\u06C6\u060C \u0628\u06D5 \u0628\u0695\u06CC \u0664\u0662\u0660 \u0645\u0644\u06CC\u06C6\u0646 \u062F\u06C6\u0644\u0627\u0631 \u06AF\u0631\u06CE\u0628\u06D5\u0633\u062A\u06CC \u06A9\u0695\u06CC\u0646 \u0648\u0627\u0698\u06C6 \u0628\u06A9\u06D5\u0646." }] } } });
