  const category = categories[idx % categories.length];
  const titles = { 26: { en: "The Grand Strategy of Emperor Taizong and the Abbasid Caliphs", ar: "\u0627\u0644\u0627\u0633\u062A\u0631\u0627\u062A\u064A\u062C\u064A\u0629 \u0627\u0644\u0643\u0628\u0631\u0649 \u0644\u0644\u0625\u0645\u0628\u0631\u0627\u0637\u0648\u0631 \u062A\u0627\u064A\u0632\u0648\u0646\u063A \u0648\u0627\u0644\u062E\u0644\u0641\u0627\u0621 \u0627\u0644\u0639\u0628\u0627\u0633\u064A\u064A\u0646", zh: "\u5510\u592A\u5B97\u4E0E\u963F\u62D4\u65AF\u54C8\u91CC\u53D1\u7684\u6CBB\u56FD\u8C0B\u7565", ckb: "\u0633\u062A\u0631\u0627\u062A\u06CC\u0698\u06CC\u06D5\u062A\u06CC \u06AF\u06D5\u0648\u0631\u06D5\u06CC \u0626\u06CC\u0645\u067E\u0631\u0627\u062A\u06C6\u0631 \u062A\u0627\u06CC\u062A\u0632\u06C6\u0646\u06AF \u0648 \u062E\u06D5\u0644\u06CC\u0641\u06D5\u06A9\u0627\u0646\u06CC \u0639\u06D5\u0628\u0627\u0633\u06CC" }, 27: { en: "Kurdish Rugs and Weaving Traditions of the Zagros", ar: "\u0627\u0644\u0633\u062C\u0627\u062F \u0627\u0644\u0643\u0631\u062F\u064A \u0648\u062A\u0642\u0627\u0644\u064A\u062F \u0627\u0644\u0646\u0633\u062C \u0641\u064A \u062C\u0628\u0627\u0644 \u0632\u0627\u06AF\u0631\u0648\u0633", zh: "\u624E\u683C\u7F57\u65AF\u5C71\u8109\u7684\u5E93\u5C14\u5FB7\u5730\u6BEF\u4E0E\u624B\u5DE5\u7EC7\u9020\u827A\u672F", ckb: "\u0628\u06D5\u0631\u0645\u0627\u06B5 \u0648 \u0641\u06D5\u0631\u0634\u06CC \u06A9\u0648\u0631\u062F\u06CC \u0648 \u0647\u0648\u0646\u06D5\u0631\u06CC \u062F\u0631\u0648\u0633\u062A\u06A9\u0631\u062F\u0646 \u0644\u06D5 \u0632\u0627\u06AF\u0631\u06C6\u0633" }, 28: { en: "The Baghdad School of Translation: Hunayn ibn Ishaq to Modern Times", ar: "\u0645\u062F\u0631\u0633\u0629 \u0628\u063A\u062F\u0627\u062F \u0644\u0644\u062A\u0631\u062C\u0645\u0629: \u0645\u0646 \u062D\u0646\u064A\u0646 \u0628\u0646 \u0625\u0633\u062D\u0627\u0642 \u0625\u0644\u0649 \u0627\u0644\u0639\u0635\u0631 \u0627\u0644\u062D\u062F\u064A\u062B", zh: "\u5DF4\u683C\u8FBE\u7FFB\u8BD1\u5B66\u6D3E\uFF1A\u4ECE\u963F\u5B81\xB7\u672C\xB7\u4F0A\u65AF\u54C8\u683C\u5230\u5F53\u4EE3", ckb: "\u0642\u0648\u062A\u0627\u0628\u062E\u0627\u0646\u06D5\u06CC \u0628\u06D5\u063A\u062F\u0627\u062F \u0628\u06C6 \u0648\u06D5\u0631\u06AF\u06CE\u0695\u0627\u0646: \u0644\u06D5 \u062D\u0648\u0646\u06D5\u06CC\u0646\u06CC \u06A9\u0648\u0695\u06CC \u0626\u06CC\u0633\u062D\u0627\u0642\u06D5\u0648\u06D5 \u062A\u0627 \u0645\u06C6\u062F\u06CE\u0631\u0646" }, 29: { en: "Port of Faw: Connecting the Persian Gulf to Europe and China", ar: "\u0645\u064A\u0646\u0627\u0621 \u0627\u0644\u0641\u0627\u0648 \u0627\u0644\u0643\u0628\u064A\u0631: \u0631\u0628\u0637 \u0627\u0644\u062E\u0644\u064A\u062C \u0627\u0644\u0639\u0631\u0628\u064A \u0628\u0623\u0648\u0631\u0648\u0628\u0627 \u0648\u0627\u0644\u0635\u064A\u0646", zh: "\u6CD5\u5965\u5927\u6E2F\uFF1A\u8FDE\u63A5\u6D77\u6E7E\u3001\u6B27\u6D32\u4E0E\u4E2D\u56FD\u7684\u5927\u901A\u9053", ckb: "\u0628\u06D5\u0646\u062F\u06D5\u0631\u06CC \u06AF\u06D5\u0648\u0631\u06D5\u06CC \u0641\u0627\u0648: \u0628\u06D5\u0633\u062A\u0646\u06D5\u0648\u06D5\u06CC \u06A9\u06D5\u0646\u062F\u0627\u0648 \u0628\u06D5 \u0626\u06D5\u0648\u0631\u0648\u067E\u0627 \u0648 \u0686\u06CC\u0646" }, 30: { en: "The Modernity of Confucius: Business Ethics in Bilateral Trade", ar: "\u062D\u062F\u0627\u062B\u0629 \u0643\u0646\u0641\u0648\u0634\u064A\u0648\u0633: \u0623\u062E\u0644\u0627\u0642\u064A\u0627\u062A \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0641\u064A \u0627\u0644\u062A\u062C\u0627\u0631\u0629 \u0627\u0644\u062B\u0646\u0627\u0626\u064A\u0629", zh: "\u5B54\u5B50\u7684\u73B0\u4EE3\u610F\u4E49\uFF1A\u53CC\u8FB9\u8D38\u6613\u4E2D\u7684\u5546\u4E1A\u4F26\u7406", ckb: "\u0646\u0648\u06CE\u062E\u0648\u0627\u0632\u06CC \u06A9\u06C6\u0646\u0641\u06C6\u0634\u06CC\u06C6\u0633: \u0626\u06D5\u062E\u0644\u0627\u0642\u06CC \u0628\u0627\u0632\u0631\u06AF\u0627\u0646\u06CC \u0644\u06D5 \u0626\u0627\u06B5\u0648\u06AF\u06C6\u0695\u062F\u0627" }, 31: { en: "Erbil to Guangzhou: Stories of Sino-Kurdish Merchants", ar: "\u0645\u0646 \u0623\u0631\u0628\u064A\u0644 \u0625\u0644\u0649 \u063A\u0648\u0627\u0646\u063A\u062C\u0648: \u0642\u0635\u0635 \u0627\u0644\u062A\u062C\u0627\u0631 \u0627\u0644\u0643\u0631\u062F \u0648\u0627\u0644\u0635\u064A\u0646\u064A\u064A\u0646", zh: "\u4ECE\u57C3\u5C14\u6BD4\u52D2\u5230\u5E7F\u5DDE\uFF1A\u4E2D\u5E93\u5546\u4EBA\u7684\u4F20\u5947\u6545\u4E8B", ckb: "\u0644\u06D5 \u0647\u06D5\u0648\u0644\u06CE\u0631\u06D5\u0648\u06D5 \u0628\u06C6 \u06AF\u0648\u0627\u0646\u06AF\u0698\u06C6: \u0628\u06D5\u0633\u06D5\u0631\u0647\u0627\u062A\u06CC \u0628\u0627\u0632\u0631\u06AF\u0627\u0646\u0627\u0646\u06CC \u06A9\u0648\u0631\u062F \u0648 \u0686\u06CC\u0646\u06CC" }, 32: { en: "Oil, Gas, and Power Grids: Reconstruction in Post-ISIS Iraq", ar: "\u0627\u0644\u0646\u0641\u0637 \u0648\u0627\u0644\u063A\u0627\u0632 \u0648\u0634\u0628\u0643\u0627\u062A \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0621: \u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u0625\u0639\u0645\u0627\u0631 \u0641\u064A \u0639\u0631\u0627\u0642 \u0645\u0627 \u0628\u0639\u062F \u062F\u0627\u0639\u0634", zh: "\u77F3\u6CB9\u3001\u5929\u7136\u6C14\u4E0E\u7535\u7F51\uFF1A\u540E\u4F0A\u65AF\u5170\u56FD\u65F6\u4EE3\u4F0A\u62C9\u514B\u7684\u91CD\u5EFA", ckb: "\u0646\u06D5\u0648\u062A \u0648 \u06AF\u0627\u0632 \u0648 \u06A9\u0627\u0631\u06D5\u0628\u0627: \u0626\u0627\u0648\u06D5\u062F\u0627\u0646\u06A9\u0631\u062F\u0646\u06D5\u0648\u06D5\u06CC \u0639\u06CE\u0631\u0627\u0642\u06CC \u067E\u0627\u0634 \u062F\u0627\u0639\u0634" }, 33: { en: "Poetry and Patriotism in Modern Kurdish Resistance", ar: "\u0627\u0644\u0634\u0639\u0631 \u0627\u0644\u0648\u0637\u0646\u064A\u0629 \u0641\u064A \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u0627\u0644\u0643\u0631\u062F\u064A\u0629 \u0627\u0644\u062D\u062F\u064A\u062B\u0629", zh: "\u73B0\u4EE3\u5E93\u5C14\u5FB7\u62B5\u6297\u529B\u91CF\u4E2D\u7684\u8BD7\u6B4C\u4E0E\u7231\u56FD\u60C5\u6000", ckb: "\u0634\u06CC\u0639\u0631 \u0648 \u0646\u06CC\u0634\u062A\u0645\u0627\u0646\u067E\u06D5\u0631\u0648\u06D5\u0631\u06CC \u0644\u06D5 \u0628\u06D5\u0631\u06D5\u0646\u06AF\u0627\u0631\u0628\u0648\u0648\u0646\u06D5\u0648\u06D5\u06CC \u06A9\u0648\u0631\u062F\u06CC" }, 34: { en: "Ancient Silk Routes: Jade, Lapis Lazuli, and Incense", ar: "\u0637\u0631\u0642 \u0627\u0644\u062D\u0631\u064A\u0631 \u0627\u0644\u0642\u062F\u064A\u0645\u0629: \u0627\u0644\u064A\u0634\u0645 \u0648\u0627\u0644\u0644\u0627\u0632\u0648\u0631\u062F \u0648\u0627\u0644\u0628\u062E\u0648\u0631", zh: "\u53E4\u4EE3\u4E1D\u7EF8\u4E4B\u8DEF\uFF1A\u7389\u77F3\u3001\u9752\u91D1\u77F3\u4E0E\u9999\u6599\u8003", ckb: "\u0695\u06CE\u06AF\u0627 \u06A9\u06C6\u0646\u06D5\u06A9\u0627\u0646\u06CC \u0626\u0627\u0648\u0631\u06CC\u0634\u0645: \u0632\u06CE\u0695 \u0648 \u0644\u0627\u062C\u0648\u06D5\u0631\u062F \u0648 \u0628\u06C6\u0646\u0648\u0628\u06D5\u0631\u0627\u0645" }, 35: { en: "Diplomacy on the Tigris: Foreign Embassies in Baghdad (1921-2025)", ar: "\u0627\u0644\u062F\u0628\u0644\u0648\u0645\u0627\u0633\u064A\u0629 \u0639\u0644\u0649 \u062F\u062C\u0644\u0629: \u0627\u0644\u0633\u0641\u0627\u0631\u0627\u062A \u0627\u0644\u0623\u062C\u0646\u0628\u064A\u0629 \u0641\u064A \u0628\u063A\u062F\u0627\u062F", zh: "\u5E95\u683C\u91CC\u65AF\u6CB3\u7554\u7684\u5916\u4EA4\uFF1A\u5DF4\u683C\u8FBE\u9A7B\u5916\u4F7F\u9986\u767E\u5E74", ckb: "\u062F\u06CC\u067E\u0644\u06C6\u0645\u0627\u0633\u06CC \u0644\u06D5\u0633\u06D5\u0631 \u0695\u0648\u0648\u0628\u0627\u0631\u06CC \u062F\u062C\u0644\u06D5: \u0628\u0627\u06B5\u06CC\u06C6\u0632\u062E\u0627\u0646\u06D5 \u0646\u06CE\u0648\u062F\u06D5\u0648\u06B5\u06D5\u062A\u06CC\u06CC\u06D5\u06A9\u0627\u0646" }, 36: { en: "Kurdish Mountain Citadel Warfare: From Saladin to Peshmerga", ar: "\u062D\u0631\u0648\u0628 \u0627\u0644\u0642\u0644\u0627\u0639 \u0627\u0644\u062C\u0628\u0644\u064A\u0629 \u0627\u0644\u0643\u0631\u062F\u064A\u0629: \u0645\u0646 \u0635\u0644\u0627\u062D \u0627\u0644\u062F\u064A\u0646 \u0625\u0644\u0649 \u0627\u0644\u0628\u064A\u0634\u0645\u0631\u0643\u0629", zh: "\u5E93\u5C14\u5FB7\u5C71\u5730\u57CE\u5821\u8981\u585E\u6218\u53F2\uFF1A\u4ECE\u8428\u62C9\u4E01\u5230\u4F69\u4EC0\u6885\u683C", ckb: "\u062C\u06D5\u0646\u06AF\u06CC \u0642\u06D5\u06B5\u0627\u06A9\u0627\u0646\u06CC \u0632\u0627\u06AF\u0631\u06C6\u0633: \u0644\u06D5 \u0633\u06D5\u0644\u0627\u062D\u06D5\u062F\u06CC\u0646\u06D5\u0648\u06D5 \u062A\u0627 \u067E\u06CE\u0634\u0645\u06D5\u0631\u06AF\u06D5" }, 37: { en: "The Tang Dynasty and the Abbasid Caliphate: The Battle of Talas", ar: "\u0633\u0644\u0627\u0644\u0629 \u062A\u0627\u0646\u063A \u0648\u0627\u0644\u062E\u0644\u0627\u0641\u0629 \u0627\u0644\u0639\u0628\u0627\u0633\u064A\u0629: \u0645\u0639\u0631\u0643\u0629 \u0637\u0644\u0627\u0633 \u0648\u0627\u0644\u0645\u0628\u0627\u062F\u0644 \u0627\u0644\u0648\u0631\u0642\u064A\u0629", zh: "\u5927\u5510\u4E0E\u963F\u62D4\u65AF\u738B\u671D\uFF1A\u601B\u7F57\u65AF\u4E4B\u6218\u4E0E\u9020\u7EB8\u672F\u897F\u4F20", ckb: "\u0633\u06D5\u0631\u062F\u06D5\u0645\u06CC \u062A\u0627\u0646\u06AF \u0648 \u062E\u06D5\u0644\u0627\u0641\u06D5\u062A\u06CC \u0639\u06D5\u0628\u0627\u0633\u06CC: \u062C\u06D5\u0646\u06AF\u06CC \u062A\u06D5\u0644\u0627\u0633" }, 38: { en: "Agriculture and Irrigation in Ancient and Modern Sumer", ar: "\u0627\u0644\u0632\u0631\u0627\u0639\u0629 \u0648\u0627\u0644\u0631\u064A \u0641\u064A \u0633\u0648\u0645\u0631 \u0627\u0644\u0642\u062F\u064A\u0645\u0629 \u0648\u0627\u0644\u062D\u062F\u064A\u062B\u0629", zh: "\u53E4\u4ECA\u82CF\u7F8E\u5C14\u5730\u533A\u7684\u6C34\u5229\u4E0E\u519C\u4E1A\u6F14\u8FDB", ckb: "\u06A9\u0634\u062A\u0648\u06A9\u0627\u06B5 \u0648 \u0626\u0627\u0648\u062F\u06CE\u0631\u06CC \u0644\u06D5 \u0633\u0648\u0645\u06D5\u0631\u06CC \u06A9\u06C6\u0646 \u0648 \u0645\u06C6\u062F\u06CE\u0631\u0646\u062F\u0627" }, 39: { en: "China's High-Speed Rail Tech: Feasibility for Iraq's Dry Canal", ar: "\u062A\u0643\u0646\u0648\u0644\u0648\u062C\u064A\u0627 \u0627\u0644\u0642\u0637\u0627\u0631\u0627\u062A \u0627\u0644\u0635\u064A\u0646\u064A\u0629 \u0627\u0644\u0641\u0627\u0626\u0642\u0629 \u0627\u0644\u0633\u0631\u0639\u0629: \u0627\u0644\u0642\u0646\u0627\u0629 \u0627\u0644\u062C\u0627\u0641\u0629 \u0627\u0644\u0639\u0631\u0627\u0642\u064A\u0629", zh: "\u4E2D\u56FD\u9AD8\u94C1\u6280\u672F\u4E0E\u4F0A\u62C9\u514B\u201C\u5E72\u8FD0\u6CB3\u201D\u94C1\u8DEF\u6218\u7565", ckb: "\u062A\u06D5\u06A9\u0646\u06D5\u0644\u06C6\u0698\u06CC\u0627\u06CC \u0634\u06D5\u0645\u06D5\u0646\u062F\u06D5\u0641\u06D5\u0631\u06CC \u062E\u06CE\u0631\u0627 \u0648 \u067E\u0695\u06C6\u0698\u06D5\u06CC \u06A9\u06D5\u0646\u0627\u06B5\u06CC \u0648\u0634\u06A9\u0627\u0646\u06CC \u0639\u06CE\u0631\u0627\u0642" }, 40: { en: "Kurdish Dialects and Lexicography: Sorani, Kurmanji, and Gorani", ar: "\u0627\u0644\u0644\u0647\u062C\u0627\u062A \u0627\u0644\u0643\u0631\u062F\u064A\u0629 \u0648\u0627\u0644\u0645\u0639\u0627\u062C\u0645: \u0627\u0644\u0633\u0648\u0631\u0627\u0646\u064A\u0629 \u0648\u0627\u0644\u0643\u0631\u0645\u0627\u0646\u062C\u064A\u0629 \u0648\u0627\u0644\u063A\u0648\u0631\u0627\u0646\u064A\u0629", zh: "\u5E93\u5C14\u5FB7\u8BED\u65B9\u8A00\u4E0E\u8BCD\u5178\u5B66\uFF1A\u7D22\u62C9\u5C3C\u3001\u5E93\u5C14\u66FC\u5409\u4E0E\u6208\u62C9\u5C3C", ckb: "\u0632\u0627\u0631\u0627\u0648\u06D5\u06A9\u0627\u0646\u06CC \u0632\u0645\u0627\u0646\u06CC \u06A9\u0648\u0631\u062F\u06CC: \u0633\u06C6\u0631\u0627\u0646\u06CC\u060C \u06A9\u0648\u0631\u0645\u0627\u0646\u062C\u06CC \u0648 \u06AF\u06C6\u0631\u0627\u0646\u06CC" }, 41: { en: "Preserving Cuneiform: Digital Archiving at the Iraq Museum", ar: "\u062D\u0641\u0638 \u0627\u0644\u0645\u0633\u0645\u0627\u0631\u064A\u0629: \u0627\u0644\u0623\u0631\u0634\u0641\u0629 \u0627\u0644\u0631\u0642\u0645\u064A\u0629 \u0641\u064A \u0627\u0644\u0645\u062A\u062D\u0641 \u0627\u0644\u0639\u0631\u0627\u0642\u064A", zh: "\u6954\u5F62\u6587\u5B57\u5B88\u62A4\u8BA1\u5212\uFF1A\u4F0A\u62C9\u514B\u56FD\u5BB6\u535A\u7269\u9986\u7684\u6570\u5B57\u590D\u5174", ckb: "\u067E\u0627\u0631\u0627\u0633\u062A\u0646\u06CC \u0646\u0648\u0648\u0633\u06CC\u0646\u06CC \u0628\u0632\u0645\u0627\u0631\u06CC: \u0626\u06D5\u0631\u0634\u06CC\u0641\u06CC \u062F\u06CC\u062C\u06CC\u062A\u0627\u06B5\u06CC \u0644\u06D5 \u0645\u06C6\u0632\u06D5\u062E\u0627\u0646\u06D5\u06CC \u0639\u06CE\u0631\u0627\u0642" }, 42: { en: "Sino-Gulf Energy Partnerships in the 21st Century", ar: "\u0627\u0644\u0634\u0631\u0627\u0643\u0627\u062A \u0627\u0644\u0646\u0645\u0637\u064A\u0629 \u0628\u064A\u0646 \u0627\u0644\u0635\u064A\u0646 \u0648\u0627\u0644\u062E\u0644\u064A\u062C \u0641\u064A \u0627\u0644\u0642\u0631\u0646 \u0627\u0644\u062D\u0627\u062F\u064A \u0648\u0627\u0644\u0639\u0634\u0631\u064A\u0646", zh: "21\u4E16\u7EAA\u4E2D\u56FD\u4E0E\u6D77\u6E7E\u56FD\u5BB6\u7684\u80FD\u6E90\u6218\u7565\u4F19\u4F34\u5173\u7CFB", ckb: "\u0647\u0627\u0648\u0628\u06D5\u0634\u06CC\u06CC\u06D5\u06A9\u0627\u0646\u06CC \u0648\u0632\u06D5 \u0644\u06D5 \u0646\u06CE\u0648\u0627\u0646 \u0686\u06CC\u0646 \u0648 \u06A9\u06D5\u0646\u062F\u0627\u0648" }, 43: { en: "Kurdish Cinema: Y\u0131lmaz G\xFCney and the New Wave Directors", ar: "\u0627\u0644\u0633\u064A\u0646\u0645\u0627 \u0627\u0644\u0643\u0631\u062F\u064A\u0629: \u064A\u0644\u0645\u0627\u0632 \u063A\u0648\u0646\u064A \u0648\u0645\u062E\u0631\u062C\u0648 \u0627\u0644\u0645\u0648\u062C\u0629 \u0627\u0644\u062C\u062F\u064A\u062F\u0629", zh: "\u5E93\u5C14\u5FB7\u7535\u5F71\u827A\u672F\uFF1A\u4F9D\u5C14\u9A6C\u5179\xB7\u53E4\u5C3C\u4E0E\u65B0\u6D6A\u6F6E\u5BFC\u6F14", ckb: "\u0633\u06CC\u0646\u06D5\u0645\u0627\u06CC \u06A9\u0648\u0631\u062F\u06CC: \u06CC\u06D5\u06B5\u0645\u0627\u0632 \u06AF\u06C6\u0646\u06CC \u0648 \u062F\u06D5\u0631\u0647\u06CE\u0646\u06D5\u0631\u0627\u0646\u06CC \u0633\u06D5\u0631\u062F\u06D5\u0645" }, 44: { en: "The Architecture of Minarets: From Samarra to Xi'an Great Mosque", ar: "\u0639\u0645\u0627\u0631\u0629 \u0627\u0644\u0645\u0622\u0630\u0646: \u0645\u0646 \u0645\u0644\u0648\u064A\u0629 \u0633\u0627\u0645\u0631\u0627\u0621 \u0625\u0644\u0649 \u0645\u0633\u062C\u062F \u0634\u064A\u0622\u0646 \u0627\u0644\u0643\u0628\u064A\u0631", zh: "\u5BA3\u793C\u5854\u5EFA\u7B51\u827A\u672F\uFF1A\u4ECE\u8428\u9A6C\u62C9\u72EC\u6728\u5854\u5230\u897F\u5B89\u5927\u6E05\u771F\u5BFA", ckb: "\u062A\u06D5\u0644\u0627\u0631\u0633\u0627\u0632\u06CC \u0645\u0646\u0627\u0631\u06D5\u06A9\u0627\u0646: \u0644\u06D5 \u0645\u06D5\u0644\u06D5\u0648\u06CC\u06CC\u06D5\u06CC \u0633\u0627\u0645\u06D5\u0695\u0627\u0648\u06D5 \u062A\u0627 \u0645\u0632\u06AF\u06D5\u0648\u062A\u06CC \u0634\u06CC\u0626\u0627\u0646" }, 45: { en: "Dams of Mesopotamia: Mosul, Dukan, and Darbandikhan", ar: "\u0633\u062F\u0648\u062F \u0628\u0644\u0627\u062F \u0627\u0644\u0631\u0627\u0641\u062F\u064A\u0646: \u0627\u0644\u0645\u0648\u0635\u0644 \u0648\u062F\u0648\u0643\u0627\u0646 \u0648\u062F\u0631\u064E\u0628\u0646\u062F\u0650\u062E\u0627\u0646", zh: "\u4E24\u6CB3\u6D41\u57DF\u7684\u5927\u575D\u5EFA\u8BBE\uFF1A\u6469\u82CF\u5C14\u3001\u675C\u574E\u4E0E\u8FBE\u5C14\u73ED\u8FEA\u6C57", ckb: "\u0628\u06D5\u0646\u062F\u0627\u0648\u06D5\u06A9\u0627\u0646\u06CC \u0645\u06CC\u0633\u06C6\u067E\u06C6\u062A\u0627\u0645\u06CC\u06CC\u0627: \u0645\u0648\u0648\u0633\u06B5\u060C \u062F\u0648\u0648\u06A9\u0627\u0646 \u0648 \u062F\u06D5\u0631\u0628\u06D5\u0646\u062F\u06CC\u062E\u0627\u0646" }, 46: { en: "China's Peacekeeping Missions in the Middle East & Africa", ar: "\u0645\u0647\u0627\u0645 \u062D\u0641\u0638 \u0627\u0644\u0633\u0644\u0627\u0645 \u0627\u0644\u0635\u064A\u0646\u064A\u0629 \u0641\u064A \u0627\u0644\u0634\u0631\u0642 \u0627\u0644\u0623\u0648\u0633\u0637 \u0648\u0623\u0641\u0631\u064A\u0642\u064A\u0627", zh: "\u4E2D\u56FD\u5728\u4E2D\u4E1C\u4E0E\u975E\u6D32\u7684\u8054\u5408\u56FD\u7EF4\u548C\u884C\u52A8", ckb: "\u0626\u06D5\u0631\u06A9\u06D5\u06A9\u0627\u0646\u06CC \u0626\u0627\u0634\u062A\u06CC\u067E\u0627\u0631\u06CE\u0632\u06CC \u0686\u06CC\u0646 \u0644\u06D5 \u0695\u06C6\u0698\u0647\u06D5\u06B5\u0627\u062A\u06CC \u0646\u0627\u0648\u06D5\u0695\u0627\u0633\u062A" }, 47: { en: "The Musical Heritage of Maqam: Baghdad and Uyghur Muqam", ar: "\u0627\u0644\u062A\u0631\u0627\u062B \u0627\u0644\u0645\u0648\u0633\u064A\u0642\u064A \u0644\u0644\u0645\u0642\u0627\u0645: \u0645\u0642\u0627\u0645 \u0628\u063A\u062F\u0627\u062F \u0648\u0627\u0644\u0645\u0642\u0627\u0645 \u0627\u0644\u0623\u0648\u064A\u063A\u0648\u0631\u064A", zh: "\u6728\u5361\u59C6\u4E0E\u9EA6\u5361\u59C6\u97F3\u4E50\u9057\u4EA7\uFF1A\u5DF4\u683C\u8FBE\u4E0E\u65B0\u7586\u6728\u5361\u59C6\u4E4B\u5BF9\u6BD4", ckb: "\u06A9\u06D5\u0644\u06D5\u067E\u0648\u0648\u0631\u06CC \u0645\u06C6\u0633\u06CC\u0642\u0627\u06CC \u0645\u06D5\u0642\u0627\u0645: \u0645\u06D5\u0642\u0627\u0645\u06CC \u0628\u06D5\u063A\u062F\u0627\u062F\u06CC \u0648 \u0645\u06D5\u0642\u0627\u0645\u06CC \u0686\u06CC\u0646\u06CC" }, 48: { en: "The Reconstruction of Mosul: Old City Restoration Protocols", ar: "\u0625\u0639\u0627\u062F\u0629 \u0625\u0639\u0645\u0627\u0631 \u0627\u0644\u0645\u0648\u0635\u0644: \u0628\u0631\u0648\u062A\u0648\u0643\u0648\u0644\u0627\u062A \u062A\u0631\u0645\u064A\u0645 \u0627\u0644\u0645\u062F\u064A\u0646\u0629 \u0627\u0644\u0642\u062F\u064A\u0645\u0629", zh: "\u6469\u82CF\u5C14\u53E4\u57CE\u91CD\u5EFA\u4E0E\u8054\u5408\u56FD\u9057\u4EA7\u590D\u5174\u7EAA\u5B9E", ckb: "\u0626\u0627\u0648\u06D5\u062F\u0627\u0646\u06A9\u0631\u062F\u0646\u06D5\u0648\u06D5\u06CC \u0645\u0648\u0648\u0633\u06B5: \u06A9\u06C6\u0646\u062A\u0695\u06C6\u06B5 \u0648 \u0646\u06C6\u0698\u06D5\u0646\u06A9\u0631\u062F\u0646\u06D5\u0648\u06D5\u06CC \u0634\u0627\u0631\u06D5 \u06A9\u06C6\u0646\u06D5\u06A9\u06D5" }, 49: { en: "Kurdish Rug Motifs: Symbolism and Tribal Heritage", ar: "\u0631\u0645\u0648\u0632 \u0627\u0644\u0633\u062C\u0627\u062F \u0627\u0644\u0643\u0631\u062F\u064A: \u0627\u0644\u0631\u0645\u0632\u064A\u0629 \u0648\u0627\u0644\u062A\u0631\u0627\u062B \u0627\u0644\u0639\u0634\u0627\u0626\u0631\u064A", zh: "\u5E93\u5C14\u5FB7\u6302\u6BEF\u56FE\u817E\uFF1A\u7B26\u53F7\u5B66\u4E0E\u90E8\u843D\u6587\u5316\u4F20\u627F", ckb: "\u0647\u06CE\u0645\u0627 \u0648 \u0646\u06D5\u062E\u0634\u06D5\u06A9\u0627\u0646\u06CC \u0641\u06D5\u0631\u0634\u06CC \u06A9\u0648\u0631\u062F\u06CC: \u0695\u06D5\u0645\u0632\u06D5\u06A9\u0627\u0646\u06CC \u06A9\u06D5\u0644\u06D5\u067E\u0648\u0648\u0631" }, 50: { en: "Sino-Iraqi Strategic Partnership: 2025 and Beyond", ar: "\u0627\u0644\u0634\u0631\u0627\u0643\u0629 \u0627\u0644\u0627\u0633\u062A\u0631\u0627\u062A\u064A\u062C\u064A\u0629 \u0628\u064A\u0646 \u0627\u0644\u0639\u0631\u0627\u0642 \u0648\u0627\u0644\u0635\u064A\u0646: 2025 \u0648\u0645\u0627 \u0628\u0639\u062F\u0647\u0627", zh: "\u4E2D\u4F0A\u6218\u7565\u4F19\u4F34\u5173\u7CFB\u5C55\u671B\uFF1A2025\u53CA\u672A\u6765\u4E4B\u8DEF", ckb: "\u0647\u0627\u0648\u0628\u06D5\u0634\u06CC \u0633\u062A\u0631\u0627\u062A\u06CC\u0698\u06CC \u0639\u06CE\u0631\u0627\u0642 \u0648 \u0686\u06CC\u0646: \u0662\u0660\u0662\u0665 \u0648 \u062F\u0627\u0647\u0627\u062A\u0648\u0648" } }[idx] || { en: `Volume ${idx} on Regional Studies`, ar: `\u0627\u0644\u0645\u062C\u0644\u062F ${idx} \u062D\u0648\u0644 \u0627\u0644\u062F\u0631\u0627\u0633\u0627\u062A \u0627\u0644\u0625\u0642\u0644\u064A\u0645\u064A\u0629`, zh: `\u533A\u57DF\u7814\u7A76\u4E1B\u4E66\u7B2C ${idx} \u5377`, ckb: `\u0628\u06D5\u0631\u06AF\u06CC ${idx} \u0644\u06D5\u0633\u06D5\u0631 \u062A\u0648\u06CE\u0698\u06CC\u0646\u06D5\u0648\u06D5\u06A9\u0627\u0646` };
