var ALL_CHINESE_PRODUCTS = [{ titleEn: "BYD Song Plus EV & PHEV Crossover", titleAr: "\u0628\u064A \u0648\u0627\u064A \u062F\u064A \u0633\u0648\u0646\u063A \u0628\u0644\u0633 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0626\u064A\u0629 \u0648\u0627\u0644\u0647\u062C\u064A\u0646\u0629", titleZh: "\u6BD4\u4E9A\u8FEA\u5B8BPLUS\u65B0\u80FD\u6E90\u667A\u80FDSUV", titleCkb: "\u0628\u06CC \u0648\u0627\u06CC \u062F\u06CC \u0633\u06C6\u0646\u06AF \u067E\u0644\u06D5\u0633 \u06A9\u0627\u0631\u06D5\u0628\u0627\u06CC\u06CC \u0648 \u0647\u0627\u06CC\u0628\u0631\u06CC\u062F", descriptionEn: "The leading smart electric crossover in Iraq's expanding clean energy automotive market, featuring ultra-safe Blade Battery technology and 605km extended range.", descriptionAr: "\u0627\u0644\u0643\u0631\u0648\u0633 \u0623\u0648\u0641\u0631 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0626\u064A \u0627\u0644\u0630\u0643\u064A \u0627\u0644\u0623\u0643\u062B\u0631 \u0637\u0644\u0628\u0627\u064B \u0641\u064A \u0633\u0648\u0642 \u0627\u0644\u0633\u064A\u0627\u0631\u0627\u062A \u0627\u0644\u0639\u0631\u0627\u0642\u064A\u060C \u0645\u062F\u0639\u0648\u0645 \u0628\u062A\u0642\u0646\u064A\u0629 \u0628\u0637\u0627\u0631\u064A\u0629 Blade \u0627\u0644\u0641\u0627\u0626\u0642\u0629 \u0627\u0644\u0623\u0645\u0627\u0646 \u0648\u0645\u062F\u0649 \u0642\u064A\u0627\u062F\u0629 \u064A\u0635\u0644 \u0625\u0644\u0649 605 \u0643\u0645.", descriptionZh: "\u4F0A\u62C9\u514B\u65B0\u80FD\u6E90\u6C7D\u8F66\u5E02\u573A\u7545\u9500\u699C\u9996\u7684\u667A\u80FD\u7D27\u51D1\u578BSUV\uFF0C\u642D\u8F7D\u9AD8\u5B89\u5168\u5200\u7247\u7535\u6C60\u4E0EDiPilot\u667A\u80FD\u9A7E\u9A76\u8F85\u52A9\uFF0C\u7EFC\u5408\u5DE5\u51B5\u7EED\u822A\u8FBE605\u516C\u91CC\u3002", descriptionCkb: "\u067E\u0695\u0641\u0631\u06C6\u0634\u062A\u0631\u06CC\u0646 \u0626\u06C6\u062A\u06C6\u0645\u0628\u06CE\u0644\u06CC \u06A9\u0627\u0631\u06D5\u0628\u0627\u06CC\u06CC \u0632\u06CC\u0631\u06D5\u06A9 \u0644\u06D5 \u0628\u0627\u0632\u0627\u0695\u06CC \u0639\u06CE\u0631\u0627\u0642\u060C \u0628\u06D5 \u067E\u0627\u062A\u0631\u06CC Blade \u06CC \u067E\u06CE\u0634\u06A9\u06D5\u0648\u062A\u0648\u0648 \u0648 \u062A\u0648\u0627\u0646\u0627\u06CC \u0628\u0695\u06CC\u0646\u06CC 605 \u06A9\u0645 \u0628\u06D5 \u06CC\u06D5\u06A9 \u0628\u0627\u0631\u06AF\u0627\u0648\u06CC\u06A9\u0631\u062F\u0646.", imageUrl: "https://images.unsplash.com/photo-1593941707882-a5bba14938c7?auto=format&fit=crop&w=1200&q=80", category: "AUTOMOTIVE", link: "/en/contact?inquiry=byd-song-plus", isFeatured: true, order: 1 }, { titleEn: "Changan UNI-K AWD Intelligent Luxury SUV", titleAr: "\u0634\u0627\u0646\u062C\u0627\u0646 \u064A\u0648\u0646\u064A-\u0643\u064A \u0627\u0644\u0630\u0643\u064A\u0629 \u0631\u0628\u0627\u0639\u064A\u0629 \u0627\u0644\u062F\u0641\u0639 \u0627\u0644\u0641\u0627\u062E\u0631\u0629", titleZh: "\u957F\u5B89 UNI-K \u667A\u7535\u5168\u8F6E\u9A71\u52A8\u672A\u6765\u611F\u8C6A\u534E\u65D7\u8230SUV", titleCkb: "\u0626\u06C6\u062A\u06C6\u0645\u0628\u06CE\u0644\u06CC \u0634\u0627\u0646\u06AF\u0627\u0646 \u06CC\u0648\u0646\u06CC \u06A9\u06D5\u06CC \u0686\u0648\u0627\u0631 \u062F\u06D5\u0641\u06D5\u0631", descriptionEn: "Futuristic design language paired with luxury cabin appointments, Sony surround acoustics, and intelligent all-wheel-drive, dominating modern urban transport in Iraqi metropolitan hubs.", descriptionAr: "\u0633\u064A\u0627\u0631\u0629 \u0643\u0631\u0648\u0633 \u0623\u0648\u0641\u0631 \u0645\u0633\u062A\u0642\u0628\u0644\u064A\u0629 \u0628\u062A\u0635\u0645\u064A\u0645 \u062C\u0631\u064A\u0621 \u0648\u0645\u0642\u0635\u0648\u0631\u0629 \u0645\u062C\u0647\u0632\u0629 \u0628\u0623\u062D\u062F\u062B \u062A\u0642\u0646\u064A\u0627\u062A \u0627\u0644\u0631\u0641\u0627\u0647\u064A\u0629 \u0648\u0627\u0644\u0623\u0645\u0627\u0646\u060C \u062A\u062D\u0638\u0649 \u0628\u0634\u0639\u0628\u064A\u0629 \u0645\u062A\u0632\u0627\u064A\u062F\u0629 \u0641\u064A \u0634\u0648\u0627\u0631\u0639 \u0627\u0644\u0645\u062F\u0646 \u0627\u0644\u0639\u0631\u0627\u0642\u064A\u0629.", descriptionZh: "\u878D\u5408\u672A\u6765\u79D1\u5E7B\u673A\u7532\u8BBE\u8BA1\u8BED\u8A00\u4E0E\u5962\u534E\u8212\u9002\u5EA7\u8231\u7684\u667A\u80FD\u65D7\u8230SUV\uFF0C\u5728\u4F0A\u62C9\u514B\u5404\u5927\u4E3B\u8981\u90FD\u5E02\u9053\u8DEF\u4E0E\u5BB6\u5EAD\u5E02\u573A\u6DF1\u53D7\u6B22\u8FCE\u3002", descriptionCkb: "\u0626\u06C6\u062A\u06C6\u0645\u0628\u06CE\u0644\u06CC \u0645\u06C6\u062F\u06CE\u0631\u0646\u06CC \u062E\u06CE\u0632\u0627\u0646\u06CC \u0628\u06D5 \u062F\u06CC\u0632\u0627\u06CC\u0646\u06CE\u06A9\u06CC \u062F\u0627\u0647\u06CE\u0646\u06D5\u0631\u0627\u0646\u06D5 \u0648 \u067E\u0695 \u0644\u06D5 \u062A\u0627\u06CC\u0628\u06D5\u062A\u0645\u06D5\u0646\u062F\u06CC \u0626\u0627\u0633\u0648\u0648\u062F\u06D5\u06CC\u06CC \u06A9\u06D5 \u062E\u0648\u0627\u0633\u062A\u06CC \u0632\u06C6\u0631\u06CC \u0644\u06D5\u0633\u06D5\u0631\u06D5 \u0644\u06D5 \u0634\u0627\u0631\u06D5\u06A9\u0627\u0646\u06CC \u0639\u06CE\u0631\u0627\u0642.", imageUrl: "https://images.unsplash.com/photo-1503376780353-7e6692767b70?auto=format&fit=crop&w=1200&q=80", category: "AUTOMOTIVE", link: "/en/contact?inquiry=changan-uni-k", isFeatured: true, order: 2 }, { titleEn: "Zeekr 001 Luxury Shooting Brake EV", titleAr: "\u0632\u064A\u0643\u0631 001 \u0634\u0648\u062A\u064A\u0646\u063A \u0628\u0631\u064A\u0643 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0626\u064A\u0629 \u0627\u0644\u0641\u0627\u062E\u0631\u0629", titleZh: "\u6781\u6C2A ZEEKR 001 \u5168\u80FD\u8C6A\u534E\u730E\u88C5\u667A\u80FD\u8F7F\u8DD1", titleCkb: "\u0626\u06C6\u062A\u06C6\u0645\u0628\u06CE\u0644\u06CC \u06A9\u0627\u0631\u06D5\u0628\u0627\u06CC\u06CC \u0644\u0648\u06A9\u0633 \u0632\u06CC\u06A9\u0631 001", descriptionEn: "Ultra-fast 800V high-voltage architecture delivering 10% to 80% charge in 15 minutes, dual motors with 0-100 km/h in 3.8s, tailored for high-speed intercity routes.", descriptionAr: "\u0647\u0646\u062F\u0633\u0629 \u0634\u062D\u0646 \u0641\u0627\u0626\u0642\u0629 \u0627\u0644\u0633\u0631\u0639\u0629 \u0628\u062C\u0647\u062F 800 \u0641\u0648\u0644\u062A \u062A\u0645\u0646\u062D \u0634\u062D\u0646\u0627\u064B \u0645\u0646 10% \u0625\u0644\u0649 80% \u0641\u064A 15 \u062F\u0642\u064A\u0642\u0629 \u0641\u0642\u0637\u060C \u0645\u0639 \u0645\u062D\u0631\u0643\u064A\u0646 \u0628\u0642\u0648\u0629 \u062A\u0633\u0627\u0631\u0639 \u0645\u0646 0 \u0625\u0644\u0649 100 \u0643\u0645/\u0633 \u062E\u0644\u0627\u0644 3.8 \u062B\u0627\u0646\u064A\u0629.", descriptionZh: "\u5168\u6808800V\u9AD8\u538B\u8D85\u5145\u67B6\u6784\uFF0C\u53CC\u7535\u673A\u56DB\u9A71\u96F6\u767E\u52A0\u901F\u4EC5\u97003.8\u79D2\uFF0C\u517C\u5177\u8DD1\u8F66\u64CD\u63A7\u4E0ESUV\u7A7A\u95F4\u7684\u8DE8\u754C\u7EAF\u7535\u730E\u88C5\u6807\u6746\u3002", descriptionCkb: "\u0633\u06CC\u0633\u062A\u06D5\u0645\u06CC \u0628\u0627\u0631\u06AF\u0627\u0648\u06CC\u06A9\u0631\u062F\u0646\u06CC \u062E\u06CE\u0631\u0627\u06CC 800 \u06A4\u06C6\u06B5\u062A \u06A9\u06D5 \u0644\u06D5 15 \u062E\u0648\u0644\u06D5\u06A9\u062F\u0627 80% \u0628\u0627\u0631\u06AF\u0627\u0648\u06CC \u062F\u06D5\u0628\u06CE\u062A\u06D5\u0648\u06D5\u060C \u0628\u06D5 \u062E\u06CE\u0631\u0627\u06CC\u06CC \u0644\u06D5 0 \u0628\u06C6 100 \u06A9\u0645/\u06A9 \u0644\u06D5 3.8 \u0686\u0631\u06A9\u06D5\u062F\u0627.", imageUrl: "https://images.unsplash.com/photo-1617814076367-b759c7d7e738?auto=format&fit=crop&w=1200&q=80", category: "AUTOMOTIVE", link: "/en/contact?inquiry=zeekr-001", isFeatured: true, order: 3 }, { titleEn: "Geely Monjaro High-Performance Flagship SUV", titleAr: "\u062C\u064A\u0644\u064A \u0645\u0648\u0646\u062C\u0627\u0631\u0648 \u0627\u0644\u062F\u0641\u0639 \u0627\u0644\u0631\u0628\u0627\u0639\u064A \u0627\u0644\u0631\u064A\u0627\u0636\u064A \u0627\u0644\u0641\u062E\u0645", titleZh: "\u5409\u5229\u661F\u8D8AL (Monjaro) \u65D7\u8230\u7EA7\u667A\u80FD\u5168\u5730\u5F62SUV", titleCkb: "\u062C\u06CC\u0644\u06CC \u0645\u06C6\u0646\u062C\u0627\u0631\u06C6 \u0626\u06C6\u062A\u06C6\u0645\u0628\u06CE\u0644\u06CC \u0686\u0648\u0627\u0631 \u062F\u06D5\u0641\u06D5\u0631\u06CC \u067E\u06CE\u0634\u06A9\u06D5\u0648\u062A\u0648\u0648", descriptionEn: "Powered by a 2.0L turbocharged engine and BorgWarner 6th-gen 4WD, equipped with IMAX triple 12.3-inch smart screens and AR-HUD heads-up display.", descriptionAr: "\u0645\u0632\u0648\u062F\u0629 \u0628\u0645\u062D\u0631\u0643 \u062A\u0648\u0631\u0628\u064A\u0646\u064A 2.0 \u0644\u062A\u0631 \u0648\u0646\u0638\u0627\u0645 \u062F\u0641\u0639 \u0631\u0628\u0627\u0639\u064A \u0630\u0643\u064A \u0645\u0646 \u0628\u0648\u0631\u063A \u0648\u0627\u0631\u0646\u0631\u060C \u0645\u0639 \u062B\u0644\u0627\u062B \u0634\u0627\u0634\u0627\u062A \u0631\u0642\u0645\u064A\u0629 \u0628\u0627\u0646\u0648\u0631\u0627\u0645\u064A\u0629 \u0648\u062A\u0642\u0646\u064A\u0629 \u0627\u0644\u0639\u0631\u0636 \u0639\u0644\u0649 \u0627\u0644\u0632\u062C\u0627\u062C \u0627\u0644\u0623\u0645\u0627\u0645\u064A AR-HUD.", descriptionZh: "CMA\u9AD8\u9636\u67B6\u6784\u6253\u9020\uFF0C\u642D\u8F7DDrive-E\u7CFB\u52172.0TD\u9AD8\u529F\u7387\u53D1\u52A8\u673A\u4E0E\u535A\u683C\u534E\u7EB3\u7B2C\u516D\u4EE3\u56DB\u9A71\uFF0C\u5EA7\u8231IMAX\u4E09\u8054\u5C4F\u4E0EAR-HUD\u63D0\u4F9B\u5168\u65B9\u4F4D\u6570\u5B57\u6C89\u6D78\u4F53\u9A8C\u3002", descriptionCkb: "\u0628\u06D5 \u0645\u06C6\u062A\u06C6\u0631\u06CC 2.0 \u062A\u06CE\u0631\u0628\u06C6 \u0648 \u0633\u06CC\u0633\u062A\u06D5\u0645\u06CC \u0686\u0648\u0627\u0631 \u062F\u06D5\u0641\u06D5\u0631\u06CC \u0632\u06CC\u0631\u06D5\u06A9\u060C \u0644\u06D5\u06AF\u06D5\u06B5 \u0633\u06CE \u0634\u0627\u0634\u06D5\u06CC \u067E\u0627\u0646\u06C6\u0631\u0627\u0645\u0627 \u0648 \u062A\u06D5\u06A9\u0646\u06D5\u0644\u06C6\u0698\u06CC\u0627\u06CC \u0632\u06CC\u0631\u06D5\u06A9\u06CC \u067E\u06CE\u0634\u06A9\u06D5\u0648\u062A\u0648\u0648.", imageUrl: "https://images.unsplash.com/photo-1549399542-7e3f8b79c341?auto=format&fit=crop&w=1200&q=80", category: "AUTOMOTIVE", link: "/en/contact?inquiry=geely-monjaro", isFeatured: true, order: 4 }, { titleEn: "Chery Tiggo 8 Pro Max 7-Seater Luxury Crossover", titleAr: "\u0634\u064A\u0631\u064A \u062A\u064A\u062C\u0648 8 \u0628\u0631\u0648 \u0645\u0627\u0643\u0633 \u0627\u0644\u0639\u0627\u0626\u0644\u064A\u0629 \u0628\u0633\u0628\u0639\u0629 \u0645\u0642\u0627\u0639\u062F", titleZh: "\u5947\u745E\u745E\u864E8 PRO MAX \u8C6A\u534E7\u5EA7\u667A\u80FD\u5168\u573A\u666FSUV", titleCkb: "\u0634\u06CE\u0631\u06CC \u062A\u06CC\u06AF\u06C6 8 \u067E\u0631\u06C6 \u0645\u0627\u06A9\u0633 \u062D\u06D5\u0648\u062A \u0633\u06D5\u0631\u0646\u0634\u06CC\u0646", descriptionEn: "Spacious 7-seater executive layout with 2.0 TGDI high-output engine, ADAS level 2.5 autonomous safety, and tropical dual-zone rear AC for Iraqi families.", descriptionAr: "\u0645\u0642\u0635\u0648\u0631\u0629 \u0639\u0627\u0626\u0644\u064A\u0629 \u0631\u062D\u0628\u0629 \u062A\u062A\u0633\u0639 \u0644\u0640 7 \u0631\u0643\u0627\u0628\u060C \u0628\u0645\u062D\u0631\u0643 2.0 TGDI \u0642\u0648\u064A \u0648\u0623\u0646\u0638\u0645\u0629 \u0623\u0645\u0627\u0646 \u0645\u062A\u0637\u0648\u0631\u0629 \u0627\u0644\u0645\u0633\u062A\u0648\u0649 2.5 \u0645\u0639 \u062A\u0643\u064A\u064A\u0641 \u0627\u0633\u062A\u0648\u0627\u0626\u064A \u062E\u0644\u0641\u064A \u0645\u0633\u062A\u0642\u0644.", descriptionZh: "\u5947\u745E\u9CB2\u9E4F\u52A8\u529B2.0TGDI\u5168\u573A\u666F\u667A\u80FD\u56DB\u9A717\u5EA7SUV\uFF0C\u914D\u5907L2.5\u7EA7\u667A\u80FD\u9A7E\u9A76\u8F85\u52A9\u4E0E\u53CC\u6E29\u533A\u540E\u6392\u5F3A\u529B\u72EC\u7ACB\u7A7A\u8C03\uFF0C\u4E3A\u5BB6\u5EAD\u4E0E\u5546\u52A1\u51FA\u884C\u4FDD\u9A7E\u62A4\u822A\u3002", descriptionCkb: "\u0626\u06C6\u062A\u06C6\u0645\u0628\u06CE\u0644\u06CC \u062E\u06CE\u0632\u0627\u0646\u06CC 7 \u0646\u06D5\u0641\u06D5\u0631\u06CC \u0628\u06D5 \u0645\u06C6\u062A\u06C6\u0631\u06CC \u0628\u06D5\u0647\u06CE\u0632 \u0648 \u0633\u06CC\u0633\u062A\u06D5\u0645\u06CC \u0626\u06C6\u062A\u06C6\u0645\u0627\u062A\u06CC\u06A9\u06CC \u0632\u06CC\u0631\u06D5\u06A9\u06CC \u0633\u06D5\u0644\u0627\u0645\u06D5\u062A\u06CC \u0648 \u0641\u06CE\u0646\u06A9\u06A9\u06D5\u0631\u06D5\u0648\u06D5\u06CC \u062A\u0627\u06CC\u0628\u06D5\u062A \u0628\u06D5 \u06A9\u06D5\u0634\u0648\u0647\u06D5\u0648\u0627\u06CC \u0646\u0627\u0648\u0686\u06D5\u06A9\u06D5.", imageUrl: "https://images.unsplash.com/photo-1533473359331-0135ef1b58bf?auto=format&fit=crop&w=1200&q=80", category: "AUTOMOTIVE", link: "/en/contact?inquiry=chery-tiggo-8", isFeatured: true, order: 5 }, { titleEn: "LONGi Hi-MO X6 High-Efficiency Solar PV Modules", titleAr: "\u0623\u0644\u0648\u0627\u062D \u0644\u0648\u0646\u062C\u064A \u0647\u0627\u064A-\u0625\u0645 \u0623\u0648 \u0627\u0644\u0634\u0645\u0633\u064A\u0629 \u0627\u0644\u0643\u0647\u0631\u0648\u0636\u0648\u0626\u064A\u0629 \u0641\u0627\u0626\u0642\u0629 \u0627\u0644\u0643\u0641\u0627\u0621\u0629", titleZh: "\u9686\u57FA\u7EFF\u80FD Hi-MO X6 \u9AD8\u6548\u8010\u9AD8\u6E29\u5149\u4F0F\u7EC4\u4EF6", titleCkb: "\u062A\u06D5\u062E\u062A\u06D5\u06CC \u0648\u0632\u06D5\u06CC \u062E\u06C6\u0631\u06CC \u0644\u06C6\u0646\u062C\u06CC \u0628\u06D5 \u06A9\u0648\u0627\u0644\u06CE\u062A\u06CC \u0628\u06D5\u0631\u0632", descriptionEn: "High-efficiency HPBC cell technology engineered for extreme high-temperature desert climates in southern and central Iraq, boasting 23.3% peak module efficiency.", descriptionAr: "\u0623\u0644\u0648\u0627\u062D \u0643\u0647\u0631\u0648\u0636\u0648\u0626\u064A\u0629 \u0639\u0627\u0644\u064A\u0629 \u0627\u0644\u0643\u0641\u0627\u0621\u0629 \u0645\u0635\u0645\u0645\u0629 \u062E\u0635\u064A\u0635\u0627\u064B \u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u062F\u0631\u062C\u0627\u062A \u0627\u0644\u062D\u0631\u0627\u0631\u0629 \u0627\u0644\u0645\u0631\u062A\u0641\u0639\u0629 \u0648\u0627\u0644\u0645\u0646\u0627\u062E \u0627\u0644\u0635\u062D\u0631\u0627\u0648\u064A \u0641\u064A \u0627\u0644\u0639\u0631\u0627\u0642\u060C \u0628\u0643\u0641\u0627\u0621\u0629 \u062A\u0634\u063A\u064A\u0644\u064A\u0629 \u0631\u0627\u0626\u062F\u0629 \u062A\u0635\u0644 \u0625\u0644\u0649 23.3%.", descriptionZh: "\u4E13\u4E3A\u4E2D\u4E1C\u53CA\u4F0A\u62C9\u514B\u9AD8\u6E29\u6C99\u6F20\u4E25\u82DB\u73AF\u5883\u7814\u53D1\u7684\u9AD8\u6548HPBC\u5149\u4F0F\u7EC4\u4EF6\uFF0C\u8F6C\u6362\u6548\u7387\u8FBE23.3%\uFF0C\u4FDD\u969C\u4E25\u5BD2\u9177\u6691\u4E0B\u7684\u5168\u5929\u5019\u53D1\u7535\u7A33\u5B9A\u6027\u3002", descriptionCkb: "\u062A\u06D5\u062E\u062A\u06D5\u06CC \u0648\u0632\u06D5\u06CC \u062E\u06C6\u0631\u06CC \u0628\u06D5\u0631\u0632\u062A\u0631\u06CC\u0646 \u06A9\u0648\u0627\u0644\u06CE\u062A\u06CC \u06A9\u06D5 \u062A\u0627\u06CC\u0628\u06D5\u062A \u062F\u0631\u0648\u0633\u062A\u06A9\u0631\u0627\u0648\u06D5 \u0628\u06C6 \u06A9\u06D5\u0634\u0648\u0647\u06D5\u0648\u0627\u06CC \u06AF\u06D5\u0631\u0645 \u0648 \u0628\u06CC\u0627\u0628\u0627\u0646\u06CC \u0639\u06CE\u0631\u0627\u0642 \u0628\u06D5 \u062A\u0648\u0627\u0646\u0627\u06CC \u06A9\u0627\u0631\u06A9\u0631\u062F\u0646\u06CC 23.3%.", imageUrl: "https://images.unsplash.com/photo-1509391365360-2e959784a276?auto=format&fit=crop&w=1200&q=80", category: "SOLAR_ENERGY", link: "/en/contact?inquiry=longi-solar-iraq", isFeatured: true, order: 6 }, { titleEn: "JinkoSolar Tiger Neo N-Type TOPCon 620W Panels", titleAr: "\u0623\u0644\u0648\u0627\u062D \u062C\u064A\u0646\u0643\u0648 \u0633\u0648\u0644\u0627\u0631 \u062A\u0627\u064A\u063A\u0631 \u0646\u064A\u0648 \u0625\u0646-\u062A\u0627\u064A\u0628 620 \u0648\u0627\u0637", titleZh: "\u6676\u79D1\u80FD\u6E90 Tiger Neo N\u578BTOPCon 620W \u9AD8\u6548\u53CC\u9762\u53CC\u73BB\u7EC4\u4EF6", titleCkb: "\u062A\u06D5\u062E\u062A\u06D5\u06CC \u0648\u0632\u06D5\u06CC \u062E\u06C6\u0631\u06CC \u062C\u06CC\u0646\u06A9\u06C6 \u0633\u06C6\u0644\u0627\u0631 620 \u0648\u0627\u0637", descriptionEn: "SMBB half-cut cell technology offering ultra-low annual degradation (-0.40%/year) and up to 85% bifaciality for ground-mounted solar farms across Basra and Najaf.", descriptionAr: "\u062A\u0642\u0646\u064A\u0629 \u062E\u0644\u0627\u064A\u0627 N-Type TOPCon \u0627\u0644\u0645\u062A\u0637\u0648\u0631\u0629 \u0628\u0646\u0633\u0628\u0629 \u062A\u062F\u0647\u0648\u0631 \u0633\u0646\u0648\u064A \u0636\u0626\u064A\u0644\u0629 (-0.40%) \u0648\u0648\u062C\u0647\u064A\u0646 \u0644\u062A\u0648\u0644\u064A\u062F \u0627\u0644\u0637\u0627\u0642\u0629 \u0628\u0643\u0641\u0627\u0621\u0629 85% \u0644\u0645\u0632\u0627\u0631\u0639 \u0627\u0644\u0637\u0627\u0642\u0629 \u0627\u0644\u0634\u0645\u0633\u064A\u0629 \u0627\u0644\u0643\u0628\u0631\u0649.", descriptionZh: "\u91C7\u7528\u884C\u4E1A\u9886\u5148\u7684N\u578BTOPCon\u7535\u6C60\u6280\u672F\uFF0C\u53CC\u9762\u7387\u9AD8\u8FBE85%\uFF0C\u5177\u5907\u4F18\u5F02\u7684\u6297PID\u8010\u6C99\u5C18\u6027\u80FD\uFF0C\u5E74\u8870\u51CF\u7387\u4F4E\u81F30.40%\u3002", descriptionCkb: "\u062A\u06D5\u06A9\u0646\u06D5\u0644\u06C6\u0698\u06CC\u0627\u06CC \u067E\u06CE\u0634\u06A9\u06D5\u0648\u062A\u0648\u0648\u06CC N-Type \u0628\u06D5 \u062A\u0648\u0627\u0646\u0627\u06CC 620 \u0648\u0627\u0637 \u06A9\u06D5 \u0644\u06D5 \u0647\u06D5\u0631\u062F\u0648\u0648 \u0695\u0648\u0648\u06D5\u0648\u06D5 \u062A\u06CC\u0634\u06A9\u06CC \u062E\u06C6\u0631 \u0648\u06D5\u0631\u062F\u06D5\u06AF\u0631\u06CE\u062A \u0648 \u062A\u06D5\u0645\u06D5\u0646\u06CE\u06A9\u06CC \u062F\u0631\u06CE\u0698\u06CC \u0647\u06D5\u06CC\u06D5.", imageUrl: "https://images.unsplash.com/photo-1508873696983-2df5293cb32f?auto=format&fit=crop&w=1200&q=80", category: "SOLAR_ENERGY", link: "/en/contact?inquiry=jinko-tiger-neo", isFeatured: true, order: 7 }, { titleEn: "Huawei FusionSolar Commercial Smart PV & Storage", titleAr: "\u0645\u062D\u0648\u0644\u0627\u062A \u0647\u0648\u0627\u0648\u064A \u0641\u064A\u0648\u062C\u0646 \u0633\u0648\u0644\u0627\u0631 \u0627\u0644\u0630\u0643\u064A\u0629 \u0645\u0639 \u0628\u0637\u0627\u0631\u064A\u0627\u062A \u0627\u0644\u062A\u062E\u0632\u064A\u0646", titleZh: "\u534E\u4E3A\u6570\u5B57\u80FD\u6E90 FusionSolar \u667A\u80FD\u5149\u50A8\u4E00\u4F53\u5316\u89E3\u51B3\u65B9\u6848", titleCkb: "\u0633\u06CC\u0633\u062A\u06D5\u0645\u06CC \u0648\u0632\u06D5\u06CC \u062E\u06C6\u0631\u06CC \u0647\u06C6\u0648\u0627\u0648\u06CC \u0648 \u0628\u0627\u062A\u0631\u06CC \u067E\u0627\u0634\u06D5\u06A9\u06D5\u0648\u062A\u06A9\u0631\u062F\u0646", descriptionEn: "SUN2000 smart string inverters paired with LUNA2000 smart energy storage, featuring AI-assisted AFCI arc-fault protection and zero grid disturbance.", descriptionAr: "\u0645\u062D\u0648\u0644\u0627\u062A \u0633\u0644\u0633\u0644\u0629 SUN2000 \u0627\u0644\u0630\u0643\u064A\u0629 \u0645\u0639 \u0623\u0646\u0638\u0645\u0629 \u062A\u062E\u0632\u064A\u0646 \u0627\u0644\u0637\u0627\u0642\u0629 LUNA2000 \u0627\u0644\u0645\u062F\u0639\u0648\u0645\u0629 \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A \u0644\u062D\u0645\u0627\u064A\u0629 \u0627\u0644\u0645\u0646\u0634\u0622\u062A \u0627\u0644\u0635\u0646\u0627\u0639\u064A\u0629 \u0648\u0627\u0644\u0645\u0635\u0627\u0646\u0639 \u0627\u0644\u0639\u0631\u0627\u0642\u064A\u0629 \u0645\u0646 \u0627\u0646\u0642\u0637\u0627\u0639 \u0627\u0644\u062A\u064A\u0627\u0631.", descriptionZh: "\u4E1A\u754C\u9996\u521BAI\u667A\u80FD\u7535\u5F27\u9632\u62A4\uFF08AFCI\uFF09\u4E0E\u7EC4\u4E32\u5F0F\u667A\u80FD\u5149\u50A8\u878D\u5408\u67B6\u6784\uFF0C0ms\u6781\u901F\u79BB\u7F51\u5207\u6362\uFF0C\u5F7B\u5E95\u89E3\u51B3\u5DE5\u5546\u4E1A\u7528\u6237\u7535\u529B\u4E0D\u7A33\u75DB\u70B9\u3002", descriptionCkb: "\u0633\u06CC\u0633\u062A\u06D5\u0645\u06CC \u0632\u06CC\u0631\u06D5\u06A9\u06CC \u0647\u06C6\u0648\u0627\u0648\u06CC \u0628\u06D5 \u067E\u0627\u0631\u0627\u0633\u062A\u0646\u06CC \u062A\u06D5\u0648\u0627\u0648 \u0644\u06D5 \u06A9\u06CE\u0634\u06D5\u06A9\u0627\u0646\u06CC \u06A9\u0627\u0631\u06D5\u0628\u0627 \u0648 \u067E\u0627\u062A\u0631\u06CC \u062A\u0627\u06CC\u0628\u06D5\u062A \u0628\u06C6 \u0628\u06D5\u0631\u062F\u06D5\u0648\u0627\u0645\u0628\u0648\u0648\u0646\u06CC \u06A9\u0627\u0631\u06D5\u0628\u0627 \u0644\u06D5 \u06A9\u0627\u0631\u06AF\u06D5 \u0648 \u06A9\u06C6\u0645\u067E\u0627\u0646\u06CC\u0627\u06A9\u0627\u0646.", imageUrl: "https://images.unsplash.com/photo-1497435334941-8c899ee9e8e9?auto=format&fit=crop&w=1200&q=80", category: "SOLAR_ENERGY", link: "/en/contact?inquiry=huawei-fusionsolar", isFeatured: true, order: 8 }, { titleEn: "Trina Solar Vertex DEG21C Bifacial Dual-Glass 670W", titleAr: "\u0623\u0644\u0648\u0627\u062D \u062A\u0631\u064A\u0646\u0627 \u0633\u0648\u0644\u0627\u0631 \u0641\u064A\u0631\u062A\u0643\u0633 \u062B\u0646\u0627\u0626\u064A\u0629 \u0627\u0644\u0632\u062C\u0627\u062C 670 \u0648\u0627\u0637", titleZh: "\u5929\u5408\u5149\u80FD \u81F3\u5C0A Vertex 670W \u8D85\u9AD8\u529F\u7387\u53CC\u73BB\u7EC4\u4EF6", titleCkb: "\u062A\u06D5\u062E\u062A\u06D5\u06CC \u062A\u0695\u06CC\u0646\u0627 \u0633\u06C6\u0644\u0627\u0631 \u06A4\u06CE\u0631\u062A\u06CE\u06A9\u0633 670 \u0648\u0627\u0637", descriptionEn: "Engineered on 210mm silicon wafers delivering 670W+ maximum output, encased in 2.0mm dual heat-strengthened glass with high sandstorm and ammonia resistance.", descriptionAr: "\u0645\u0635\u0645\u0645\u0629 \u0628\u0631\u0642\u0627\u0642\u0627\u062A \u0633\u064A\u0644\u064A\u0643\u0648\u0646 210 \u0645\u0645 \u0644\u0625\u0646\u062A\u0627\u062C \u0637\u0627\u0642\u0629 \u0642\u0635\u0648\u0649 \u062A\u062A\u062C\u0627\u0648\u0632 670 \u0648\u0627\u0637\u060C \u0645\u063A\u0644\u0641\u0629 \u0628\u0632\u062C\u0627\u062C \u0645\u0632\u062F\u0648\u062C \u0645\u0642\u0648\u0649 \u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u0627\u0644\u0639\u0648\u0627\u0635\u0641 \u0627\u0644\u0631\u0645\u0644\u064A\u0629 \u0648\u0627\u0644\u0623\u062A\u0631\u0628\u0629 \u0641\u064A \u0627\u0644\u0639\u0631\u0627\u0642.", descriptionZh: "\u57FA\u4E8E210mm\u5927\u5C3A\u5BF8\u7845\u7247\u4E0E\u65E0\u635F\u5207\u5272\u5FAE\u8DDD\u6280\u672F\uFF0C\u53CC\u73BB\u53CC\u9762\u53D1\u7535\uFF0C\u5168\u9762\u62B5\u6297\u4E2D\u4E1C\u6C99\u5C18\u66B4\u3001\u9AD8\u6E29\u53CA\u6C28\u6C14\u5316\u5B66\u8150\u8680\u3002", descriptionCkb: "\u062A\u06D5\u062E\u062A\u06D5\u06CC \u0628\u06D5\u0647\u06CE\u0632 \u0628\u06D5 \u062A\u0648\u0627\u0646\u0627\u06CC 670 \u0648\u0627\u0637 \u06A9\u06D5 \u0628\u06D5 \u062F\u0648\u0648 \u0686\u06CC\u0646\u06CC \u0634\u0648\u0648\u0634\u06D5\u06CC \u062A\u0627\u06CC\u0628\u06D5\u062A \u062F\u0627\u067E\u06C6\u0634\u0631\u0627\u0648\u06D5 \u0628\u06C6 \u0628\u06D5\u0631\u06AF\u06D5\u06AF\u0631\u062A\u0646\u06CC \u062A\u06C6\u0632 \u0648 \u06AF\u06D5\u0631\u0645\u0627\u06CC \u0628\u06D5\u0631\u0632.", imageUrl: "https://images.unsplash.com/photo-1466611653911-95081537e5b7?auto=format&fit=crop&w=1200&q=80", category: "SOLAR_ENERGY", link: "/en/contact?inquiry=trina-vertex", isFeatured: true, order: 9 }, { titleEn: "Sungrow SG350HX Utility-Scale String Inverter & Liquid ESS", titleAr: "\u0645\u062D\u0648\u0644\u0627\u062A \u0633\u0648\u0646\u063A\u0631\u0648 \u0627\u0644\u0643\u0628\u0631\u0649 \u0628\u0642\u062F\u0631\u0629 352 \u0643\u064A\u0644\u0648\u0648\u0627\u0637 \u0645\u0639 \u0646\u0638\u0627\u0645 \u0627\u0644\u062A\u0628\u0631\u064A\u062F \u0627\u0644\u0633\u0627\u0626\u0644", titleZh: "\u9633\u5149\u7535\u6E90 SG350HX \u5730\u9762\u7535\u7AD9\u7EC4\u4E32\u9006\u53D8\u5668\u4E0E\u6DB2\u51B7\u50A8\u80FD\u7CFB\u7EDF", titleCkb: "\u0626\u06CC\u0646\u06A4\u06CE\u0631\u062A\u06D5\u0631\u06CC \u067E\u06CC\u0634\u06D5\u0633\u0627\u0632\u06CC \u0633\u0648\u0646\u06AF\u0631\u06C6\u0648 \u0648 \u0633\u06CC\u0633\u062A\u06D5\u0645\u06CC \u0633\u0627\u0631\u062F\u06A9\u0631\u062F\u0646\u06D5\u0648\u06D5\u06CC \u0634\u0644", descriptionEn: "Heavy-duty 352kW utility inverter with IP66 ingress rating and C5 anti-corrosion, integrated with intelligent liquid-cooling energy storage containers.", descriptionAr: "\u0645\u062D\u0648\u0644 \u0639\u0645\u0644\u0627\u0642 \u0644\u0645\u062D\u0637\u0627\u062A \u0627\u0644\u0637\u0627\u0642\u0629 \u0628\u0642\u062F\u0631\u0629 352 \u0643\u064A\u0644\u0648\u0648\u0627\u0637 \u0645\u0639 \u062D\u0645\u0627\u064A\u0629 IP66 \u0648\u0645\u0642\u0627\u0648\u0645\u0629 \u0627\u0644\u062A\u0622\u0643\u0644 C5\u060C \u0645\u062A\u0643\u0627\u0645\u0644 \u0645\u0639 \u062D\u0627\u0648\u064A\u0627\u062A \u062A\u062E\u0632\u064A\u0646 \u0627\u0644\u0637\u0627\u0642\u0629 \u0627\u0644\u0645\u0628\u0631\u062F\u0629 \u0628\u0627\u0644\u0633\u0648\u0627\u0626\u0644.", descriptionZh: "\u5355\u673A\u529F\u7387\u8FBE352kW\uFF0C\u5177\u5907IP66\u4E0EC5\u7EA7\u9AD8\u9632\u8150\u9632\u62A4\uFF0C\u667A\u80FD\u5206\u533A\u98CE\u51B7\u4E0E\u6DB2\u51B7\u50A8\u80FD\u6DF1\u5EA6\u534F\u540C\uFF0C\u9002\u5E9450\u2103\u4EE5\u4E0A\u6781\u7AEF\u4E2D\u4E1C\u6C99\u6F20\u73AF\u5883\u3002", descriptionCkb: "\u0626\u06CC\u0646\u06A4\u06CE\u0631\u062A\u06D5\u0631\u06CC \u067E\u06CC\u0634\u06D5\u0633\u0627\u0632\u06CC \u0628\u06C6 \u0648\u06CE\u0633\u062A\u06AF\u06D5\u06A9\u0627\u0646\u06CC \u06A9\u0627\u0631\u06D5\u0628\u0627 \u0628\u06D5 \u062A\u0648\u0627\u0646\u0627\u06CC 352 \u06A9\u06CC\u0644\u06C6\u0648\u0627\u0637 \u0628\u06D5 \u0633\u06CC\u0633\u062A\u06D5\u0645\u06CC \u0633\u0627\u0631\u062F\u06A9\u0631\u062F\u0646\u06D5\u0648\u06D5\u06CC \u067E\u06CE\u0634\u06A9\u06D5\u0648\u062A\u0648\u0648 \u0628\u06C6 \u06A9\u06D5\u0634\u06CC \u06AF\u06D5\u0631\u0645.", imageUrl: "https://images.unsplash.com/photo-1548337138-e87d889cc369?auto=format&fit=crop&w=1200&q=80", category: "SOLAR_ENERGY", link: "/en/contact?inquiry=sungrow-sg350hx", isFeatured: true, order: 10 }, { titleEn: "XCMG XE215D Heavy Hydraulic Excavator", titleAr: "\u062D\u0641\u0627\u0631 \u0647\u064A\u062F\u0631\u0648\u0644\u064A\u0643\u064A \u062B\u0642\u064A\u0644 \u0645\u0646 \u0625\u0643\u0633 \u0633\u064A \u0625\u0645 \u062C\u064A (XCMG)", titleZh: "\u5F90\u5DE5\u96C6\u56E2 XE215D \u65D7\u8230\u7EA7\u667A\u80FD\u6DB2\u538B\u6316\u6398\u673A", titleCkb: "\u062D\u06D5\u0641\u0627\u0631\u06D5\u06CC \u0647\u0627\u06CC\u062F\u0631\u06C6\u0644\u06CC\u06A9\u06CC \u0642\u0648\u0631\u0633\u06CC XCMG", descriptionEn: "Premium heavy excavation machinery deployed across Iraq's national infrastructure reconstruction, highway corridors, and Belt and Road projects.", descriptionAr: "\u062D\u0641\u0627\u0631\u0627\u062A \u0647\u064A\u062F\u0631\u0648\u0644\u064A\u0643\u064A\u0629 \u0630\u0643\u064A\u0629 \u0645\u062A\u064A\u0646\u0629 \u062A\u0639\u062A\u0645\u062F \u0639\u0644\u064A\u0647\u0627 \u0643\u0628\u0631\u0649 \u0645\u0634\u0627\u0631\u064A\u0639 \u0625\u0639\u0627\u062F\u0629 \u0625\u0639\u0645\u0627\u0631 \u0627\u0644\u0628\u0646\u064A\u0629 \u0627\u0644\u062A\u062D\u062A\u064A\u0629 \u0648\u0627\u0644\u0645\u0648\u0627\u0646\u0626 \u0648\u0627\u0644\u0637\u0631\u0642 \u0627\u0644\u0633\u0631\u064A\u0639\u0629 \u0641\u064A \u0645\u062E\u062A\u0644\u0641 \u0627\u0644\u0645\u062D\u0627\u0641\u0638\u0627\u062A \u0627\u0644\u0639\u0631\u0627\u0642\u064A\u0629.", descriptionZh: "\u5E7F\u6CDB\u5E94\u7528\u4E8E\u4F0A\u62C9\u514B\u5168\u56FD\u57FA\u7840\u8BBE\u65BD\u91CD\u5EFA\u3001\u516C\u8DEF\u7F51\u7EDC\u4EE5\u53CA\u201C\u4E00\u5E26\u4E00\u8DEF\u201D\u91CD\u70B9\u5DE5\u4E1A\u6807\u6746\u5DE5\u5730\u7684\u65D7\u8230\u7EA7\u4E2D\u91CD\u578B\u667A\u80FD\u6DB2\u538B\u6316\u6398\u673A\u3002", descriptionCkb: "\u062D\u06D5\u0641\u0627\u0631\u06D5\u06CC \u0647\u0627\u06CC\u062F\u0631\u06C6\u0644\u06CC\u06A9\u06CC \u067E\u06CE\u0634\u06A9\u06D5\u0648\u062A\u0648\u0648 \u06A9\u06D5 \u0644\u06D5 \u067E\u0695\u06C6\u0698\u06D5\u06A9\u0627\u0646\u06CC \u0626\u0627\u0648\u06D5\u062F\u0627\u0646\u06A9\u0631\u062F\u0646\u06D5\u0648\u06D5\u06CC \u0698\u06CE\u0631\u062E\u0627\u0646 \u0648 \u067E\u0695\u06C6\u0698\u06D5\u06A9\u0627\u0646\u06CC \u0695\u06CE\u06AF\u0627\u06CC \u0626\u0627\u0648\u0631\u06CC\u0634\u0645 \u0644\u06D5 \u0639\u06CE\u0631\u0627\u0642 \u0628\u06D5\u06A9\u0627\u0631\u062F\u06D5\u0647\u06CE\u0646\u0631\u06CE\u062A.", imageUrl: "https://images.unsplash.com/photo-1578328819058-b69f3a3b0f6b?auto=format&fit=crop&w=1200&q=80", category: "HEAVY_MACHINERY", link: "/en/contact?inquiry=xcmg-heavy-machinery", isFeatured: true, order: 11 }, { titleEn: "SANY SY365H Heavy-Duty Mining & Construction Excavator", titleAr: "\u062D\u0641\u0627\u0631\u0629 \u0633\u0627\u0646\u064A SY365H \u0644\u0644\u062A\u0639\u062F\u064A\u0646 \u0648\u0627\u0644\u0623\u0634\u063A\u0627\u0644 \u0627\u0644\u0634\u0627\u0642\u0629", titleZh: "\u4E09\u4E00\u91CD\u5DE5 SY365H \u91CD\u8F7D\u77FF\u5C71\u578B\u6DB2\u538B\u6316\u6398\u673A", titleCkb: "\u062D\u06D5\u0641\u0627\u0631\u06D5\u06CC \u0633\u0627\u0646\u06CC SY365H \u0628\u06C6 \u06A9\u0627\u0631\u06D5 \u0642\u0648\u0631\u0633\u06D5\u06A9\u0627\u0646\u06CC \u06A9\u0648\u0646\u06A9\u0631\u062F\u0646 \u0648 \u0628\u06CC\u0646\u0627\u0633\u0627\u0632\u06CC", descriptionEn: "36-ton reinforced high-tensile steel excavator equipped with a custom Cummins QSL9 engine and automated load-sensing hydraulic distribution for harsh Iraqi earthworks.", descriptionAr: "\u062D\u0641\u0627\u0631\u0629 \u0648\u0632\u0646 36 \u0637\u0646\u0627\u064B \u0645\u0646 \u0627\u0644\u0641\u0648\u0644\u0627\u0630 \u0627\u0644\u0645\u0642\u0627\u0648\u0645 \u0644\u0644\u0625\u062C\u0647\u0627\u062F\u060C \u0645\u062C\u0647\u0632\u0629 \u0628\u0645\u062D\u0631\u0643 \u0643\u0627\u0645\u0646\u0632 QSL9 \u0648\u0646\u0638\u0627\u0645 \u0647\u064A\u062F\u0631\u0648\u0644\u064A\u0643\u064A \u0630\u0643\u064A \u0644\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u062C\u0628\u0644\u064A\u0629 \u0648\u0627\u0644\u062A\u0631\u0627\u0628\u064A\u0629 \u0627\u0644\u0634\u0627\u0642\u0629.", descriptionZh: "36\u5428\u7EA7\u91CD\u8F7D\u77FF\u5C71\u5229\u5668\uFF0C\u642D\u8F7D\u5B9A\u5236\u5316\u5EB7\u660E\u65AF\u53D1\u52A8\u673A\u4E0E\u9AD8\u538B\u7535\u63A7\u6B63\u6D41\u91CF\u6DB2\u538B\u7CFB\u7EDF\uFF0C\u6CB9\u8017\u66F4\u4F4E\u3001\u6316\u6398\u529B\u66F4\u5F3A\uFF0C\u4E13\u514B\u575A\u786C\u5CA9\u77F3\u4E0E\u5927\u8D1F\u8377\u65BD\u5DE5\u3002", descriptionCkb: "\u062D\u06D5\u0641\u0627\u0631\u06D5\u06CC 36 \u062A\u06C6\u0646\u06CC \u0632\u06C6\u0631 \u0628\u06D5\u0647\u06CE\u0632 \u0628\u06D5 \u0645\u06C6\u062A\u06C6\u0631\u06CC \u06A9\u06D5\u0645\u06CC\u0646\u0632 \u0648 \u0633\u06CC\u0633\u062A\u06D5\u0645\u06CC \u0647\u0627\u06CC\u062F\u0631\u06C6\u0644\u06CC\u06A9\u06CC \u067E\u06CE\u0634\u06A9\u06D5\u0648\u062A\u0648\u0648 \u0628\u06C6 \u067E\u0631\u06C6\u0698\u06D5 \u0633\u06D5\u062E\u062A\u06D5\u06A9\u0627\u0646.", imageUrl: "https://images.unsplash.com/photo-1581094288338-2314dddb7ece?auto=format&fit=crop&w=1200&q=80", category: "HEAVY_MACHINERY", link: "/en/contact?inquiry=sany-sy365h", isFeatured: true, order: 12 }, { titleEn: "Zoomlion ZTC800V 80-Ton Intelligent Truck Crane", titleAr: "\u0631\u0627\u0641\u0639\u0629 \u0647\u064A\u062F\u0631\u0648\u0644\u064A\u0643\u064A\u0629 \u0645\u062A\u0646\u0642\u0644\u0629 \u0632\u0648\u0645\u0644\u064A\u0648\u0646 ZTC800V \u062D\u0645\u0648\u0644\u0629 80 \u0637\u0646\u0627\u064B", titleZh: "\u4E2D\u8054\u91CD\u79D1 ZTC800V 80\u5428\u6C7D\u8F66\u8D77\u91CD\u673A", titleCkb: "\u06A9\u0631\u06CE\u0646\u06CC \u06AF\u06D5\u0695\u06C6\u06A9\u06CC \u0632\u0648\u0648\u0645\u0644\u06CC\u06C6\u0646 80 \u062A\u06C6\u0646", descriptionEn: "Equipped with a 5-section 49-meter U-shaped main boom, CAN-bus intelligent control, and heavy dual-engine chassis for bridge construction and oil refineries.", descriptionAr: "\u0645\u0632\u0648\u062F\u0629 \u0628\u0630\u0631\u0627\u0639 \u0631\u0626\u064A\u0633\u064A \u062E\u0645\u0627\u0633\u064A \u0627\u0644\u0623\u0642\u0633\u0627\u0645 \u0628\u0637\u0648\u0644 49 \u0645\u062A\u0631\u0627\u064B \u0628\u0634\u0643\u0644 \u062D\u0631\u0641 U\u060C \u0645\u0639 \u062A\u062D\u0643\u0645 \u0631\u0642\u0645\u064A \u0630\u0643\u064A \u0648\u0642\u062F\u0631\u0629 \u0631\u0641\u0639 \u0641\u0627\u0626\u0642\u0629 \u0644\u0628\u0646\u0627\u0621 \u0627\u0644\u062C\u0633\u0648\u0631 \u0648\u0645\u0646\u0634\u0622\u062A \u0627\u0644\u0646\u0641\u0637 \u0648\u0627\u0644\u063A\u0627\u0632.", descriptionZh: "\u4E94\u828249\u7C73U\u578B\u4E3B\u81C2\uFF0C\u884C\u4E1A\u9886\u5148\u7684\u7EFC\u5408\u8D77\u91CD\u6027\u80FD\uFF0C\u914D\u5907\u5168\u65B0\u667A\u80FD\u603B\u7EBF\u63A7\u5236\u4E0E\u591A\u6A21\u5F0F\u56DE\u8F6C\u7F13\u51B2\uFF0C\u5728\u6865\u6881\u540A\u88C5\u4E0E\u70BC\u6CB9\u5316\u5DE5\u5EFA\u8BBE\u4E2D\u8868\u73B0\u5353\u8D8A\u3002", descriptionCkb: "\u06A9\u0631\u06CE\u0646\u06CC 80 \u062A\u06C6\u0646\u06CC \u067E\u06CE\u0634\u06A9\u06D5\u0648\u062A\u0648\u0648 \u0628\u06D5 \u0628\u0627\u06B5\u06CC 49 \u0645\u06D5\u062A\u0631\u06CC \u0628\u06D5\u0647\u06CE\u0632 \u0628\u06C6 \u067E\u0695\u06C6\u0698\u06D5\u06A9\u0627\u0646\u06CC \u067E\u0631\u062F \u0648 \u06A9\u06C6\u0645\u067E\u0627\u0646\u06CC\u0627\u06A9\u0627\u0646\u06CC \u0646\u06D5\u0648\u062A \u0648 \u06AF\u0627\u0632.", imageUrl: "https://images.unsplash.com/photo-1541888946425-d0fbb18086f6?auto=format&fit=crop&w=1200&q=80", category: "HEAVY_MACHINERY", link: "/en/contact?inquiry=zoomlion-ztc800v", isFeatured: true, order: 13 }, { titleEn: "LiuGong 856H MAX Heavy Industrial Wheel Loader", titleAr: "\u0644\u0648\u062F\u0631 \u0644\u064A\u0648\u063A\u0648\u0646\u063A 856H MAX \u0627\u0644\u062B\u0642\u064A\u0644 \u0644\u0644\u0645\u062D\u0627\u062C\u0631 \u0648\u0645\u0648\u0627\u062F \u0627\u0644\u0628\u0646\u0627\u0621", titleZh: "\u67F3\u5DE5 856H MAX \u65D7\u8230\u7EA7\u91CD\u578B\u8F6E\u5F0F\u88C5\u8F7D\u673A", titleCkb: "\u0634\u06C6\u0641\u06B5\u06CC \u067E\u06CC\u0634\u06D5\u0633\u0627\u0632\u06CC \u0644\u06CC\u0648\u06AF\u06C6\u0646\u06AF 856H MAX", descriptionEn: "Cummins QSL9.3 high-torque engine with ZF automatic powershift transmission and 5.5-ton rated payload, built to withstand Iraqi aggregate loading cycles.", descriptionAr: "\u0645\u062D\u0631\u0643 \u0643\u0627\u0645\u0646\u0632 QSL9.3 \u0639\u0627\u0644\u064A \u0627\u0644\u0639\u0632\u0645 \u0645\u0639 \u0646\u0627\u0642\u0644 \u062D\u0631\u0643\u0629 \u0623\u0648\u062A\u0648\u0645\u0627\u062A\u064A\u0643\u064A ZF \u0648\u062D\u0645\u0648\u0644\u0629 \u062A\u0634\u063A\u064A\u0644\u064A\u0629 5.5 \u0637\u0646 \u0644\u062A\u062D\u0645\u064A\u0644 \u0627\u0644\u062D\u0635\u0649 \u0648\u0627\u0644\u0631\u0645\u0644 \u0648\u0627\u0644\u0623\u0633\u0645\u0646\u062A \u062F\u0648\u0646 \u062A\u0648\u0642\u0641.", descriptionZh: "\u642D\u8F7D\u5EB7\u660E\u65AFQSL9.3\u5927\u626D\u77E9\u53D1\u52A8\u673A\u4E0E\u5FB7\u56FD\u91C7\u57C3\u5B5A\u81EA\u52A8\u53D8\u901F\u7BB1\uFF0C\u989D\u5B9A\u8F7D\u91CD5.5\u5428\uFF0C\u91CD\u8F7D\u7ED3\u6784\u4EF6\u4E0E\u9632\u5C18\u5BC6\u5C01\u5EA7\u8231\u4E13\u4E3A\u7802\u77F3\u91C7\u6398\u5DE5\u51B5\u5B9A\u5236\u3002", descriptionCkb: "\u0634\u06C6\u0641\u06B5\u06CC \u067E\u06CC\u0634\u06D5\u0633\u0627\u0632\u06CC \u0628\u06D5 \u062A\u0648\u0627\u0646\u0627\u06CC \u0628\u0627\u0631\u06A9\u0631\u062F\u0646\u06CC 5.5 \u062A\u06C6\u0646 \u0628\u06D5 \u0645\u06C6\u062A\u06C6\u0631\u06CC \u06A9\u06D5\u0645\u06CC\u0646\u0632 \u0628\u06C6 \u06A9\u0627\u0631\u06A9\u0631\u062F\u0646 \u0644\u06D5 \u0646\u0627\u0648\u0686\u06D5\u06A9\u0627\u0646\u06CC \u0628\u06D5\u0631\u062F \u0648 \u0628\u06CC\u0646\u0627\u0633\u0627\u0632\u06CC.", imageUrl: "https://images.unsplash.com/photo-1504307651254-35680f356dfd?auto=format&fit=crop&w=1200&q=80", category: "HEAVY_MACHINERY", link: "/en/contact?inquiry=liugong-856h", isFeatured: true, order: 14 }, { titleEn: "Shantui DH17-C3 Full Hydrostatic Crawler Bulldozer", titleAr: "\u0628\u0644\u062F\u0648\u0632\u0631 \u0634\u0627\u0646\u062A\u0648\u064A DH17-C3 \u0627\u0644\u0647\u064A\u062F\u0631\u0648\u0633\u062A\u0627\u062A\u064A\u0643\u064A \u0644\u0645\u0634\u0627\u0631\u064A\u0639 \u0627\u0644\u0637\u0631\u0642 \u0648\u0627\u0644\u0635\u062D\u0631\u0627\u0621", titleZh: "\u5C71\u63A8\u80A1\u4EFD DH17-C3 \u5168\u6DB2\u538B\u9759\u6DB2\u538B\u4F20\u52A8\u5C65\u5E26\u63A8\u571F\u673A", titleCkb: "\u0628\u06C6\u06B5\u062F\u06C6\u0632\u06D5\u0631\u06CC \u0634\u0627\u0646\u062A\u0648\u06CC DH17-C3 \u0647\u0627\u06CC\u062F\u0631\u06C6\u0633\u062A\u0627\u062A\u06CC\u06A9\u06CC", descriptionEn: "Dual-circuit electronically controlled hydrostatic drive, Weichai Tier 3 electronic injection engine, and heavy semi-U blade engineered for desert road grading.", descriptionAr: "\u0646\u0638\u0627\u0645 \u062F\u0641\u0639 \u0647\u064A\u062F\u0631\u0648\u0633\u062A\u0627\u062A\u064A\u0643\u064A \u0645\u062A\u0637\u0648\u0631 \u0628\u062F\u0627\u0626\u0631\u062A\u064A\u0646 \u0645\u0639 \u0645\u062D\u0631\u0643 \u0648\u064A\u062A\u0634\u0627\u064A \u0628\u062D\u0642\u0646 \u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A \u0648\u0646\u0635\u0644\u0629 \u0646\u0635\u0641 \u0645\u0642\u0648\u0633\u0629 \u0644\u062A\u0645\u0647\u064A\u062F \u0627\u0644\u0637\u0631\u0642 \u0627\u0644\u0635\u062D\u0631\u0627\u0648\u064A\u0629 \u0641\u064A \u0627\u0644\u0639\u0631\u0627\u0642.", descriptionZh: "\u53CC\u56DE\u8DEF\u7535\u63A7\u9759\u6DB2\u538B\u9A71\u52A8\u7CFB\u7EDF\uFF0C\u642D\u8F7D\u6F4D\u67F4\u7535\u55B7\u9AD8\u626D\u77E9\u5F15\u64CE\u4E0E\u91CD\u578B\u534AU\u63A8\u571F\u94F2\uFF0C\u65E0\u6781\u53D8\u901F\uFF0C\u5728\u6C99\u6F20\u94FA\u8DEF\u4E0E\u571F\u77F3\u65B9\u538B\u5B9E\u4E2D\u6781\u5177\u6548\u7387\u3002", descriptionCkb: "\u0628\u06C6\u06B5\u062F\u06C6\u0632\u06D5\u0631\u06CC \u067E\u06CE\u0634\u06A9\u06D5\u0648\u062A\u0648\u0648 \u0628\u06D5 \u0633\u06CC\u0633\u062A\u06D5\u0645\u06CC \u0647\u0627\u06CC\u062F\u0631\u06C6\u0633\u062A\u0627\u062A\u06CC\u06A9 \u0648 \u0647\u06CE\u0632\u06CC \u0632\u06C6\u0631 \u0628\u06C6 \u0695\u06CE\u06A9\u062E\u0633\u062A\u0646\u06CC \u0695\u06CE\u06AF\u0627 \u0648 \u062E\u0627\u06A9\u06CC \u0628\u06CC\u0627\u0628\u0627\u0646\u06CC.", imageUrl: "https://images.unsplash.com/photo-1517524008697-84bbe3c3fd98?auto=format&fit=crop&w=1200&q=80", category: "HEAVY_MACHINERY", link: "/en/contact?inquiry=shantui-dh17", isFeatured: true, order: 15 }, { titleEn: "Gree Tropical T3 Inverter Air Conditioners", titleAr: "\u0645\u0643\u064A\u0641\u0627\u062A \u063A\u0631\u064A \u0627\u0644\u0627\u0633\u062A\u0648\u0627\u0626\u064A\u0629 \u0627\u0644\u0645\u0648\u0641\u0631\u0629 \u0644\u0644\u0637\u0627\u0642\u0629 \u0628\u0636\u0627\u063A\u0637 T3", titleZh: "\u683C\u529B T3 \u8D85\u91CD\u8F7D\u70ED\u5E26\u53D8\u9891\u8282\u80FD\u7A7A\u8C03", titleCkb: "\u0633\u067E\u0644\u06CE\u062A\u06CC \u06AF\u0631\u06CC \u06AF\u06D5\u0631\u0645\u0627\u06CC\u06CC \u0628\u06D5\u0647\u06CE\u0632 \u0628\u06C6 \u0647\u0627\u0648\u06CC\u0646\u06CC \u0639\u06CE\u0631\u0627\u0642", descriptionEn: "Heavy-duty T3 compressor air conditioning units engineered to sustain continuous powerful cooling in Iraqi summer temperatures exceeding 55\xB0C with minimal energy draw.", descriptionAr: "\u0623\u0646\u0638\u0645\u0629 \u062A\u0643\u064A\u064A\u0641 \u0627\u0633\u062A\u0648\u0627\u0626\u064A\u0629 \u0645\u062A\u0637\u0648\u0631\u0629 \u0628\u0636\u0627\u063A\u0637 T3 \u0641\u0627\u0626\u0642 \u0627\u0644\u062A\u062D\u0645\u0644\u060C \u0645\u0635\u0645\u0645\u0629 \u0644\u062A\u062D\u0642\u064A\u0642 \u062A\u0628\u0631\u064A\u062F \u0641\u0627\u0626\u0642 \u0645\u0633\u062A\u0645\u0631 \u062D\u062A\u0649 \u0641\u064A \u0630\u0631\u0648\u0629 \u0635\u064A\u0641 \u0627\u0644\u0639\u0631\u0627\u0642 \u0639\u0646\u062F \u062F\u0631\u062C\u0627\u062A \u062D\u0631\u0627\u0631\u0629 \u062A\u062A\u062C\u0627\u0648\u0632 55 \u0645\u0626\u0648\u064A\u0629.", descriptionZh: "\u914D\u5907\u8D85\u5F3AT3\u70ED\u5E26\u538B\u7F29\u673A\u7684\u5168\u76F4\u6D41\u53D8\u9891\u51B7\u6696\u7A7A\u8C03\uFF0C\u4E13\u4E3A55\u2103\u6781\u7AEF\u9177\u70ED\u4E2D\u4E1C\u76DB\u590F\u5DE5\u51B5\u91CF\u8EAB\u6253\u9020\uFF0C\u9AD8\u6548\u8282\u80FD\u5236\u51B7\u3002", descriptionCkb: "\u0633\u067E\u0644\u06CE\u062A \u0648 \u0633\u06CC\u0633\u062A\u06D5\u0645\u06CC \u0641\u06CE\u0646\u06A9\u06A9\u06D5\u0631\u06D5\u0648\u06D5\u06CC \u067E\u06CE\u0634\u06A9\u06D5\u0648\u062A\u0648\u0648 \u0628\u06D5 \u06A9\u06C6\u0645\u067E\u0631\u06CE\u0633\u06D5\u0631\u06CC \u0628\u06D5\u0647\u06CE\u0632\u06CC T3 \u06A9\u06D5 \u0644\u06D5 \u067E\u0644\u06D5\u06CC \u06AF\u06D5\u0631\u0645\u0627\u06CC \u0632\u06CC\u0627\u062A\u0631 \u0644\u06D5 55 \u067E\u0644\u06D5 \u0628\u06D5 \u06A9\u06D5\u0645\u062A\u0631\u06CC\u0646 \u06A9\u0627\u0631\u06D5\u0628\u0627 \u06A9\u0627\u0631 \u062F\u06D5\u06A9\u0627\u062A.", imageUrl: "https://images.unsplash.com/photo-1621905251189-08b45d6a269e?auto=format&fit=crop&w=1200&q=80", category: "HOME_APPLIANCES", link: "/en/contact?inquiry=gree-tropical-ac", isFeatured: true, order: 16 }, { titleEn: "Midea Breezeless T3 Extreme Climate Split AC", titleAr: "\u0645\u0643\u064A\u0641 \u0645\u064A\u062F\u064A\u0627 \u0628\u0631\u064A\u0632\u0644\u0633 \u0627\u0644\u0627\u0633\u062A\u0648\u0627\u0626\u064A \u0628\u062A\u0642\u0646\u064A\u0629 \u0627\u0644\u0647\u0648\u0627\u0621 \u063A\u064A\u0631 \u0627\u0644\u0645\u0628\u0627\u0634\u0631", titleZh: "\u7F8E\u7684 Breezeless \u65E0\u98CE\u611F\u70ED\u5E26\u6781\u7AEF\u6C14\u5019\u667A\u80FD\u7A7A\u8C03", titleCkb: "\u0633\u067E\u0644\u06CE\u062A\u06CC \u0645\u06CC\u062F\u06CC\u0627 \u0628\u0631\u06CC\u0632\u0644\u06CE\u0633 \u0628\u06C6 \u06A9\u06D5\u0634\u0648\u0647\u06D5\u0648\u0627\u06CC \u06AF\u06D5\u0631\u0645", descriptionEn: "Features 7,928 micro-holes dispersion avoiding direct blast, dual Inverter Quattro compressor operating reliably at up to 60\xB0C ambient temperatures.", descriptionAr: "\u062A\u0643\u0646\u0648\u0644\u0648\u062C\u064A\u0627 \u062A\u0634\u062A\u064A\u062A \u0627\u0644\u0647\u0648\u0627\u0621 \u0639\u0628\u0631 7928 \u062B\u0642\u0628\u0627\u064B \u062F\u0642\u064A\u0642\u0627\u064B \u0644\u062A\u0628\u0631\u064A\u062F \u0645\u0631\u064A\u062D \u0628\u062F\u0648\u0646 \u062A\u064A\u0627\u0631 \u0647\u0648\u0627\u0621 \u0645\u0628\u0627\u0634\u0631\u060C \u0645\u0639 \u0636\u0627\u063A\u0637 Inverter Quattro \u064A\u0639\u0645\u0644 \u062D\u062A\u0649 60 \u062F\u0631\u062C\u0629 \u0645\u0626\u0648\u064A\u0629.", descriptionZh: "\u72EC\u521B\u53CC\u5BFC\u98CE\u677F\u5185\u59167928\u4E2A\u5FAE\u5B54\u5BFC\u98CE\u6280\u672F\uFF0C\u5B9E\u73B0\u67D4\u548C\u65E0\u98CE\u611F\u8212\u9002\u964D\u6E29\uFF0C\u642D\u8F7DQuattro\u6781\u5149\u538B\u7F29\u673A\u65E0\u60E760\u2103\u6781\u9650\u9177\u70ED\u3002", descriptionCkb: "\u062A\u06D5\u06A9\u0646\u06D5\u0644\u06C6\u0698\u06CC\u0627\u06CC \u0628\u06CE\u0628\u0627\u06CC \u0641\u06CE\u0646\u06A9\u06A9\u0631\u062F\u0646\u06D5\u0648\u06D5 \u0628\u06D5 \u0632\u06CC\u0627\u062A\u0631 \u0644\u06D5 7 \u0647\u06D5\u0632\u0627\u0631 \u06A9\u0648\u0646\u06CC\u0644\u06D5\u06CC \u0628\u0686\u0648\u0648\u06A9 \u06A9\u06D5 \u0628\u06D5 \u0646\u06D5\u0631\u0645\u06CC \u0698\u0648\u0648\u0631\u06D5\u06A9\u06D5 \u0633\u0627\u0631\u062F \u062F\u06D5\u06A9\u0627\u062A\u06D5\u0648\u06D5 \u0644\u06D5 \u06AF\u06D5\u0631\u0645\u0627\u06CC \u0628\u06D5\u0631\u0632\u062F\u0627.", imageUrl: "https://images.unsplash.com/photo-1585338107529-13afc5f02586?auto=format&fit=crop&w=1200&q=80", category: "HOME_APPLIANCES", link: "/en/contact?inquiry=midea-breezeless", isFeatured: true, order: 17 }, { titleEn: "Haier Smart Multi-Door Twin-Inverter Refrigerator", titleAr: "\u062B\u0644\u0627\u062C\u0629 \u0648 \u0641\u0631\u064A\u0632\u0631 \u0647\u0627\u064A\u0631 \u0627\u0644\u0630\u0643\u064A\u0629 \u0645\u062A\u0639\u062F\u062F\u0629 \u0627\u0644\u0623\u0628\u0648\u0627\u0628 \u0628\u062A\u0628\u0631\u064A\u062F \u0645\u0632\u062F\u0648\u062C", titleZh: "\u6D77\u5C14 \u5168\u7A7A\u95F4\u4FDD\u9C9C\u53CC\u53D8\u9891\u591A\u95E8\u667A\u80FD\u51B0\u7BB1", titleCkb: "\u0633\u06D5\u0644\u0627\u062C\u06D5\u06CC \u0641\u0631\u06D5\u062F\u06D5\u0631\u06AF\u0627\u06CC \u0647\u0627\u06CC\u06D5\u0631 \u0628\u06D5 \u062A\u06D5\u06A9\u0646\u06D5\u0644\u06C6\u0698\u06CC\u0627\u06CC \u067E\u0627\u0634\u06D5\u06A9\u06D5\u0648\u062A\u06A9\u0631\u062F\u0646", descriptionEn: "520L executive capacity with Fresher Shield technology, ABT antibacterial ion sterilization, and 100-hour cooling retention during power outages.", descriptionAr: "\u0633\u0639\u0629 520 \u0644\u062A\u0631\u0627\u064B \u0628\u062A\u0642\u0646\u064A\u0629 \u0627\u0644\u062D\u0641\u0627\u0638 \u0639\u0644\u0649 \u0646\u0636\u0627\u0631\u0629 \u0627\u0644\u0623\u063A\u0630\u064A\u0629 \u0648\u062A\u0639\u0642\u064A\u0645 \u0623\u064A\u0648\u0646\u064A \u0628\u0646\u0633\u0628\u0629 99.9%\u060C \u0645\u0639 \u0627\u062D\u062A\u0641\u0627\u0638 \u0628\u0627\u0644\u0628\u0631\u0648\u062F\u0629 \u0644\u0645\u062F\u0629 100 \u0633\u0627\u0639\u0629 \u0623\u062B\u0646\u0627\u0621 \u0627\u0646\u0642\u0637\u0627\u0639 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0621.", descriptionZh: "520\u5347\u5927\u5BB9\u91CF\u591A\u95E8\u65D7\u8230\uFF0C\u642D\u8F7D\u5168\u7A7A\u95F4\u4FDD\u9C9C\u79D1\u6280\u4E0EABT\u52A8\u6001\u79BB\u5B50\u9664\u83CC\uFF0C\u5373\u4F7F\u65AD\u7535\u4EA6\u53EF\u4FDD\u6E29\u9501\u9C9C\u957F\u8FBE100\u5C0F\u65F6\uFF0C\u5951\u5408\u4F0A\u62C9\u514B\u5BB6\u5EAD\u521A\u9700\u3002", descriptionCkb: "\u0633\u06D5\u0644\u0627\u062C\u06D5\u06CC 520 \u0644\u06CC\u062A\u0631\u06CC \u0647\u0627\u06CC\u06D5\u0631 \u06A9\u06D5 \u0628\u06D5\u0628\u06CE \u06A9\u0627\u0631\u06D5\u0628\u0627\u0634 \u062A\u0627 100 \u06A9\u0627\u062A\u0698\u0645\u06CE\u0631 \u062E\u0648\u0627\u0631\u062F\u0646 \u0633\u0627\u0631\u062F \u0648 \u067E\u0627\u0631\u06CE\u0632\u0631\u0627\u0648 \u062F\u06D5\u0647\u06CE\u06B5\u06CE\u062A\u06D5\u0648\u06D5.", imageUrl: "https://images.unsplash.com/photo-1571175443880-49e1d25b2bc5?auto=format&fit=crop&w=1200&q=80", category: "HOME_APPLIANCES", link: "/en/contact?inquiry=haier-refrigerator", isFeatured: true, order: 18 }, { titleEn: "Roborock S8 Pro Ultra Smart Robotic Vacuum & Mop", titleAr: "\u0645\u0643\u0646\u0633\u0629 \u0631\u0648\u0628\u0648\u0631\u0648\u0643 S8 \u0628\u0631\u0648 \u0623\u0644\u062A\u0631\u0627 \u0627\u0644\u0630\u0643\u064A\u0629 \u0644\u0645\u0633\u062D \u0648\u062A\u0646\u0638\u064A\u0641 \u0627\u0644\u0645\u0646\u0627\u0632\u0644", titleZh: "\u77F3\u5934\u79D1\u6280 S8 Pro Ultra \u5168\u80FD\u516D\u5408\u4E00\u626B\u62D6\u673A\u5668\u4EBA", titleCkb: "\u06AF\u0633\u06A9 \u0648 \u0633\u0695\u06D5\u0631\u06CC \u0632\u06CC\u0631\u06D5\u06A9\u06CC \u0695\u06C6\u0628\u06C6\u0631\u06C6\u06A9 S8 \u067E\u0631\u06C6", descriptionEn: "RockDock Ultra all-in-one hands-free base with automatic mop washing, drying, and dust emptying, featuring 6000Pa hyper-suction and 3D reactive obstacle avoidance.", descriptionAr: "\u0642\u0627\u0639\u062F\u0629 \u0634\u062D\u0646 \u0645\u062A\u0643\u0627\u0645\u0644\u0629 \u062A\u0642\u0648\u0645 \u0628\u063A\u0633\u0644 \u0627\u0644\u0645\u0645\u0633\u062D\u0629 \u0648\u062A\u062C\u0641\u064A\u0641\u0647\u0627 \u0648\u062A\u0641\u0631\u064A\u063A \u0627\u0644\u063A\u0628\u0627\u0631 \u0622\u0644\u064A\u0627\u064B\u060C \u0628\u0642\u0648\u0629 \u0634\u0641\u0637 6000 \u0628\u0627\u0633\u0643\u0627\u0644 \u0648\u0645\u0644\u0627\u062D\u0629 \u0644\u064A\u0632\u0631\u064A\u0629 \u062B\u0644\u0627\u062B\u064A\u0629 \u0627\u0644\u0623\u0628\u0639\u0627\u062F.", descriptionZh: "\u5341\u9879\u5168\u80FD\u57FA\u7AD9\uFF0C\u81EA\u52A8\u6D17\u62D6\u5E03\u3001\u81EA\u52A8\u70D8\u5E72\u4E0E\u81EA\u52A8\u96C6\u5C18\uFF0C\u5177\u59076000Pa\u5F3A\u52B2\u98D3\u98CE\u5438\u529B\u4E0EReactive 3D\u7ED3\u6784\u5149\u907F\u969C\uFF0C\u8F7B\u677E\u5E94\u5BF9\u6C99\u5C18\u4FB5\u88AD\u3002", descriptionCkb: "\u0695\u06C6\u0628\u06C6\u062A\u06CC \u0632\u06CC\u0631\u06D5\u06A9 \u0628\u06C6 \u067E\u0627\u06A9\u06A9\u0631\u062F\u0646\u06D5\u0648\u06D5 \u0648 \u0633\u0695\u06CC\u0646 \u06A9\u06D5 \u062E\u06C6\u06CC \u062E\u0627\u0648\u06CE\u0646 \u062F\u06D5\u0628\u06CE\u062A\u06D5\u0648\u06D5 \u0648 \u062A\u06C6\u0632 \u0648 \u062E\u06C6\u06B5 \u0628\u06D5 \u0647\u06CE\u0632\u06CC 6000 \u0628\u0627\u0633\u0643\u0627\u06B5 \u0647\u06D5\u06B5\u062F\u06D5\u0645\u0698\u06CE\u062A.", imageUrl: "https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1200&q=80", category: "HOME_APPLIANCES", link: "/en/contact?inquiry=roborock-s8-ultra", isFeatured: true, order: 19 }, { titleEn: "TCL FreshAIR Series Smart Pro Wall-Mounted AC", titleAr: "\u0645\u0643\u064A\u0641 \u062A\u064A \u0633\u064A \u0625\u0644 \u0641\u0631\u064A\u0634 \u0625\u064A\u0631 \u0628\u062A\u0628\u0627\u062F\u0644 \u0627\u0644\u0647\u0648\u0627\u0621 \u0627\u0644\u0646\u0642\u064A \u0627\u0644\u062E\u0627\u0631\u062C\u064A", titleZh: "TCL \u65B0\u98CE\u7A7A\u8C03\u5C0F\u84DD\u7FFCPro\u7CFB\u5217", titleCkb: "\u0633\u067E\u0644\u06CE\u062A\u06CC \u062A\u06CC \u0633\u06CC \u0626\u06CE\u06B5 \u0628\u06D5 \u0633\u06CC\u0633\u062A\u06D5\u0645\u06CC \u0647\u06D5\u0648\u0627\u06CC \u067E\u0627\u06A9\u0698", descriptionEn: "Introduces 60m\xB3/h of fresh filtered outside air without opening windows, equipped with quadruple HEPA dust filtration and smart TVOC air quality sensing.", descriptionAr: "\u064A\u062F\u062E\u0644 60 \u0645\u062A\u0631\u0627\u064B \u0645\u0643\u0639\u0628\u0627\u064B \u0641\u064A \u0627\u0644\u0633\u0627\u0639\u0629 \u0645\u0646 \u0627\u0644\u0647\u0648\u0627\u0621 \u0627\u0644\u062E\u0627\u0631\u062C\u064A \u0627\u0644\u0645\u0646\u0642\u0649 \u0639\u0628\u0631 \u0641\u0644\u0627\u062A\u0631 HEPA \u0631\u0628\u0627\u0639\u064A\u0629\u060C \u0645\u0639 \u0645\u0633\u062A\u0634\u0639\u0631 \u0630\u0643\u064A \u0644\u062C\u0648\u062F\u0629 \u0627\u0644\u0647\u0648\u0627\u0621 \u062F\u0648\u0646 \u0627\u0644\u062D\u0627\u062C\u0629 \u0644\u0641\u062A\u062D \u0627\u0644\u0646\u0648\u0627\u0641\u0630.", descriptionZh: "\u5177\u590760m\xB3/h\u5927\u65B0\u98CE\u91CF\u5F15\u5165\u4E0E\u56DB\u91CDHEPA\u6DF1\u5EA6\u6EE4\u7F51\uFF0C\u5185\u7F6E\u7A7A\u6C14\u8D28\u91CFTVOC\u667A\u80FD\u663E\u793A\u73AF\uFF0C\u8BA9\u5C01\u95ED\u5BA4\u5185\u968F\u65F6\u547C\u5438\u5982\u68EE\u6797\u822C\u7EAF\u51C0\u6E05\u65B0\u7A7A\u6C14\u3002", descriptionCkb: "\u0633\u06CC\u0633\u062A\u06D5\u0645\u06CC \u062A\u06CE\u06A9\u06D5\u06B5\u06A9\u0631\u062F\u0646\u06CC \u0647\u06D5\u0648\u0627\u06CC \u067E\u0627\u06A9 \u0644\u06D5 \u062F\u06D5\u0631\u06D5\u0648\u06D5 \u0628\u06D5 \u0641\u0644\u062A\u06D5\u0631\u06CC \u062A\u0627\u06CC\u0628\u06D5\u062A\u06CC \u0686\u0648\u0627\u0631\u06CC\u0646\u06D5 \u0628\u06C6 \u0646\u06D5\u0647\u06CE\u0634\u062A\u0646\u06CC \u062A\u06C6\u0632 \u0648 \u0628\u06C6\u0646\u06CC \u0646\u0627\u062E\u06C6\u0634.", imageUrl: "https://images.unsplash.com/photo-1527011046414-4781f1f94f8c?auto=format&fit=crop&w=1200&q=80", category: "HOME_APPLIANCES", link: "/en/contact?inquiry=tcl-freshair", isFeatured: true, order: 20 }, { titleEn: "Xiaomi 14 Ultra & Smart AIoT Ecosystem", titleAr: "\u0634\u0627\u0648\u0645\u064A 14 \u0623\u0644\u062A\u0631\u0627 \u0645\u0639 \u0645\u0646\u0638\u0648\u0645\u0629 \u0625\u0646\u062A\u0631\u0646\u062A \u0627\u0644\u0623\u0634\u064A\u0627\u0621 \u0648\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A", titleZh: "\u5C0F\u7C7314 Ultra \u5F95\u5361\u5168\u7126\u6BB5\u65D7\u8230\u4E0E\u6F8E\u6E43\u667A\u8054\u751F\u6001", titleCkb: "\u0634\u0627\u06C6\u0645\u06CC 14 \u0626\u06C6\u06B5\u062A\u0631\u0627 \u0648 \u0633\u06CC\u0633\u062A\u06D5\u0645\u06CC \u0645\u0627\u06B5\u06CC \u0632\u06CC\u0631\u06D5\u06A9", descriptionEn: "Flagship Leica quad-camera mobile imaging technology and smart home ecosystem trending rapidly among tech-savvy Iraqi professionals and youth across Baghdad and Erbil.", descriptionAr: "\u0627\u0644\u0647\u0627\u062A\u0641 \u0627\u0644\u0631\u0627\u0626\u062F \u0627\u0644\u0645\u0632\u0648\u062F \u0628\u0639\u062F\u0633\u0627\u062A Leica \u0627\u0644\u0627\u062D\u062A\u0631\u0627\u0641\u064A\u0629 \u0648\u0645\u0646\u0638\u0648\u0645\u0629 \u0627\u0644\u0645\u0646\u0632\u0644 \u0627\u0644\u0630\u0643\u064A \u0627\u0644\u0645\u062A\u0643\u0627\u0645\u0644\u0629 \u0627\u0644\u0623\u0643\u062B\u0631 \u0631\u0648\u0627\u062C\u0627\u064B \u0648\u0645\u0628\u064A\u0639\u0627\u064B \u0641\u064A \u0623\u0633\u0648\u0627\u0642 \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A\u0627\u062A \u0641\u064A \u0628\u063A\u062F\u0627\u062F \u0648\u0623\u0631\u0628\u064A\u0644.", descriptionZh: "\u642D\u8F7D\u5F95\u5361\u5149\u5B66\u5168\u7126\u6BB5\u56DB\u6444\u7CFB\u7EDF\u7684\u5C0F\u7C73\u5F71\u50CF\u65D7\u8230\u624B\u673A\u53CA\u6F8E\u6E43OS\u667A\u80FD\u7269\u8054\u7F51\u751F\u6001\uFF0C\u5728\u4E2D\u4E1C\u53CA\u4F0A\u62C9\u514B\u5404\u5927\u90FD\u5E02\u79D1\u6280\u6D88\u8D39\u8005\u7FA4\u4F53\u4E2D\u6301\u7EED\u5F15\u9886\u70ED\u6F6E\u3002", descriptionCkb: "\u0645\u06C6\u0628\u0627\u06CC\u0644\u06CC \u0632\u06CC\u0631\u06D5\u06A9\u06CC \u067E\u06CE\u0634\u06A9\u06D5\u0648\u062A\u0648\u0648 \u0628\u06D5 \u06A9\u0627\u0645\u06CE\u0631\u0627\u06CC \u067E\u06CC\u0634\u06D5\u06AF\u06D5\u0631\u06CC \u0644\u0627\u06CC\u06A9\u0627 \u0648 \u0633\u06CC\u0633\u062A\u06D5\u0645\u06CC \u0645\u0627\u06B5\u06CC \u0632\u06CC\u0631\u06D5\u06A9\u060C \u06CC\u06D5\u06A9\u06CE\u06A9 \u0644\u06D5 \u067E\u0695\u0641\u0631\u06C6\u0634\u062A\u0631\u06CC\u0646\u06D5\u06A9\u0627\u0646 \u0644\u06D5 \u0628\u0627\u0632\u0627\u0695\u06D5\u06A9\u0627\u0646\u06CC \u0628\u06D5\u063A\u062F\u0627 \u0648 \u0647\u06D5\u0648\u0644\u06CE\u0631.", imageUrl: "https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?auto=format&fit=crop&w=1200&q=80", category: "CONSUMER_ELECTRONICS", link: "/en/contact?inquiry=xiaomi-iraq", isFeatured: true, order: 21 }, { titleEn: "DJI Agras T50 Smart Agricultural & Surveying Drone", titleAr: "\u0637\u0627\u0626\u0631\u0629 \u062F\u0631\u0648\u0646 \u062F\u064A \u062C\u064A\u0647 \u0622\u064A \u0623\u063A\u0631\u0627\u0633 T50 \u0627\u0644\u0630\u0643\u064A\u0629 \u0644\u0644\u0632\u0631\u0627\u0639\u0629 \u0648\u0645\u0633\u062D \u0627\u0644\u0623\u0631\u0627\u0636\u064A", titleZh: "\u5927\u7586\u519C\u4E1A DJI T50 \u65D7\u8230\u7EA7\u667A\u80FD\u519C\u4E1A\u822A\u6D4B\u65E0\u4EBA\u673A", titleCkb: "\u0641\u0695\u06C6\u06A9\u06D5\u06CC \u0628\u06CE\u0641\u0695\u06C6\u06A9\u06D5\u0648\u0627\u0646\u06CC \u06A9\u0634\u062A\u0648\u06A9\u0627\u06B5\u06CC \u062F\u06CC \u062C\u06D5\u06CC \u0626\u0627\u06CC T50", descriptionEn: "Heavy 50kg spraying payload with dual atomizing centrifugal sprinklers, active phased-array radar, and binocular vision for Iraqi date palm groves and agricultural plains.", descriptionAr: "\u0637\u0627\u0626\u0631\u0629 \u0628\u062F\u0648\u0646 \u0637\u064A\u0627\u0631 \u0628\u062D\u0645\u0648\u0644\u0629 \u0631\u0634 50 \u0643\u063A \u0648\u0645\u0631\u0627\u0648\u062D \u0637\u0631\u062F \u0645\u0631\u0643\u0632\u064A\u0629 \u0645\u0632\u062F\u0648\u062C\u0629 \u0645\u0639 \u0631\u0627\u062F\u0627\u0631 \u0646\u0634\u0637 \u0644\u062A\u063A\u0637\u064A\u0629 \u0628\u0633\u0627\u062A\u064A\u0646 \u0627\u0644\u0646\u062E\u064A\u0644 \u0648\u0627\u0644\u0645\u0632\u0627\u0631\u0639 \u0627\u0644\u0634\u0627\u0633\u0639\u0629 \u0641\u064A \u0627\u0644\u0639\u0631\u0627\u0642 \u0628\u062F\u0642\u0629 \u0639\u0627\u0644\u064A\u0629.", descriptionZh: "\u5171\u8F74\u53CC\u65CB\u7FFC\u52A8\u529B\u7CFB\u7EDF\uFF0C\u8F7D\u91CD50\u516C\u65A4\u55B7\u6D12\u4E0E75\u5347\u64AD\u6492\uFF0C\u642D\u8F7D\u6709\u6E90\u76F8\u63A7\u9635\u96F7\u8FBE\u4E0E\u53CC\u76EE\u89C6\u89C9\u7CFB\u7EDF\uFF0C\u5E7F\u6CDB\u8D4B\u80FD\u4F0A\u62C9\u514B\u6930\u67A3\u6797\u4E0E\u73B0\u4EE3\u704C\u6E89\u519C\u4E1A\u3002", descriptionCkb: "\u062F\u0631\u06C6\u0646\u06CC \u067E\u06CE\u0634\u06A9\u06D5\u0648\u062A\u0648\u0648\u06CC \u06A9\u0634\u062A\u0648\u06A9\u0627\u06B5\u06CC \u0628\u06D5 \u062A\u0648\u0627\u0646\u0627\u06CC \u0647\u06D5\u06B5\u06AF\u0631\u062A\u0646\u06CC 50 \u06A9\u06CC\u0644\u06C6\u06AF\u0631\u0627\u0645 \u0628\u06C6 \u062F\u06D5\u0631\u0645\u0627\u0646\u0695\u06CE\u0698\u06CC \u0648 \u0686\u0627\u0648\u062F\u06CE\u0631\u06CC \u06A9\u06CE\u06B5\u06AF\u06D5 \u0648 \u0628\u0627\u062E\u06D5\u06A9\u0627\u0646 \u0628\u06D5 \u0695\u0627\u062F\u0627\u0631\u06CC \u0632\u06CC\u0631\u06D5\u06A9.", imageUrl: "https://images.unsplash.com/photo-1527977966376-1c8408f9f108?auto=format&fit=crop&w=1200&q=80", category: "CONSUMER_ELECTRONICS", link: "/en/contact?inquiry=dji-agras-t50", isFeatured: true, order: 22 }, { titleEn: "Huawei MatePad Pro & PaperMatte Smart Office Suite", titleAr: "\u062A\u0627\u0628\u0644\u062A \u0647\u0648\u0627\u0648\u064A \u0645\u064A\u062A \u0628\u0627\u062F \u0628\u0631\u0648 \u0645\u0639 \u0634\u0627\u0634\u0629 \u0628\u064A\u0628\u0631\u0645\u0627\u062A \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u0644\u0644\u0627\u0646\u0639\u0643\u0627\u0633", titleZh: "\u534E\u4E3A MatePad Pro 13.2\u5BF8\u67D4\u6027OLED\u4E91\u6670\u67D4\u5149\u5C4F\u5E73\u677F", titleCkb: "\u062A\u0627\u0628\u0644\u06CE\u062A\u06CC \u0647\u06C6\u0648\u0627\u0648\u06CC \u0645\u06D5\u06CC\u067E\u0627\u062F \u067E\u0631\u06C6 \u0628\u06D5 \u0634\u0627\u0634\u06D5\u06CC \u062F\u0698\u06D5 \u0695\u06D5\u0646\u06AF\u062F\u0627\u0646\u06D5\u0648\u06D5", descriptionEn: "13.2-inch flexible OLED with nano-level anti-glare etching, NearLink M-Pencil with 10,000+ pressure levels, and PC-level WPS office productivity.", descriptionAr: "\u0634\u0627\u0634\u0629 OLED \u0645\u0631\u0646\u0629 \u0645\u0642\u0627\u0633 13.2 \u0628\u0648\u0635\u0629 \u0628\u062A\u0642\u0646\u064A\u0629 \u0645\u0636\u0627\u062F\u0629 \u0644\u0644\u0648\u0647\u062C \u0627\u0644\u0633\u0627\u0637\u0639\u060C \u0645\u0639 \u0642\u0644\u0645 NearLink \u0641\u0627\u0626\u0642 \u0627\u0644\u062D\u0633\u0627\u0633\u064A\u0629 \u0648\u0628\u0631\u0627\u0645\u062C \u0645\u0643\u062A\u0628\u064A\u0629 \u0628\u0645\u0633\u062A\u0648\u0649 \u0623\u062C\u0647\u0632\u0629 \u0627\u0644\u0643\u0645\u0628\u064A\u0648\u062A\u0631.", descriptionZh: "\u8D85\u8F7B\u8584\u5927\u5C3A\u5BF8\u67D4\u6027OLED\u5E73\u677F\uFF0C\u642D\u8F7D\u5FAE\u7EB3\u7C73\u8680\u523B\u9632\u7729\u5149\u67D4\u5149\u5C4F\u4E0E\u661F\u95EA\uFF08NearLink\uFF09\u8D85\u4E07\u7EA7\u538B\u611F\u624B\u5199\u7B14\uFF0C\u63D0\u4F9BPC\u7EA7\u539F\u751F\u684C\u9762\u529E\u516C\u4F53\u9A8C\u3002", descriptionCkb: "\u062A\u0627\u0628\u0644\u06CE\u062A\u06CC 13.2 \u0626\u06CC\u0646\u0686\u06CC \u0647\u06C6\u0648\u0627\u0648\u06CC \u0628\u06D5 \u0634\u0627\u0634\u06D5\u06CC \u062A\u0627\u06CC\u0628\u06D5\u062A \u062F\u0698\u06CC \u062A\u06CC\u0634\u06A9\u06CC \u0695\u06C6\u0698 \u0648 \u0642\u06D5\u06B5\u06D5\u0645\u06CC \u067E\u06CE\u0634\u06A9\u06D5\u0648\u062A\u0648\u0648 \u0628\u06C6 \u062F\u06CC\u0632\u0627\u06CC\u0646 \u0648 \u06A9\u0627\u0631\u06CC \u0641\u06D5\u0631\u0645\u06CC.", imageUrl: "https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?auto=format&fit=crop&w=1200&q=80", category: "CONSUMER_ELECTRONICS", link: "/en/contact?inquiry=huawei-matepad-pro", isFeatured: true, order: 23 }, { titleEn: "Anker SOLIX F3800 Ultra-Capacity Portable Power Station", titleAr: "\u0645\u062D\u0637\u0629 \u0627\u0644\u0637\u0627\u0642\u0629 \u0627\u0644\u0645\u062A\u0646\u0642\u0644\u0629 \u0623\u0646\u0643\u0631 \u0633\u0648\u0644\u064A\u0643\u0633 F3800 \u0639\u0627\u0644\u064A\u0629 \u0627\u0644\u0633\u0639\u0629", titleZh: "\u5B89\u514B\u521B\u65B0 ANKER SOLIX F3800 \u8D85\u5927\u5BB9\u91CF\u79FB\u52A8\u50A8\u80FD\u7535\u6E90", titleCkb: "\u0648\u06CE\u0633\u062A\u06AF\u06D5\u06CC \u06A9\u0627\u0631\u06D5\u0628\u0627\u06CC \u06AF\u06D5\u0695\u06C6\u06A9\u06CC \u0626\u0627\u0646\u06A9\u06D5\u0631 \u0633\u0648\u0644\u06CC\u06A9\u0633 F3800", descriptionEn: "3.84kWh LiFePO4 battery expandable up to 26.9kWh, with 6000W AC output (120V/240V split-phase) capable of direct EV charging and whole-home backup.", descriptionAr: "\u0628\u0637\u0627\u0631\u064A\u0629 \u0641\u0648\u0633\u0641\u0627\u062A \u062D\u062F\u064A\u062F \u0627\u0644\u0644\u064A\u062B\u064A\u0648\u0645 \u0628\u0633\u0639\u0629 3.84 \u0643\u064A\u0644\u0648\u0648\u0627\u0637/\u0633\u0627\u0639\u0629 \u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u062A\u0648\u0633\u0639\u0629 \u062D\u062A\u0649 26.9 \u0643\u064A\u0644\u0648\u0648\u0627\u0637/\u0633\u0627\u0639\u0629\u060C \u0645\u0639 \u0645\u062E\u0631\u062C 6000 \u0648\u0627\u0637 \u0644\u0634\u062D\u0646 \u0627\u0644\u0633\u064A\u0627\u0631\u0627\u062A \u0648\u062A\u0634\u063A\u064A\u0644 \u0627\u0644\u0645\u0646\u0627\u0632\u0644.", descriptionZh: "\u6807\u914D3.84\u5EA6\u78F7\u9178\u94C1\u9502\u9AD8\u5B89\u5168\u7535\u82AF\uFF0C\u652F\u6301\u81F3\u9AD8\u6269\u5C55\u81F326.9\u5EA6\uFF0C\u5177\u59076000W\u4EA4\u6D41\u53CC\u538B\u8F93\u51FA\uFF0C\u53EF\u76F4\u63A5\u4E3A\u7535\u52A8\u6C7D\u8F66\u8865\u80FD\u53CA\u5BB6\u5EAD\u5168\u5C4B\u65AD\u7535\u5E94\u6025\u3002", descriptionCkb: "\u067E\u0627\u062A\u0631\u06CC \u0632\u06D5\u0628\u06D5\u0644\u0627\u062D\u06CC \u06AF\u06D5\u0695\u06C6\u06A9 \u0628\u06D5 \u062A\u0648\u0627\u0646\u0627\u06CC 3.84 \u06A9\u06CC\u0644\u06C6\u0648\u0627\u062A \u0648 \u062F\u06D5\u0633\u062A\u067E\u06CE\u06A9\u0631\u062F\u0646\u06CC 6000 \u0648\u0627\u0637 \u0628\u06C6 \u06A9\u0627\u0631\u067E\u06CE\u06A9\u0631\u062F\u0646\u06CC \u062A\u06D5\u0648\u0627\u0648\u06CC \u0645\u0627\u06B5 \u0648 \u0628\u0627\u0631\u06AF\u0627\u0648\u06CC\u06A9\u0631\u062F\u0646\u06CC \u0626\u06C6\u062A\u06C6\u0645\u0628\u06CE\u0644\u06CC \u06A9\u0627\u0631\u06D5\u0628\u0627\u06CC\u06CC.", imageUrl: "https://images.unsplash.com/photo-1609091839311-d5365f9ff1c5?auto=format&fit=crop&w=1200&q=80", category: "CONSUMER_ELECTRONICS", link: "/en/contact?inquiry=anker-solix-f3800", isFeatured: true, order: 24 }, { titleEn: "Insta360 X4 8K 360-Degree AI Action & Surveying Camera", titleAr: "\u0643\u0627\u0645\u064A\u0631\u0627 \u0625\u0646\u0633\u062A\u0627 360 \u0625\u0643\u0633 4 \u0627\u0644\u0643\u0631\u0648\u064A\u0629 \u0628\u062F\u0642\u0629 8K \u0645\u0639 \u0645\u0639\u0627\u0644\u062C\u0629 \u0628\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A", titleZh: "\u5F71\u77F3 Insta360 X4 8K\u5168\u666F\u8FD0\u52A8\u4E0E\u73B0\u573A\u667A\u80FD\u6D4B\u7ED8\u76F8\u673A", titleCkb: "\u06A9\u0627\u0645\u06CE\u0631\u0627\u06CC 360 \u067E\u0644\u06D5\u06CC \u0626\u06CC\u0646\u0633\u062A\u0627360 X4 \u0628\u06D5 \u06A9\u0648\u0627\u0644\u06CE\u062A\u06CC 8K", descriptionEn: "Records ultra-high resolution 8K 30fps immersive 360 video powered by a 5nm AI chip, with FlowState stabilization and invisible selfie stick for construction and media.", descriptionAr: "\u062A\u0635\u0648\u064A\u0631 \u0641\u064A\u062F\u064A\u0648 \u0628\u0627\u0646\u0648\u0631\u0627\u0645\u064A \u0628\u062F\u0642\u0629 8K \u0641\u0627\u0626\u0642\u0629 \u0628\u0645\u0639\u062F\u0644 30 \u0625\u0637\u0627\u0631\u0627\u064B \u0641\u064A \u0627\u0644\u062B\u0627\u0646\u064A\u0629 \u0648\u0645\u0639\u0627\u0644\u062C \u0630\u0643\u0627\u0621 \u0627\u0635\u0637\u0646\u0627\u0639\u064A 5 \u0646\u0627\u0646\u0648\u0645\u062A\u0631\u060C \u0645\u062B\u0627\u0644\u064A\u0629 \u0644\u0645\u0648\u0627\u0642\u0639 \u0627\u0644\u0628\u0646\u0627\u0621 \u0648\u0627\u0644\u0625\u0646\u0634\u0627\u0621\u0627\u062A \u0648\u0627\u0644\u062A\u0648\u062B\u064A\u0642 \u0627\u0644\u0625\u0639\u0644\u0627\u0645\u064A.", descriptionZh: "\u539F\u751F8K 30fps\u8D85\u9AD8\u6E05\u5168\u666F\u89C6\u9891\uFF0C\u642D\u8F7D5nm\u5236\u7A0BAI\u964D\u566A\u82AF\u7247\u4E0EFlowState\u9632\u6296\uFF0C\u5728\u5DE5\u7A0B\u6D4B\u7ED8\u3001\u865A\u62DF\u770B\u5C55\u4E0E\u6781\u9650\u63A2\u9669\u4E2D\u5B9E\u73B0\u9690\u5F62\u81EA\u62CD\u6746\u6C89\u6D78\u4F53\u9A8C\u3002", descriptionCkb: "\u06A9\u0627\u0645\u06CE\u0631\u0627\u06CC \u0648\u06CE\u0646\u06D5\u06AF\u0631\u062A\u0646\u06CC 360 \u067E\u0644\u06D5 \u0628\u06D5 \u06A9\u0648\u0627\u0644\u06CE\u062A\u06CC 8K \u0648 \u062A\u06D5\u06A9\u0646\u06D5\u0644\u06C6\u0698\u06CC\u0627\u06CC \u0698\u06CC\u0631\u06CC \u062F\u06D5\u0633\u062A\u06A9\u0631\u062F \u0628\u06C6 \u062A\u06C6\u0645\u0627\u0631\u06A9\u0631\u062F\u0646\u06CC \u0634\u0648\u06CE\u0646\u06D5\u0648\u0627\u0631 \u0648 \u067E\u0631\u06C6\u0698\u06D5\u06A9\u0627\u0646\u06CC \u0628\u06CC\u0646\u0627\u0633\u0627\u0632\u06CC.", imageUrl: "https://images.unsplash.com/photo-1502920917128-1aa500764cbd?auto=format&fit=crop&w=1200&q=80", category: "CONSUMER_ELECTRONICS", link: "/en/contact?inquiry=insta360-x4", isFeatured: true, order: 25 }];
async function seedChineseProducts() {
  try {
    const existingCount = await prisma.chineseProduct.count();
    console.log(`\u{1F6CD}\uFE0F Checking Chinese Products... (Current count: ${existingCount})`);
    if (existingCount >= 25) {
      console.log("\u2705 Chinese Products already well-seeded with 5 products per sector.");
      return;
    }
    console.log("\u{1F331} Seeding 5 authentic products per sector into Chinese Products Showcase...");
    await prisma.chineseProduct.deleteMany();
    for (const item of ALL_CHINESE_PRODUCTS) {
      await prisma.chineseProduct.create({ data: item });
    }
    const finalCount = await prisma.chineseProduct.count();
    console.log(`\u2705 Successfully seeded ${finalCount} Chinese products (5 in each of the 5 sectors).`);
  } catch (err) {
    console.error("Error seeding Chinese products:", err);
  }
}
