var INITIAL_BUSINESS_OPPORTUNITIES = [{ slug: "basra-petrochem-hub", titleEn: "Basra Sovereign Petrochemical Complex & Associated Gas Valorization", titleAr: "\u0645\u062C\u0645\u0639 \u0627\u0644\u0628\u0635\u0631\u0629 \u0627\u0644\u0633\u064A\u0627\u062F\u064A \u0644\u0644\u0628\u062A\u0631\u0648\u0643\u064A\u0645\u0627\u0648\u064A\u0627\u062A \u0648\u062A\u062B\u0645\u064A\u0646 \u0627\u0644\u063A\u0627\u0632 \u0627\u0644\u0645\u0635\u0627\u062D\u0628", titleZh: "\u5DF4\u58EB\u62C9\u4E3B\u6743\u7EA7\u77F3\u5316\u8054\u5408\u4F53\u4E0E\u6CB9\u7530\u4F34\u751F\u6C14\u6DF1\u5EA6\u5229\u7528\u9879\u76EE", titleCkb: "\u06A9\u06C6\u0645\u06D5\u06B5\u06AF\u06D5\u06CC \u067E\u06CE\u062A\u0631\u06C6\u06A9\u06CC\u0645\u06CC\u0627\u06CC\u06CC \u0633\u06CC\u0627\u062F\u06CC \u0628\u06D5\u0633\u0631\u06D5 \u0648 \u0628\u06D5\u06A9\u0627\u0631\u0647\u06CE\u0646\u0627\u0646\u06CC \u06AF\u0627\u0632\u06CC \u0647\u0627\u0648\u067E\u06CE\u0686", summaryEn: "A tier-one downstream refining and polymer production facility designed to capture flaring gas across southern fields, providing 10-year fiscal immunity under Investment Law No. 13.", summaryAr: "\u0645\u0646\u0634\u0623\u0629 \u062A\u062D\u0648\u064A\u0644\u064A\u0629 \u0648\u062A\u0643\u0631\u064A\u0631\u064A\u0629 \u0644\u0625\u0646\u062A\u0627\u062C \u0627\u0644\u0628\u0648\u0644\u064A\u0645\u0631\u0627\u062A \u0645\u0635\u0645\u0645\u0629 \u0644\u0627\u0633\u062A\u062B\u0645\u0627\u0631 \u0627\u0644\u063A\u0627\u0632 \u0627\u0644\u0645\u062D\u0631\u0648\u0642 \u0641\u064A \u062D\u0642\u0648\u0644 \u0627\u0644\u062C\u0646\u0648\u0628\u060C \u0645\u0639 \u0625\u0639\u0641\u0627\u0621 \u0636\u0631\u064A\u0628\u064A \u0644\u0645\u062F\u0629 \u0661\u0660 \u0633\u0646\u0648\u0627\u062A \u0628\u0645\u0648\u062C\u0628 \u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0627\u0633\u062A\u062B\u0645\u0627\u0631 \u0631\u0642\u0645 \u0661\u0663.", summaryZh: "\u4F0A\u62C9\u514B\u5357\u90E8\u7279\u5927\u578B\u4E0B\u6E38\u7CBE\u7EC6\u5316\u5DE5\u4E0E\u805A\u5408\u7269\u751F\u4EA7\u57FA\u5730\uFF0C\u65E8\u5728\u6DF1\u5EA6\u56DE\u6536\u6CB9\u7530\u706B\u70AC\u653E\u7A7A\u5929\u7136\u6C14\uFF0C\u4EAB\u53D7\u7B2C13\u53F7\u6295\u8D44\u6CD5\u5168\u989D10\u5E74\u514D\u7A0E\u4F18\u60E0\u3002", summaryCkb: "\u067E\u0631\u06C6\u0698\u06D5\u06CC\u06D5\u06A9\u06CC \u06AF\u06D5\u0648\u0631\u06D5\u06CC \u067E\u0627\u06B5\u0627\u0648\u062A\u0646 \u0648 \u0628\u06D5\u0631\u0647\u06D5\u0645\u0647\u06CE\u0646\u0627\u0646\u06CC \u067E\u06C6\u0644\u06CC\u0645\u06D5\u0631 \u0628\u06C6 \u0633\u0648\u0648\u062F\u0648\u06D5\u0631\u06AF\u0631\u062A\u0646 \u0644\u06D5 \u06AF\u0627\u0632\u06CC \u06A9\u06CE\u06B5\u06AF\u06D5\u06A9\u0627\u0646\u06CC \u0628\u0627\u0634\u0648\u0648\u0631\u060C \u0628\u06D5 \u0628\u06D5\u062E\u0634\u06CC\u0646\u06CC \u0628\u0627\u062C \u0628\u06C6 \u0661\u0660 \u0633\u0627\u06B5 \u0628\u06D5\u067E\u06CE\u06CC \u06CC\u0627\u0633\u0627\u06CC \u0648\u06D5\u0628\u06D5\u0631\u0647\u06CE\u0646\u0627\u0646.", contentEn: "The Iraqi Ministry of Oil, in close bilateral coordination with Chinese petrochemical engineering consortiums, invites qualified industrial EPC partners for Phase II equity participation in the Basra Petrochemical Complex. The project integrates cryogenic separation units, ethylene crackers, and high-density polyethylene production. Sovereign guarantees include free allocation of 450 hectares in the Khor Al-Zubair Industrial Zone, zero customs tariff on imported engineering plant equipment, and full constitutional freedom to repatriate capital yields in RMB or USD.", contentAr: "\u062A\u062F\u0639\u0648 \u0648\u0632\u0627\u0631\u0629 \u0627\u0644\u0646\u0641\u0637 \u0627\u0644\u0639\u0631\u0627\u0642\u064A\u0629\u060C \u0628\u0627\u0644\u062A\u0646\u0633\u064A\u0642 \u0627\u0644\u062B\u0646\u0627\u0626\u064A \u0627\u0644\u0648\u062B\u064A\u0642 \u0645\u0639 \u062A\u062D\u0627\u0644\u0641\u0627\u062A \u0627\u0644\u0647\u0646\u062F\u0633\u0629 \u0627\u0644\u0628\u062A\u0631\u0648\u0643\u064A\u0645\u0627\u0648\u064A\u0629 \u0627\u0644\u0635\u064A\u0646\u064A\u0629\u060C \u0627\u0644\u0634\u0631\u0643\u0627\u0621 \u0627\u0644\u0635\u0646\u0627\u0639\u064A\u064A\u0646 \u0627\u0644\u0645\u0624\u0647\u0644\u064A\u0646 \u0644\u0644\u0645\u0634\u0627\u0631\u0643\u0629 \u0627\u0644\u0631\u0623\u0633\u0645\u0627\u0644\u064A\u0629 \u0641\u064A \u0627\u0644\u0645\u0631\u062D\u0644\u0629 \u0627\u0644\u062B\u0627\u0646\u064A\u0629 \u0645\u0646 \u0645\u062C\u0645\u0639 \u0627\u0644\u0628\u0635\u0631\u0629. \u064A\u0634\u0645\u0644 \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u0648\u062D\u062F\u0627\u062A \u0627\u0644\u0641\u0635\u0644 \u0627\u0644\u062A\u0628\u0631\u064A\u062F\u064A\u060C \u0648\u062A\u0643\u0633\u064A\u0631 \u0627\u0644\u0625\u064A\u062B\u064A\u0644\u064A\u0646\u060C \u0648\u0625\u0646\u062A\u0627\u062C \u0627\u0644\u0628\u0648\u0644\u064A \u0625\u064A\u062B\u064A\u0644\u064A\u0646. \u062A\u062A\u0636\u0645\u0646 \u0627\u0644\u0636\u0645\u0627\u0646\u0627\u062A \u0627\u0644\u0633\u064A\u0627\u062F\u064A\u0629 \u062A\u062E\u0635\u064A\u0635 \u0664\u0665\u0660 \u0647\u0643\u062A\u0627\u0631\u0627\u064B \u0641\u064A \u062E\u0648\u0631 \u0627\u0644\u0632\u0628\u064A\u0631 \u0645\u0639 \u0625\u0639\u0641\u0627\u0621 \u062C\u0645\u0631\u0643\u064A \u0643\u0627\u0645\u0644 \u0644\u062C\u0645\u064A\u0639 \u0627\u0644\u0645\u0639\u062F\u0627\u062A \u0648\u062D\u0631\u064A\u0629 \u062F\u0633\u062A\u0648\u0631\u064A\u0629 \u0643\u0627\u0645\u0644\u0629 \u0644\u062A\u062D\u0648\u064A\u0644 \u0627\u0644\u0623\u0631\u0628\u0627\u062D \u0628\u0627\u0644\u064A\u0648\u0627\u0646 \u0623\u0648 \u0627\u0644\u062F\u0648\u0644\u0627\u0631.", contentZh: "\u4F0A\u62C9\u514B\u77F3\u6CB9\u90E8\u5728\u4E2D\u4F0A\u53CC\u8FB9\u534F\u8C03\u6846\u67B6\u4E0B\uFF0C\u8BDA\u9080\u5177\u5907\u8D44\u8D28\u7684\u56FD\u9645\u5DE5\u7A0B\u4E0E\u80FD\u6E90\u8D22\u56E2\u53C2\u4E0E\u5DF4\u58EB\u62C9\u5927\u578B\u77F3\u5316\u57FA\u5730\u7B2C\u4E8C\u9636\u6BB5\u7684\u80A1\u6743\u5408\u4F5C\u3002\u9879\u76EE\u6DB5\u76D6\u6DF1\u51B7\u5206\u79BB\u88C5\u7F6E\u3001\u4E59\u70EF\u88C2\u89E3\u7089\u53CA\u9AD8\u5BC6\u5EA6\u805A\u4E59\u70EF\u751F\u4EA7\u7EBF\u3002\u4F0A\u62C9\u514B\u653F\u5E9C\u63D0\u4F9B\u7684\u4E3B\u6743\u4FDD\u969C\u5305\u62EC\uFF1A\u5728\u7956\u62DC\u5C14\u5DE5\u4E1A\u7279\u533A\u514D\u8D39\u5212\u62E8450\u516C\u9877\u5DE5\u4E1A\u7528\u5730\u3001\u5DE5\u7A0B\u603B\u627F\u5305\u8BBE\u5907\u8FDB\u53E3\u96F6\u5173\u7A0E\u3001\u4EE5\u53CA\u53D7\u5BAA\u6CD5\u4FDD\u62A4\u7684\u6295\u8D44\u6536\u76CA\u4EBA\u6C11\u5E01/\u7F8E\u5143\u5168\u989D\u81EA\u7531\u6C47\u51FA\u673A\u5236\u3002", contentCkb: "\u0648\u06D5\u0632\u0627\u0631\u06D5\u062A\u06CC \u0646\u06D5\u0648\u062A\u06CC \u0639\u06CE\u0631\u0627\u0642 \u0628\u06D5 \u0647\u06D5\u0645\u0627\u0647\u06D5\u0646\u06AF\u06CC \u0644\u06D5\u06AF\u06D5\u06B5 \u0647\u0627\u0648\u067E\u06D5\u06CC\u0645\u0627\u0646\u06CC \u06A9\u06C6\u0645\u067E\u0627\u0646\u06CC\u0627 \u0626\u06D5\u0646\u062F\u0627\u0632\u06CC\u0627\u0631\u06CC\u06CC\u06D5 \u0686\u06CC\u0646\u06CC\u06CC\u06D5\u06A9\u0627\u0646\u060C \u062F\u0627\u0648\u0627 \u0644\u06D5 \u0648\u06D5\u0628\u06D5\u0631\u0647\u06CE\u0646\u06D5\u0631\u0627\u0646 \u062F\u06D5\u06A9\u0627\u062A \u0628\u06C6 \u0628\u06D5\u0634\u062F\u0627\u0631\u06CC\u06A9\u0631\u062F\u0646 \u0644\u06D5 \u0642\u06C6\u0646\u0627\u063A\u06CC \u062F\u0648\u0648\u06D5\u0645\u06CC \u0645\u06C6\u0645\u06D5\u06B5\u06AF\u06D5\u06CC \u067E\u06CE\u062A\u0631\u06C6\u06A9\u06CC\u0645\u06CC\u0627\u06CC\u06CC \u0628\u06D5\u0633\u0631\u06D5. \u067E\u0695\u06C6\u0698\u06D5\u06A9\u06D5 \u062A\u06D5\u0631\u062E\u0627\u0646\u06A9\u0631\u062F\u0646\u06CC \u0664\u0665\u0660 \u0647\u06CE\u06A9\u062A\u0627\u0631 \u0632\u06D5\u0648\u06CC \u0648 \u0644\u06CE\u062E\u06C6\u0634\u0628\u0648\u0648\u0646\u06CC \u06AF\u0648\u0645\u0631\u06AF\u06CC \u0648 \u06AF\u0648\u0627\u0633\u062A\u0646\u06D5\u0648\u06D5\u06CC \u0626\u0627\u0632\u0627\u062F\u06CC \u0642\u0627\u0632\u0627\u0646\u062C \u0644\u06D5\u062E\u06C6\u062F\u06D5\u06AF\u0631\u06CE\u062A.", category: "ENERGY", sector: "Petrochemicals & Gas Capture", investmentValue: "$3.2 Billion", location: "Khor Al-Zubair, Basra", coverImage: "https://images.unsplash.com/photo-1518709268805-4e9042af9f23?auto=format&fit=crop&w=1200&q=80", featured: true, order: 1, status: "OPEN", contactEmail: "petrochem@iraqi-chineseagency.com" }, { slug: "sino-iraq-solar-microgrid", titleEn: "Muthanna & Najaf 1.4GW Desert Photovoltaic Microgrid Corridor", titleAr: "\u0645\u0645\u0631 \u062D\u0642\u0648\u0644 \u0627\u0644\u0637\u0627\u0642\u0629 \u0627\u0644\u0634\u0645\u0633\u064A\u0629 \u0627\u0644\u0643\u0647\u0631\u0648\u0636\u0648\u0626\u064A\u0629 \u0641\u064A \u0628\u0627\u062F\u064A\u0629 \u0627\u0644\u0645\u062B\u0646\u0649 \u0648\u0627\u0644\u0646\u062C\u0641 \u0628\u0642\u0648\u0629 1.4 \u063A\u064A\u063A\u0627\u0648\u0627\u0637", titleZh: "\u7A46\u8428\u7EB3\u4E0E\u7EB3\u6770\u592B\u6C99\u6F201.4\u5409\u74E6\u5927\u578B\u5149\u4F0F\u5FAE\u7535\u7F51\u8D70\u5ECA", titleCkb: "\u06A9\u06C6\u0631\u06CC\u062F\u06C6\u0631\u06CC \u0648\u06CE\u0633\u062A\u06AF\u06D5\u06CC \u0633\u06C6\u0644\u0627\u0631\u06CC \u062F\u06D5\u0634\u062A\u06CC \u0645\u0648\u0633\u06D5\u0646\u0646\u0627 \u0648 \u0646\u06D5\u062C\u06D5\u0641 \u0628\u06D5 \u062A\u0648\u0627\u0646\u0627\u06CC \u0661.\u0664 \u06AF\u06CE\u06AF\u0627\u0648\u0627\u062A", summaryEn: "Utility-scale desert solar installations linked directly with provincial transmission nodes, offering guaranteed 25-year sovereign power purchase agreements (PPA).", summaryAr: "\u0645\u062D\u0637\u0627\u062A \u0637\u0627\u0642\u0629 \u0634\u0645\u0633\u064A\u0629 \u0643\u0628\u0631\u0649 \u0641\u064A \u0628\u0627\u062F\u064A\u0629 \u0627\u0644\u062C\u0646\u0648\u0628 \u0645\u0631\u062A\u0628\u0637\u0629 \u0645\u0628\u0627\u0634\u0631\u0629 \u0628\u0634\u0628\u0643\u0629 \u0627\u0644\u0646\u0642\u0644 \u0627\u0644\u0648\u0637\u0646\u064A\u0629\u060C \u0645\u0639 \u0627\u062A\u0641\u0627\u0642\u064A\u0627\u062A \u0634\u0631\u0627\u0621 \u0637\u0627\u0642\u0629 \u0633\u064A\u0627\u062F\u064A\u0629 \u0645\u0636\u0645\u0648\u0646\u0629 \u0644\u0645\u062F\u0629 \u0662\u0665 \u0639\u0627\u0645\u0627\u064B (PPA).", summaryZh: "\u4F4D\u4E8E\u4F0A\u62C9\u514B\u5357\u90E8\u6C99\u6F20\u7684\u5927\u578B\u5E76\u7F51\u5149\u4F0F\u7535\u7AD9\u96C6\u7FA4\uFF0C\u76F4\u63A5\u63A5\u5165\u56FD\u5BB6\u4E3B\u5E72\u7535\u7F51\uFF0C\u4EAB\u6709\u4F0A\u62C9\u514B\u7535\u529B\u90E8\u63D0\u4F9B\u768425\u5E74\u671F\u4E3B\u6743\u7EA7\u7167\u4ED8\u4E0D\u8BAE\u8D2D\u7535\u534F\u8BAE\uFF08PPA\uFF09\u3002", summaryCkb: "\u0648\u06CE\u0633\u062A\u06AF\u06D5\u06CC \u0628\u06D5\u0631\u0647\u06D5\u0645\u0647\u06CE\u0646\u0627\u0646\u06CC \u06A9\u0627\u0631\u06D5\u0628\u0627\u06CC \u0633\u06C6\u0644\u0627\u0631 \u0644\u06D5 \u062F\u06D5\u0634\u062A\u0627\u06CC\u06CC\u06D5\u06A9\u0627\u0646\u06CC \u0628\u0627\u0634\u0648\u0648\u0631\u060C \u0628\u06D5\u0633\u062A\u0631\u0627\u0648\u06D5\u062A\u06D5\u0648\u06D5 \u0628\u06D5 \u062A\u06C6\u0695\u06CC \u0646\u06CC\u0634\u062A\u0645\u0627\u0646\u06CC \u0628\u06D5 \u06AF\u0631\u06CE\u0628\u06D5\u0633\u062A\u06CC \u0662\u0665 \u0633\u0627\u06B5\u06D5\u06CC \u06A9\u0695\u06CC\u0646\u06CC \u0648\u0632\u06D5.", contentEn: "Designed to relieve southern grid deficits, this bilateral initiative covers two solar parks equipped with dual-axis trackers and 300MWh battery energy storage systems (BESS). Consortium members benefit from fast-track customs clearance at Safwan, exemption from corporate income tax for 10 years, and designated sub-station interconnection rights.", contentAr: "\u0635\u064F\u0645\u0645\u062A \u0647\u0630\u0647 \u0627\u0644\u0645\u0628\u0627\u062F\u0631\u0629 \u0627\u0644\u062B\u0646\u0627\u0626\u064A\u0629 \u0644\u0633\u062F \u0627\u0644\u0639\u062C\u0632 \u0627\u0644\u0643\u0647\u0631\u0628\u0627\u0626\u064A\u060C \u0648\u062A\u063A\u0637\u064A \u062D\u0642\u0644\u064A\u0646 \u0644\u0644\u0637\u0627\u0642\u0629 \u0627\u0644\u0634\u0645\u0633\u064A\u0629 \u0645\u0632\u0648\u062F\u064A\u0646 \u0628\u0623\u0646\u0638\u0645\u0629 \u0627\u0644\u062A\u062A\u0628\u0639 \u0648\u0645\u0633\u062A\u0648\u062F\u0639\u0627\u062A \u062A\u062E\u0632\u064A\u0646 \u0637\u0627\u0642\u0629 \u0628\u0633\u0639\u0629 \u0663\u0660\u0660 \u0645\u064A\u063A\u0627\u0648\u0627\u0637/\u0633\u0627\u0639\u0629. \u064A\u0633\u062A\u0641\u064A\u062F \u0627\u0644\u0634\u0631\u0643\u0627\u0621 \u0645\u0646 \u0627\u0644\u062A\u062E\u0644\u064A\u0635 \u0627\u0644\u062C\u0645\u0631\u0643\u064A \u0627\u0644\u0641\u0648\u0631\u064A \u0641\u064A \u0633\u0641\u0648\u0627\u0646\u060C \u0648\u0627\u0644\u0625\u0639\u0641\u0627\u0621 \u0627\u0644\u0636\u0631\u064A\u0628\u064A \u0644\u0645\u062F\u0629 \u0661\u0660 \u0633\u0646\u0648\u0627\u062A\u060C \u0648\u0631\u0628\u0637 \u0645\u062C\u0627\u0646\u064A \u0628\u0645\u062D\u0637\u0627\u062A \u0627\u0644\u062A\u062D\u0648\u064A\u0644 \u0627\u0644\u0631\u0626\u064A\u0633\u064A\u0629.", contentZh: "\u8BE5\u4E2D\u4F0A\u53CC\u8FB9\u5021\u8BAE\u65E8\u5728\u5F7B\u5E95\u89E3\u51B3\u5357\u90E8\u7535\u7F51\u8D64\u5B57\uFF0C\u5305\u542B\u4E24\u5EA7\u914D\u5907\u53CC\u8F74\u8DDF\u8E2A\u652F\u67B6\u53CA300\u5146\u74E6\u65F6\u5148\u8FDB\u50A8\u80FD\u7CFB\u7EDF\u7684\u5927\u578B\u5149\u4F0F\u56ED\u533A\u3002\u5165\u9A7B\u4E2D\u4F01\u5C06\u4EAB\u53D7\u8428\u592B\u4E07\u53E3\u5CB8\u7EFF\u8272\u901A\u5173\u534F\u8BAE\u3001\u4F01\u4E1A\u6240\u5F97\u7A0E\u524D\u5341\u5E74\u5168\u514D\u4EE5\u53CA\u514D\u6536\u7535\u7F51\u63A5\u5165\u8D39\u7B49\u591A\u9879\u7279\u6743\u3002", contentCkb: "\u0626\u06D5\u0645 \u067E\u0631\u06C6\u0698\u06D5\u06CC\u06D5 \u0628\u06C6 \u0686\u0627\u0631\u06D5\u0633\u06D5\u0631\u06CC \u06A9\u06CE\u0634\u06D5\u06CC \u06A9\u0627\u0631\u06D5\u0628\u0627\u06CC \u0628\u0627\u0634\u0648\u0648\u0631\u06D5\u060C \u0628\u06D5 \u0628\u06D5\u06A9\u0627\u0631\u0647\u06CE\u0646\u0627\u0646\u06CC \u0633\u06CC\u0633\u062A\u06D5\u0645\u06CC \u06A9\u06C6\u06A9\u0631\u062F\u0646\u06D5\u0648\u06D5\u06CC \u0648\u0632\u06D5 \u0628\u06D5 \u0642\u06D5\u0628\u0627\u0631\u06D5\u06CC \u0663\u0660\u0660 \u0645\u06CE\u06AF\u0627\u0648\u0627\u062A/\u06A9\u0627\u062A\u0698\u0645\u06CE\u0631\u060C \u0644\u06D5\u06AF\u06D5\u06B5 \u0644\u06CE\u062E\u06C6\u0634\u0628\u0648\u0648\u0646\u06CC \u0628\u0627\u062C \u0628\u06C6 \u0645\u0627\u0648\u06D5\u06CC \u062F\u06D5 \u0633\u0627\u06B5.", category: "ENERGY", sector: "Renewable Energy & Storage", investmentValue: "$1.4 Billion", location: "Muthanna & Najaf Deserts", coverImage: "https://images.unsplash.com/photo-1509391365360-2e959784a276?auto=format&fit=crop&w=1200&q=80", featured: true, order: 2, status: "OPEN", contactEmail: "renewables@iraqi-chineseagency.com" }, { slug: "faw-port-logistics-freezone", titleEn: "Al-Faw Grand Port International Bonded Logistics & Free Zone Park", titleAr: "\u0627\u0644\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0644\u0648\u062C\u0633\u062A\u064A\u0629 \u0627\u0644\u062D\u0631\u0629 \u0648\u0627\u0644\u0645\u064A\u0646\u0627\u0621 \u0627\u0644\u062C\u0627\u0641 \u0627\u0644\u062F\u0648\u0644\u064A \u0641\u064A \u0645\u064A\u0646\u0627\u0621 \u0627\u0644\u0641\u0627\u0648 \u0627\u0644\u0643\u0628\u064A\u0631", titleZh: "\u5927\u6E2F\u6CD5\u5965\u6E2F\u56FD\u9645\u7EFC\u5408\u4FDD\u7A0E\u7269\u6D41\u56ED\u533A\u4E0E\u81EA\u7531\u8D38\u6613\u7279\u533A", titleCkb: "\u0646\u0627\u0648\u0686\u06D5\u06CC \u0626\u0627\u0632\u0627\u062F\u06CC \u0644\u06C6\u062C\u0633\u062A\u06CC \u0648 \u0628\u06D5\u0646\u062F\u06D5\u0631\u06CC \u0648\u0634\u06A9\u0627\u0646\u06CC \u0644\u06D5 \u0628\u06D5\u0646\u062F\u06D5\u0631\u06CC \u0641\u0627\u0648-\u06CC \u06AF\u06D5\u0648\u0631\u06D5", summaryEn: "Development of automated dry-dock warehouses, multi-modal rail interchange terminals, and deepwater container yards connecting the Maritime Silk Road to the Dry Canal.", summaryAr: "\u062A\u0637\u0648\u064A\u0631 \u0645\u0633\u062A\u0648\u062F\u0639\u0627\u062A \u0627\u0644\u062D\u0648\u0636 \u0627\u0644\u062C\u0627\u0641 \u0627\u0644\u0645\u0624\u062A\u0645\u062A\u0629\u060C \u0648\u0645\u062D\u0637\u0627\u062A \u0627\u0644\u062A\u0628\u0627\u062F\u0644 \u0627\u0644\u0633\u0643\u0643\u064A \u0645\u062A\u0639\u062F\u062F\u0629 \u0627\u0644\u0648\u0633\u0627\u0626\u0637\u060C \u0648\u0633\u0627\u062D\u0627\u062A \u0627\u0644\u062D\u0627\u0648\u064A\u0627\u062A \u0627\u0644\u0639\u0645\u064A\u0642\u0629 \u0644\u0631\u0628\u0637 \u0637\u0631\u064A\u0642 \u0627\u0644\u062D\u0631\u064A\u0631 \u0627\u0644\u0628\u062D\u0631\u064A \u0628\u0627\u0644\u0642\u0646\u0627\u0629 \u0627\u0644\u062C\u0627\u0641\u0629.", summaryZh: "\u4F9D\u6258\u6CD5\u5965\u6DF1\u6C34\u5927\u6E2F\u6838\u5FC3\u6E2F\u533A\uFF0C\u5EFA\u8BBE\u96C6\u81EA\u52A8\u5316\u4FDD\u7A0E\u4ED3\u50A8\u3001\u94C1\u6C34\u8054\u8FD0\u67A2\u7EBD\u7AD9\u53CA\u8D85\u6DF1\u6C34\u96C6\u88C5\u7BB1\u5806\u573A\u4E8E\u4E00\u4F53\u7684\u9646\u6D77\u65B0\u901A\u9053\u6218\u7565\u67A2\u7EBD\u3002", summaryCkb: "\u067E\u06D5\u0631\u06D5\u067E\u06CE\u062F\u0627\u0646\u06CC \u06A9\u06C6\u06AF\u0627\u06A9\u0627\u0646\u06CC \u062D\u06D5\u0648\u0632\u06CC \u0648\u0634\u06A9 \u0648 \u0648\u06CE\u0633\u062A\u06AF\u06D5\u06A9\u0627\u0646\u06CC \u0647\u06CE\u06B5\u06CC \u0626\u0627\u0633\u0646 \u0628\u06C6 \u0628\u06D5\u0633\u062A\u0646\u06D5\u0648\u06D5\u06CC \u0695\u06CE\u06AF\u0627\u06CC \u0626\u0627\u0648\u0631\u06CC\u0634\u0645\u06CC \u062F\u06D5\u0631\u06CC\u0627\u06CC\u06CC \u0628\u06D5 \u06A9\u06D5\u0646\u0627\u06B5\u06CC \u0648\u0634\u06A9\u0627\u0646\u06CC.", contentEn: "The General Company for Ports of Iraq (GCPI) offers multi-year concession contracts for international logistics operators to build bonded freight stations, cold-storage logistics chains, and container inspection gantries. The zone provides corporate zero-tariff status on raw re-exports, zero municipal fees for 15 years, and dedicated maritime berths constructed to 19.5m draft standards.", contentAr: "\u062A\u0637\u0631\u062D \u0627\u0644\u0634\u0631\u0643\u0629 \u0627\u0644\u0639\u0627\u0645\u0629 \u0644\u0645\u0648\u0627\u0646\u0626 \u0627\u0644\u0639\u0631\u0627\u0642 \u0639\u0642\u0648\u062F \u0627\u0645\u062A\u064A\u0627\u0632 \u0637\u0648\u064A\u0644\u0629 \u0627\u0644\u0623\u062C\u0644 \u0644\u0644\u0645\u0634\u063A\u0644\u064A\u0646 \u0627\u0644\u0644\u0648\u062C\u0633\u062A\u064A\u064A\u0646 \u0644\u062A\u0634\u064A\u064A\u062F \u0645\u062D\u0637\u0627\u062A \u0627\u0644\u0634\u062D\u0646 \u0627\u0644\u062C\u0645\u0631\u0643\u064A\u060C \u0648\u0633\u0644\u0627\u0633\u0644 \u0627\u0644\u062A\u0628\u0631\u064A\u062F\u060C \u0648\u0628\u0648\u0627\u0628\u0627\u062A \u0641\u062D\u0635 \u0627\u0644\u062D\u0627\u0648\u064A\u0627\u062A. \u062A\u0648\u0641\u0631 \u0627\u0644\u0645\u0646\u0637\u0642\u0629 \u0635\u0641\u0629 \u0627\u0644\u0625\u0639\u0641\u0627\u0621 \u0627\u0644\u062C\u0645\u0631\u0643\u064A \u0627\u0644\u0643\u0627\u0645\u0644 \u0644\u0644\u0645\u0648\u0627\u062F \u0627\u0644\u0645\u0639\u0627\u062F \u062A\u0635\u062F\u064A\u0631\u0647\u0627\u060C \u0648\u0625\u0639\u0641\u0627\u0621 \u0645\u0646 \u0627\u0644\u0631\u0633\u0648\u0645 \u0627\u0644\u0628\u0644\u062F\u064A\u0629 \u0644\u0645\u062F\u0629 \u0661\u0665 \u0639\u0627\u0645\u0627\u064B\u060C \u0648\u0623\u0631\u0635\u0641\u0629 \u0628\u0639\u0645\u0642 \u0661\u0669.\u0665 \u0645\u062A\u0631\u0627\u064B.", contentZh: "\u4F0A\u62C9\u514B\u56FD\u5BB6\u6E2F\u52A1\u5C40\uFF08GCPI\uFF09\u9762\u5411\u5177\u5907\u5B9E\u529B\u7684\u56FD\u9645\u7269\u6D41\u8FD0\u8425\u5546\u63A8\u51FA\u7279\u8BB8\u7ECF\u8425\u5408\u7EA6\uFF0C\u6DB5\u76D6\u7EFC\u5408\u4FDD\u7A0E\u8D27\u8FD0\u7AD9\u3001\u533B\u836F\u51B7\u94FE\u67A2\u7EBD\u53CA\u96C6\u88C5\u7BB1\u667A\u80FD\u5B89\u68C0\u7CFB\u7EDF\u5EFA\u8BBE\u3002\u7279\u533A\u4EAB\u6709\u8F6C\u53E3\u8D38\u6613\u5B8C\u5168\u514D\u7A0E\u3001\u524D15\u5E74\u5E02\u653F\u6536\u8D39\u8C41\u514D\uFF0C\u5E76\u76F4\u63A5\u914D\u5957\u5403\u6C34\u6DF1\u5EA6\u8FBE19.5\u7C73\u7684\u4E16\u754C\u7EA7\u6DF1\u6C34\u96C6\u88C5\u7BB1\u6CCA\u4F4D\u3002", contentCkb: "\u06A9\u06C6\u0645\u067E\u0627\u0646\u06CC\u0627\u06CC \u06AF\u0634\u062A\u06CC \u0628\u06D5\u0646\u062F\u06D5\u0631\u06D5\u06A9\u0627\u0646\u06CC \u0639\u06CE\u0631\u0627\u0642 \u06AF\u0631\u06CE\u0628\u06D5\u0633\u062A\u06CC \u062F\u0631\u06CE\u0698\u062E\u0627\u06CC\u06D5\u0646 \u067E\u06CE\u0634\u06A9\u06D5\u0634 \u062F\u06D5\u06A9\u0627\u062A \u0628\u06C6 \u062F\u0631\u0648\u0633\u062A\u06A9\u0631\u062F\u0646\u06CC \u0646\u0627\u0648\u0686\u06D5\u06CC \u06AF\u0648\u0645\u0631\u06AF\u06CC \u0648 \u06A9\u06C6\u06AF\u0627\u06CC \u0633\u0627\u0631\u062F\u06A9\u06D5\u0631\u06D5\u0648\u06D5 \u0628\u06D5 \u0628\u06D5\u062E\u0634\u06CC\u0646\u06CC \u0628\u0627\u062C \u0644\u06D5 \u0628\u0627\u062C\u06CC \u0634\u0627\u0631\u06D5\u0648\u0627\u0646\u06CC \u0628\u06C6 \u0661\u0665 \u0633\u0627\u06B5.", category: "INFRASTRUCTURE", sector: "Maritime Logistics & Free Zones", investmentValue: "$850 Million", location: "Al-Faw Peninsula, Basra", coverImage: "https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?auto=format&fit=crop&w=1200&q=80", featured: true, order: 3, status: "OPEN", contactEmail: "fawlogistics@iraqi-chineseagency.com" }, { slug: "tigris-drip-irrigation-agritech", titleEn: "Tigris Basin High-Efficiency Precision Agritech & Drip Irrigation", titleAr: "\u0645\u0634\u0631\u0648\u0639 \u0627\u0644\u062A\u0642\u0646\u064A\u0627\u062A \u0627\u0644\u0632\u0631\u0627\u0639\u064A\u0629 \u0627\u0644\u062D\u062F\u064A\u062B\u0629 \u0648\u0627\u0644\u0631\u064A \u0628\u0627\u0644\u062A\u0646\u0642\u064A\u0637 \u0639\u0627\u0644\u064A \u0627\u0644\u0643\u0641\u0627\u0621\u0629 \u0641\u064A \u062D\u0648\u0636 \u062F\u062C\u0644\u0629", titleZh: "\u5E95\u683C\u91CC\u65AF\u6CB3\u6D41\u57DF\u73B0\u4EE3\u8282\u6C34\u7CBE\u51C6\u519C\u4E1A\u4E0E\u667A\u6167\u6EF4\u704C\u6280\u672F\u8F6C\u79FB\u57FA\u5730", titleCkb: "\u067E\u0695\u06C6\u0698\u06D5\u06CC \u062A\u06D5\u06A9\u0646\u06D5\u0644\u06C6\u062C\u06CC\u0627\u06CC \u0646\u0648\u06CE\u06CC \u06A9\u0634\u062A\u0648\u06A9\u0627\u06B5\u06CC \u0648 \u0626\u0627\u0648\u062F\u06CE\u0631\u06CC \u062F\u06B5\u06C6\u067E\u06D5\u06CC\u06CC \u0644\u06D5 \u062D\u06D5\u0648\u0632\u06CC \u062F\u06CC\u062C\u0644\u06D5", summaryEn: "Modernizing cereal and high-yield crop cultivation across 80,000 dunams in Wasit and Dhi Qar utilizing Chinese low-pressure automated drip equipment and drought-resistant seeds.", summaryAr: "\u062A\u062D\u062F\u064A\u062B \u0632\u0631\u0627\u0639\u0629 \u0627\u0644\u062D\u0628\u0648\u0628 \u0648\u0627\u0644\u0645\u062D\u0627\u0635\u064A\u0644 \u0639\u0627\u0644\u064A\u0629 \u0627\u0644\u0625\u0646\u062A\u0627\u062C\u064A\u0629 \u0639\u0644\u0649 \u0645\u0633\u0627\u062D\u0629 \u0668\u0660 \u0623\u0644\u0641 \u062F\u0648\u0646\u0645 \u0641\u064A \u0648\u0627\u0633\u0637 \u0648\u0630\u064A \u0642\u0627\u0631 \u0628\u0627\u0644\u0627\u0639\u062A\u0645\u0627\u062F \u0639\u0644\u0649 \u062A\u0642\u0646\u064A\u0627\u062A \u0627\u0644\u0631\u064A \u0627\u0644\u0630\u0643\u064A\u0629 \u0648\u0627\u0644\u0628\u0630\u0648\u0631 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u0644\u0644\u062C\u0641\u0627\u0641.", summaryZh: "\u5728\u74E6\u897F\u7279\u7701\u548C\u6D4E\u52A0\u5C14\u77018\u4E07\u675C\u7EB3\u59C6\u826F\u7530\u63A8\u5E7F\u5E94\u7528\u4E2D\u56FD\u5148\u8FDB\u5FAE\u538B\u7CBE\u51C6\u6C34\u80A5\u4E00\u4F53\u5316\u6EF4\u704C\u7CFB\u7EDF\u53CA\u8010\u65F1\u9AD8\u4EA7\u79CD\u4E1A\u6280\u672F\u3002", summaryCkb: "\u0646\u0648\u06CE\u06A9\u0631\u062F\u0646\u06D5\u0648\u06D5\u06CC \u06A9\u06D5\u0631\u062A\u06CC \u06A9\u0634\u062A\u0648\u06A9\u0627\u06B5\u06CC \u0644\u06D5\u0633\u06D5\u0631 \u0695\u0648\u0648\u0628\u06D5\u0631\u06CC \u0668\u0660 \u0647\u06D5\u0632\u0627\u0631 \u062F\u06C6\u0646\u0645 \u0644\u06D5 \u0648\u0627\u0633\u062A \u0648 \u0632\u06CC\u0642\u0627\u0631 \u0628\u06D5 \u0628\u06D5\u06A9\u0627\u0631\u0647\u06CE\u0646\u0627\u0646\u06CC \u0633\u06CC\u0633\u062A\u06D5\u0645\u06CC \u0626\u0627\u0648\u062F\u06CE\u0631\u06CC \u067E\u06CE\u0634\u06A9\u06D5\u0648\u062A\u0648\u0648 \u0648 \u062A\u06C6\u0648\u06CC \u0628\u06D5\u0647\u06CE\u0632.", contentEn: "In partnership with the Iraqi Supreme Agricultural Committee, this initiative grants 25-year leaseholds on agricultural state lands at nominal rates. Chinese agricultural equipment manufacturers are offered long-term off-take agreements by the Ministry of Trade for wheat and grain production, alongside guaranteed water discharge allocations from modern reservoir off-takes.", contentAr: "\u0628\u0627\u0644\u0634\u0631\u0627\u0643\u0629 \u0645\u0639 \u0627\u0644\u0644\u062C\u0646\u0629 \u0627\u0644\u0632\u0631\u0627\u0639\u064A\u0629 \u0627\u0644\u0639\u0644\u064A\u0627\u060C \u064A\u0645\u0646\u062D \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u0639\u0642\u0648\u062F \u0625\u064A\u062C\u0627\u0631 \u0644\u0645\u062F\u0629 \u0662\u0665 \u0639\u0627\u0645\u0627\u064B \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0627\u0636\u064A \u0627\u0644\u0632\u0631\u0627\u0639\u064A\u0629 \u0628\u0623\u0633\u0639\u0627\u0631 \u0631\u0645\u0632\u064A\u0629. \u064A\u062D\u0635\u0644 \u0645\u0635\u0646\u0639\u0648 \u0627\u0644\u0645\u0639\u062F\u0627\u062A \u0627\u0644\u0632\u0631\u0627\u0639\u064A\u0629 \u0639\u0644\u0649 \u0639\u0642\u0648\u062F \u0634\u0631\u0627\u0621 \u062D\u0643\u0648\u0645\u064A\u0629 \u0637\u0648\u064A\u0644\u0629 \u0627\u0644\u0623\u062C\u0644 \u0644\u0645\u062D\u0627\u0635\u064A\u0644 \u0627\u0644\u062D\u0646\u0637\u0629\u060C \u0645\u0639 \u0636\u0645\u0627\u0646 \u062D\u0635\u0635 \u0645\u0627\u0626\u064A\u0629 \u0645\u0642\u0646\u0646\u0629 \u0645\u0646 \u0627\u0644\u0633\u062F\u0648\u062F \u0648\u0627\u0644\u062E\u0632\u0627\u0646\u0627\u062A \u0627\u0644\u062D\u062F\u064A\u062B\u0629.", contentZh: "\u9879\u76EE\u4E0E\u4F0A\u62C9\u514B\u6700\u9AD8\u519C\u4E1A\u59D4\u5458\u4F1A\u8054\u5408\u5F00\u5C55\uFF0C\u4E3A\u6295\u8D44\u4E3B\u4F53\u63D0\u4F9B25\u5E74\u671F\u8C61\u5F81\u6027\u5730\u79DF\u7684\u56FD\u6709\u519C\u4E1A\u7528\u5730\u79DF\u8D41\u6743\u3002\u4F0A\u62C9\u514B\u8D38\u6613\u90E8\u4E3A\u751F\u4EA7\u7684\u5C0F\u9EA6\u53CA\u4F18\u8D28\u7ECF\u6D4E\u4F5C\u7269\u63D0\u4F9B\u5168\u989D\u4E3B\u6743\u515C\u5E95\u6536\u8D2D\u534F\u8BAE\uFF0C\u5E76\u7531\u6C34\u8D44\u6E90\u90E8\u4E3A\u667A\u6167\u704C\u6E89\u793A\u8303\u533A\u63D0\u4F9B\u6392\u704C\u6C34\u6E90\u4FDD\u969C\u3002", contentCkb: "\u0628\u06D5 \u0647\u0627\u0648\u0628\u06D5\u0634\u06CC \u0644\u06D5\u06AF\u06D5\u06B5 \u0644\u06CC\u0698\u0646\u06D5\u06CC \u0628\u0627\u06B5\u0627\u06CC \u06A9\u0634\u062A\u0648\u06A9\u0627\u06B5\u060C \u0632\u06D5\u0648\u06CC \u06A9\u0634\u062A\u0648\u06A9\u0627\u06B5\u06CC \u0628\u06C6 \u0662\u0665 \u0633\u0627\u06B5 \u0628\u06D5 \u0646\u0631\u062E\u06CC \u0695\u06D5\u0645\u0632\u06CC \u062F\u0627\u0628\u06CC\u0646 \u062F\u06D5\u06A9\u0631\u06CE\u062A\u060C \u0644\u06D5\u06AF\u06D5\u06B5 \u06AF\u0631\u06CE\u0628\u06D5\u0633\u062A\u06CC \u06A9\u0695\u06CC\u0646\u06D5\u0648\u06D5\u06CC \u0628\u06D5\u0631\u0647\u06D5\u0645 \u0644\u06D5\u0644\u0627\u06CC\u06D5\u0646 \u0648\u06D5\u0632\u0627\u0631\u06D5\u062A\u06CC \u0628\u0627\u0632\u0631\u06AF\u0627\u0646\u06CC\u06CC\u06D5\u0648\u06D5.", category: "AGRICULTURE", sector: "Precision Agronomy & Water Conservation", investmentValue: "$320 Million", location: "Wasit & Dhi Qar Governorates", coverImage: "https://images.unsplash.com/photo-1592417817098-8f3d6eb22509?auto=format&fit=crop&w=1200&q=80", featured: false, order: 4, status: "OPEN", contactEmail: "agritech@iraqi-chineseagency.com" }, { slug: "baghdad-erbil-fiber-datacenter", titleEn: "Baghdad-Kirkuk-Erbil Sovereign Terrestrial Fiber & Cloud Datacenter Backbone", titleAr: "\u0627\u0644\u0639\u0645\u0648\u062F \u0627\u0644\u0641\u0642\u0631\u064A \u0644\u0644\u0623\u0644\u064A\u0627\u0641 \u0627\u0644\u0636\u0648\u0626\u064A\u0629 \u0648\u0645\u0631\u0627\u0643\u0632 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0633\u062D\u0627\u0628\u064A\u0629 \u0628\u064A\u0646 \u0628\u063A\u062F\u0627\u062F \u0648\u0643\u0631\u0643\u0648\u0643 \u0648\u0623\u0631\u0628\u064A\u0644", titleZh: "\u5DF4\u683C\u8FBE-\u57FA\u5C14\u5E93\u514B-\u57C3\u5C14\u6BD4\u52D2\u56FD\u5BB6\u7EA7\u9646\u57FA\u5149\u7F06\u5E72\u7EBF\u4E0E\u4E3B\u6743\u4E91\u6570\u636E\u4E2D\u5FC3", titleCkb: "\u0647\u06CE\u06B5\u06CC \u0633\u06D5\u0631\u06D5\u06A9\u06CC \u0641\u0627\u06CC\u0628\u06D5\u0631 \u0626\u06C6\u067E\u062A\u06CC\u06A9 \u0648 \u0633\u06D5\u0646\u062A\u06D5\u0631\u06CC \u062F\u0627\u062A\u0627\u06CC \u0647\u06D5\u0648\u0631\u06CC \u0644\u06D5 \u0646\u06CE\u0648\u0627\u0646 \u0628\u06D5\u063A\u062F\u0627\u060C \u06A9\u06D5\u0631\u06A9\u0648\u0648\u06A9 \u0648 \u0647\u06D5\u0648\u0644\u06CE\u0631", summaryEn: "Deployment of 1,200 km dual-redundant buried fiber optic corridors and twin Tier-III sovereign data facilities in Baghdad and Erbil to support e-governance and bilateral digital clearing.", summaryAr: "\u0645\u062F \u0661\u0662\u0660\u0660 \u0643\u0645 \u0645\u0646 \u0643\u0627\u0628\u0644\u0627\u062A \u0627\u0644\u0623\u0644\u064A\u0627\u0641 \u0627\u0644\u0636\u0648\u0626\u064A\u0629 \u0627\u0644\u0645\u0632\u062F\u0648\u062C\u0629 \u0648\u0625\u0646\u0634\u0627\u0621 \u0645\u0631\u0643\u0632\u064A \u0628\u064A\u0627\u0646\u0627\u062A \u0633\u064A\u0627\u062F\u064A\u064A\u0646 \u0645\u0646 \u0627\u0644\u0645\u0633\u062A\u0648\u0649 \u0627\u0644\u062B\u0627\u0644\u062B \u0641\u064A \u0628\u063A\u062F\u0627\u062F \u0648\u0623\u0631\u0628\u064A\u0644 \u0644\u062F\u0639\u0645 \u0627\u0644\u062D\u0648\u0643\u0645\u0629 \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A\u0629 \u0648\u0627\u0644\u0645\u0642\u0627\u0635\u0629 \u0627\u0644\u0631\u0642\u0645\u064A\u0629.", summaryZh: "\u6577\u8BBE1200\u516C\u91CC\u9AD8\u5197\u4F59\u57CB\u5730\u5E72\u7EBF\u5149\u7F06\uFF0C\u5E76\u5728\u5DF4\u683C\u8FBE\u4E0E\u57C3\u5C14\u6BD4\u52D2\u5EFA\u8BBE\u4E24\u5EA7\u56FD\u9645Tier-III\u7EA7\u9AD8\u53EF\u7528\u4E3B\u6743\u6570\u636E\u4E2D\u5FC3\uFF0C\u5168\u65B9\u4F4D\u652F\u6491\u7535\u5B50\u653F\u52A1\u4E0E\u53CC\u8FB9\u6570\u5B57\u6E05\u7B97\u7F51\u7EDC\u3002", summaryCkb: "\u0695\u0627\u06A9\u06CE\u0634\u0627\u0646\u06CC \u0661\u0662\u0660\u0660 \u06A9\u0645 \u06A9\u06D5\u06CC\u0628\u06B5\u06CC \u0641\u0627\u06CC\u0628\u06D5\u0631 \u0626\u06C6\u067E\u062A\u06CC\u06A9 \u0648 \u062F\u0631\u0648\u0633\u062A\u06A9\u0631\u062F\u0646\u06CC \u062F\u0648\u0648 \u0633\u06D5\u0646\u062A\u06D5\u0631\u06CC \u062F\u0627\u062A\u0627\u06CC \u067E\u06CE\u0634\u06A9\u06D5\u0648\u062A\u0648\u0648 \u0644\u06D5 \u0628\u06D5\u063A\u062F\u0627 \u0648 \u0647\u06D5\u0648\u0644\u06CE\u0631 \u0628\u06C6 \u062E\u0632\u0645\u06D5\u062A\u06AF\u0648\u0632\u0627\u0631\u06CC \u062F\u06CC\u062C\u06CC\u062A\u0627\u06B5\u06CC.", contentEn: "The Communications and Media Commission (CMC) and KRG Department of Information Technology provide unified sovereign concessions for fiber right-of-way alongside major highway corridors. Investors gain dark-fiber leasing exclusivity to telecom carriers and public ministries, backed by a 100% tax exemption on data hardware imports under Iraq Investment Law.", contentAr: "\u062A\u0648\u0641\u0631 \u0647\u064A\u0626\u0629 \u0627\u0644\u0625\u0639\u0644\u0627\u0645 \u0648\u0627\u0644\u0627\u062A\u0635\u0627\u0644\u0627\u062A \u0648\u062F\u0627\u0626\u0631\u0629 \u062A\u0643\u0646\u0648\u0644\u0648\u062C\u064A\u0627 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062A \u0641\u064A \u0625\u0642\u0644\u064A\u0645 \u0643\u0648\u0631\u062F\u0633\u062A\u0627\u0646 \u0627\u0645\u062A\u064A\u0627\u0632\u0627\u062A \u0645\u0648\u062D\u062F\u0629 \u0644\u0645\u062F \u0627\u0644\u0623\u0644\u064A\u0627\u0641 \u0639\u0644\u0649 \u0627\u0645\u062A\u062F\u0627\u062F \u0627\u0644\u0637\u0631\u0642 \u0627\u0644\u0633\u0631\u064A\u0639\u0629. \u064A\u062D\u0635\u0644 \u0627\u0644\u0645\u0633\u062A\u062B\u0645\u0631\u0648\u0646 \u0639\u0644\u0649 \u062D\u0642\u0648\u0642 \u062A\u0623\u062C\u064A\u0631 \u062D\u0635\u0631\u064A\u0629 \u0644\u0634\u0631\u0643\u0627\u062A \u0627\u0644\u0627\u062A\u0635\u0627\u0644\u0627\u062A \u0648\u0627\u0644\u0648\u0632\u0627\u0631\u0627\u062A\u060C \u0645\u0639 \u0625\u0639\u0641\u0627\u0621 \u062C\u0645\u0631\u0643\u064A \u0648\u0636\u0631\u064A\u0628\u064A \u0643\u0627\u0645\u0644 \u0628\u0646\u0633\u0628\u0629 \u0661\u0660\u0660\u066A \u0639\u0644\u0649 \u062E\u0648\u0627\u062F\u0645 \u0648\u0645\u0639\u062F\u0627\u062A \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A.", contentZh: "\u4F0A\u62C9\u514B\u901A\u4FE1\u4E0E\u5A92\u4F53\u59D4\u5458\u4F1A\uFF08CMC\uFF09\u53CA\u5E93\u533A\u653F\u5E9C\u4FE1\u606F\u6280\u672F\u90E8\u8054\u5408\u6388\u4E88\u6CBF\u56FD\u5BB6\u9AD8\u901F\u516C\u8DEF\u5E72\u7EBF\u7684\u72EC\u5BB6\u5149\u7F06\u7BA1\u5ECA\u901A\u884C\u6743\u3002\u6295\u8D44\u8D22\u56E2\u5C06\u83B7\u5F97\u5411\u5404\u5927\u7535\u4FE1\u8FD0\u8425\u5546\u53CA\u653F\u5E9C\u90E8\u95E8\u79DF\u8D41\u88F8\u5149\u7EA4\u7684\u72EC\u5BB6\u7279\u8BB8\u6743\uFF0C\u540C\u65F6\u4EAB\u53D7\u670D\u52A1\u5668\u53CA\u901A\u4FE1\u8BBE\u5907\u8FDB\u53E3\u5168\u989D\u514D\u7A0E\u5F85\u9047\u3002", contentCkb: "\u062F\u06D5\u0633\u062A\u06D5\u06CC \u0695\u0627\u06AF\u06D5\u06CC\u0627\u0646\u062F\u0646 \u0648 \u06AF\u06D5\u06CC\u0627\u0646\u062F\u0646 \u0648 \u0641\u06D5\u0631\u0645\u0627\u0646\u06AF\u06D5\u06CC \u062A\u06D5\u06A9\u0646\u06D5\u0644\u06C6\u062C\u06CC\u0627\u06CC \u0632\u0627\u0646\u06CC\u0627\u0631\u06CC \u0647\u06D5\u0631\u06CE\u0645 \u0645\u0627\u0641\u06CC \u0628\u06D5\u06A9\u0627\u0631\u0647\u06CE\u0646\u0627\u0646\u06CC \u0695\u06CE\u06AF\u0627\u06A9\u0627\u0646 \u062F\u06D5\u0628\u06D5\u062E\u0634\u0646 \u0628\u06C6 \u0695\u0627\u06A9\u06CE\u0634\u0627\u0646\u06CC \u0647\u06CE\u06B5\u06D5\u06A9\u0627\u0646 \u0644\u06D5\u06AF\u06D5\u06B5 \u0628\u06D5\u062E\u0634\u06CC\u0646\u06CC \u062A\u06D5\u0648\u0627\u0648\u06CC \u0628\u0627\u062C \u0644\u06D5\u0633\u06D5\u0631 \u0626\u0627\u0645\u06CE\u0631\u06D5\u06A9\u0627\u0646.", category: "TECHNOLOGY", sector: "Cloud Infrastructure & 5G Grids", investmentValue: "$450 Million", location: "Federal Iraq & Kurdistan Region", coverImage: "https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=1200&q=80", featured: false, order: 5, status: "OPEN", contactEmail: "telecom@iraqi-chineseagency.com" }, { slug: "kurdistan-mineral-industrial-park", titleEn: "Kurdistan Regional Mineral Extraction & Structural Metallurgy Park", titleAr: "\u0645\u062C\u0645\u0639 \u0627\u0633\u062A\u062E\u0631\u0627\u062C \u0627\u0644\u0645\u0639\u0627\u062F\u0646 \u0648\u0627\u0644\u0635\u0646\u0627\u0639\u0627\u062A \u0627\u0644\u0645\u0639\u062F\u0646\u064A\u0629 \u0627\u0644\u0625\u0646\u0634\u0627\u0626\u064A\u0629 \u0641\u064A \u0625\u0642\u0644\u064A\u0645 \u0643\u0648\u0631\u062F\u0633\u062A\u0627\u0646", titleZh: "\u5E93\u5C14\u5FB7\u65AF\u5766\u77FF\u4EA7\u8D44\u6E90\u9AD8\u6548\u5F00\u91C7\u4E0E\u91CD\u578B\u5EFA\u6750\u51B6\u91D1\u5DE5\u4E1A\u56ED", titleCkb: "\u0634\u0627\u0631\u06C6\u0686\u06A9\u06D5\u06CC \u067E\u06CC\u0634\u06D5\u0633\u0627\u0632\u06CC \u062F\u06D5\u0631\u0647\u06CE\u0646\u0627\u0646\u06CC \u06A9\u0627\u0646\u0632\u0627\u06A9\u0627\u0646 \u0648 \u06A9\u0627\u0646\u0632\u0627 \u0628\u06CC\u0646\u0627\u0633\u0627\u0632\u06CC\u06CC\u06D5\u06A9\u0627\u0646 \u0644\u06D5 \u0647\u06D5\u0631\u06CE\u0645\u06CC \u0643\u0648\u0631\u062F\u0633\u062A\u0627\u0646", summaryEn: "Large-scale limestone, gypsum, and structural steel manufacturing facilities situated under KRG Investment Law No. 4 with full 10-year tax exemptions and dedicated electrical grid tie-ins.", summaryAr: "\u0645\u0646\u0634\u0622\u062A \u0644\u062A\u0635\u0646\u064A\u0639 \u0627\u0644\u062D\u062C\u0631 \u0627\u0644\u062C\u064A\u0631\u064A \u0648\u0627\u0644\u062C\u0628\u0633 \u0648\u0627\u0644\u062D\u062F\u064A\u062F \u0627\u0644\u0625\u0646\u0634\u0627\u0626\u064A \u0628\u0645\u0648\u062C\u0628 \u0642\u0627\u0646\u0648\u0646 \u0627\u0633\u062A\u062B\u0645\u0627\u0631 \u0643\u0648\u0631\u062F\u0633\u062A\u0627\u0646 \u0631\u0642\u0645 \u0664 \u0645\u0639 \u0625\u0639\u0641\u0627\u0621 \u0636\u0631\u064A\u0628\u064A \u0634\u0627\u0645\u0644 \u0644\u0640 \u0661\u0660 \u0633\u0646\u0648\u0627\u062A \u0648\u0631\u0628\u0637 \u0643\u0647\u0631\u0628\u0627\u0626\u064A \u0635\u0646\u0627\u0639\u064A \u0645\u0628\u0627\u0634\u0631.", summaryZh: "\u4F9D\u6258\u5E93\u5C14\u5FB7\u65AF\u5766\u4E30\u5BCC\u7684\u9AD8\u54C1\u4F4D\u77F3\u7070\u77F3\u4E0E\u94C1\u77FF\u8D44\u6E90\uFF0C\u4F9D\u7167\u5E93\u533A\u7B2C4\u53F7\u6295\u8D44\u6CD5\u5EFA\u8BBE\u73B0\u4EE3\u5316\u7EFF\u8272\u5EFA\u6750\u4E0E\u5EFA\u7B51\u94A2\u6750\u51B6\u91D1\u4EA7\u4E1A\u56ED\uFF0C\u4EAB\u53D710\u5E74\u5168\u9762\u514D\u7A0E\u53CA\u5DE5\u4E1A\u7528\u7535\u4E13\u7EBF\u4FDD\u969C\u3002", summaryCkb: "\u062F\u0627\u0645\u06D5\u0632\u0631\u0627\u0646\u062F\u0646\u06CC \u06A9\u0627\u0631\u06AF\u06D5\u06A9\u0627\u0646\u06CC \u0628\u06D5\u0631\u062F\u06CC \u06AF\u06D5\u0686 \u0648 \u0686\u06CC\u0645\u06D5\u0646\u062A\u06C6 \u0648 \u0626\u0627\u0633\u0646 \u0628\u06D5\u067E\u06CE\u06CC \u06CC\u0627\u0633\u0627\u06CC \u0648\u06D5\u0628\u06D5\u0631\u0647\u06CE\u0646\u0627\u0646\u06CC \u0698\u0645\u0627\u0631\u06D5 \u0664\u06CC \u0647\u06D5\u0631\u06CE\u0645\u06CC \u06A9\u0648\u0631\u062F\u0633\u062A\u0627\u0646 \u0628\u06D5 \u0644\u06CE\u062E\u06C6\u0634\u0628\u0648\u0648\u0646\u06CC \u062A\u06D5\u0648\u0627\u0648\u06CC \u0628\u0627\u062C \u0628\u06C6 \u062F\u06D5 \u0633\u0627\u06B5.", contentEn: "Licensed by the KRG Board of Investment, the park covers 300 hectares near major transport axes connecting Erbil and Sulaymaniyah to central Iraq. Foreign enterprises enjoy 100% foreign ownership rights, sovereign leasehold protection, and direct export permits for building materials needed in national reconstruction programs.", contentAr: "\u0645\u0631\u062E\u0635 \u0645\u0646 \u0642\u0628\u0644 \u0647\u064A\u0626\u0629 \u0627\u0633\u062A\u062B\u0645\u0627\u0631 \u0643\u0648\u0631\u062F\u0633\u062A\u0627\u0646 \u0628\u0645\u0633\u0627\u062D\u0629 \u0663\u0660\u0660 \u0647\u0643\u062A\u0627\u0631 \u0628\u0627\u0644\u0642\u0631\u0628 \u0645\u0646 \u0627\u0644\u0645\u062D\u0627\u0648\u0631 \u0627\u0644\u0631\u0627\u0628\u0637\u0629 \u0628\u064A\u0646 \u0623\u0631\u0628\u064A\u0644 \u0648\u0627\u0644\u0633\u0644\u064A\u0645\u0627\u0646\u064A\u0629 \u0648\u0648\u0633\u0637 \u0627\u0644\u0639\u0631\u0627\u0642. \u062A\u062A\u0645\u062A\u0639 \u0627\u0644\u0634\u0631\u0643\u0627\u062A \u0627\u0644\u0623\u062C\u0646\u0628\u064A\u0629 \u0628\u0645\u0644\u0643\u064A\u0629 \u0628\u0646\u0633\u0628\u0629 \u0661\u0660\u0660\u066A\u060C \u0648\u062D\u0645\u0627\u064A\u0629 \u0633\u064A\u0627\u062F\u064A\u0629 \u0644\u0639\u0642\u0648\u062F \u0627\u0644\u0625\u064A\u062C\u0627\u0631\u060C \u0648\u062A\u0635\u0627\u0631\u064A\u062D \u062A\u0635\u062F\u064A\u0631 \u0648\u062A\u0648\u0631\u064A\u062F \u0644\u0645\u0648\u0627\u062F \u0627\u0644\u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u062E\u0635\u0635\u0629 \u0644\u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u0625\u0639\u0645\u0627\u0631.", contentZh: "\u8BE5\u4EA7\u4E1A\u56ED\u83B7\u5F97\u5E93\u533A\u6295\u8D44\u59D4\u5458\u4F1A\u5168\u9762\u7279\u8BB8\u6279\u6587\uFF0C\u5360\u5730300\u516C\u9877\uFF0C\u627C\u5B88\u8FDE\u63A5\u57C3\u5C14\u6BD4\u52D2\u3001\u82CF\u83B1\u66FC\u5C3C\u4E9A\u901A\u5F80\u4F0A\u62C9\u514B\u4E2D\u90E8\u5E73\u539F\u7684\u6838\u5FC3\u8D27\u8FD0\u8D70\u5ECA\u3002\u5916\u8D44\u4F01\u4E1A\u4EAB\u6709100%\u5168\u8D44\u63A7\u80A1\u6743\u3001\u4E3B\u6743\u7EA7\u79DF\u8D41\u6743\u76CA\u4FDD\u62A4\uFF0C\u5E76\u76F4\u901A\u56FD\u5BB6\u91CD\u5EFA\u91C7\u8D2D\u8BA1\u5212\u7684\u5EFA\u6750\u76F4\u4F9B\u91C7\u8D2D\u901A\u9053\u3002", contentCkb: "\u0645\u06C6\u06B5\u06D5\u062A\u062F\u0631\u0627\u0648\u06D5 \u0644\u06D5\u0644\u0627\u06CC\u06D5\u0646 \u062F\u06D5\u0633\u062A\u06D5\u06CC \u0648\u06D5\u0628\u06D5\u0631\u0647\u06CE\u0646\u0627\u0646\u06CC \u0647\u06D5\u0631\u06CE\u0645\u06CC \u06A9\u0648\u0631\u062F\u0633\u062A\u0627\u0646 \u0644\u06D5\u0633\u06D5\u0631 \u0695\u0648\u0648\u0628\u06D5\u0631\u06CC \u0663\u0660\u0660 \u0647\u06CE\u06A9\u062A\u0627\u0631 \u0644\u06D5 \u0646\u06CE\u0648\u0627\u0646 \u0647\u06D5\u0648\u0644\u06CE\u0631 \u0648 \u0633\u0644\u06CE\u0645\u0627\u0646\u06CC\u060C \u0628\u06D5 \u0645\u0627\u0641\u06CC \u0661\u0660\u0660\u066A \u062E\u0627\u0648\u06D5\u0646\u062F\u0627\u0631\u06CE\u062A\u06CC \u0628\u06C6 \u0628\u06CC\u0627\u0646\u06CC\u06CC\u06D5\u06A9\u0627\u0646.", category: "INDUSTRIAL_ZONES", sector: "Metallurgy & Building Materials", investmentValue: "$580 Million", location: "Sulaymaniyah & Erbil Governorates", coverImage: "https://images.unsplash.com/photo-1504917599217-d4dc5ebe6122?auto=format&fit=crop&w=1200&q=80", featured: false, order: 6, status: "OPEN", contactEmail: "industrial@iraqi-chineseagency.com" }, { slug: "bilateral-customs-legal-advisory", titleEn: "Bilateral Legal Advisory, Customs Exemption & Sovereign Treaty Desk", titleAr: "\u0627\u0644\u0645\u0643\u062A\u0628 \u0627\u0644\u0627\u0633\u062A\u0634\u0627\u0631\u064A \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064A \u0627\u0644\u062B\u0646\u0627\u0626\u064A \u0644\u0644\u0625\u0639\u0641\u0627\u0621\u0627\u062A \u0627\u0644\u062C\u0645\u0631\u0643\u064A\u0629 \u0648\u0627\u0644\u0627\u0645\u062A\u062B\u0627\u0644 \u0644\u0644\u0645\u0639\u0627\u0647\u062F\u0627\u062A \u0627\u0644\u0633\u064A\u0627\u062F\u064A\u0629", titleZh: "\u4E2D\u4F0A\u53CC\u8FB9\u5546\u4E8B\u6CD5\u5F8B\u987E\u95EE\u3001\u6D77\u5173\u514D\u7A0E\u653F\u7B56\u4E0E\u4E3B\u6743\u6761\u7EA6\u4E13\u5C5E\u670D\u52A1\u53F0", titleCkb: "\u062F\u06D5\u0641\u062A\u06D5\u0631\u06CC \u0695\u0627\u0648\u06CE\u0698\u06A9\u0627\u0631\u06CC \u06CC\u0627\u0633\u0627\u06CC\u06CC \u062F\u0648\u0648\u0642\u06C6\u06B5\u06CC\u060C \u0644\u06CE\u062E\u06C6\u0634\u0628\u0648\u0648\u0646\u06CC \u06AF\u0648\u0645\u0631\u06AF\u06CC \u0648 \u067E\u06D5\u06CC\u0645\u0627\u0646\u0646\u0627\u0645\u06D5 \u0633\u06CC\u0627\u062F\u06CC\u06CC\u06D5\u06A9\u0627\u0646", summaryEn: "Dedicated corporate retainer and compliance service guiding Chinese and international corporations through Investment Law No. 13 certifications, tax holidays, and bilateral dispute arbitration.", summaryAr: "\u062E\u062F\u0645\u0627\u062A \u0627\u0633\u062A\u0634\u0627\u0631\u064A\u0629 \u0648\u0645\u062A\u0627\u0628\u0639\u0629 \u0644\u0644\u0645\u0624\u0633\u0633\u0627\u062A \u0627\u0644\u0635\u064A\u0646\u064A\u0629 \u0648\u0627\u0644\u062F\u0648\u0644\u064A\u0629 \u0644\u0644\u062D\u0635\u0648\u0644 \u0639\u0644\u0649 \u0634\u0647\u0627\u062F\u0627\u062A \u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0627\u0633\u062A\u062B\u0645\u0627\u0631 \u0631\u0642\u0645 \u0661\u0663\u060C \u0648\u0627\u0644\u0625\u0639\u0641\u0627\u0621\u0627\u062A \u0627\u0644\u0636\u0631\u064A\u0628\u064A\u0629\u060C \u0648\u0627\u0644\u062A\u062D\u0643\u064A\u0645 \u0627\u0644\u062A\u062C\u0627\u0631\u064A \u0627\u0644\u062B\u0646\u0627\u0626\u064A.", summaryZh: "\u4E3A\u4E2D\u8D44\u4F01\u4E1A\u91CF\u8EAB\u6253\u9020\u7684\u5E38\u5E74\u6295\u8D44\u6CD5\u5F8B\u5408\u89C4\u4E0E\u901A\u5173\u4FBF\u5229\u987E\u95EE\u670D\u52A1\uFF0C\u5168\u7A0B\u4EE3\u529E\u7B2C13\u53F7\u6295\u8D44\u6CD5\u8D44\u8D28\u8BA4\u8BC1\u3001\u514D\u7A0E\u6279\u6587\u3001\u6D77\u5173\u7EFF\u901A\u6838\u51C6\u53CA\u53CC\u8FB9\u5546\u4E8B\u4EF2\u88C1\u652F\u6301\u3002", summaryCkb: "\u062E\u0632\u0645\u06D5\u062A\u06AF\u0648\u0632\u0627\u0631\u06CC \u06CC\u0627\u0633\u0627\u06CC\u06CC \u0648 \u0695\u0627\u0648\u06CE\u0698\u06A9\u0627\u0631\u06CC \u0628\u06C6 \u06A9\u06C6\u0645\u067E\u0627\u0646\u06CC\u0627 \u0628\u06CC\u0627\u0646\u06CC \u0648 \u0686\u06CC\u0646\u06CC\u06CC\u06D5\u06A9\u0627\u0646 \u0628\u06C6 \u0648\u06D5\u0631\u06AF\u0631\u062A\u0646\u06CC \u0644\u06CE\u062E\u06C6\u0634\u0628\u0648\u0648\u0646\u06CC \u0628\u0627\u062C \u0628\u06D5\u067E\u06CE\u06CC \u06CC\u0627\u0633\u0627\u06CC \u0698\u0645\u0627\u0631\u06D5 \u0661\u0663 \u0648 \u0686\u0627\u0631\u06D5\u0633\u06D5\u0631\u06CC \u0646\u0627\u06A9\u06C6\u06A9\u06CC\u06CC\u06D5 \u0628\u0627\u0632\u0631\u06AF\u0627\u0646\u06CC\u06CC\u06D5\u06A9\u0627\u0646.", contentEn: "Administered directly by senior bilateral legal counsel accredited in Baghdad and Beijing, this desk handles certificate of investment issuance from the National Investment Commission (NIC), customs bond releases at Umm Qasr, and bilateral currency conversion guarantees. Available on retainers for state enterprises and private chambers of commerce.", contentAr: "\u064A\u064F\u062F\u0627\u0631 \u0627\u0644\u0645\u0643\u062A\u0628 \u0645\u0628\u0627\u0634\u0631\u0629 \u0645\u0646 \u0642\u0628\u0644 \u0645\u0633\u062A\u0634\u0627\u0631\u064A\u0646 \u0642\u0627\u0646\u0648\u0646\u064A\u064A\u0646 \u0645\u0639\u062A\u0645\u062F\u064A\u0646 \u0641\u064A \u0628\u063A\u062F\u0627\u062F \u0648\u0628\u0643\u064A\u0646\u060C \u0648\u064A\u062A\u0648\u0644\u0649 \u0627\u0633\u062A\u062E\u0631\u0627\u062C \u0625\u062C\u0627\u0632\u0627\u062A \u0627\u0644\u0627\u0633\u062A\u062B\u0645\u0627\u0631 \u0645\u0646 \u0627\u0644\u0647\u064A\u0626\u0629 \u0627\u0644\u0648\u0637\u0646\u064A\u0629 \u0644\u0644\u0627\u0633\u062A\u062B\u0645\u0627\u0631 (NIC)\u060C \u0648\u0627\u0644\u0625\u0641\u0631\u0627\u062C \u0627\u0644\u062C\u0645\u0631\u0643\u064A \u0641\u064A \u0623\u0645 \u0642\u0635\u0631\u060C \u0648\u0636\u0645\u0627\u0646\u0627\u062A \u062A\u0633\u0648\u064A\u0629 \u0627\u0644\u0639\u0645\u0644\u0627\u062A. \u0645\u062A\u0627\u062D \u0644\u0644\u0634\u0631\u0643\u0627\u062A \u0627\u0644\u062D\u0643\u0648\u0645\u064A\u0629 \u0648\u063A\u0631\u0641 \u0627\u0644\u062A\u062C\u0627\u0631\u0629.", contentZh: "\u7531\u5E38\u9A7B\u5DF4\u683C\u8FBE\u4E0E\u5317\u4EAC\u7684\u8D44\u6DF1\u53CC\u8FB9\u6D89\u5916\u6CD5\u52A1\u56E2\u961F\u8054\u5408\u4E3B\u7406\uFF0C\u76F4\u63A5\u534F\u52A9\u4F01\u4E1A\u9AD8\u6548\u7533\u529E\u4F0A\u62C9\u514B\u56FD\u5BB6\u6295\u8D44\u59D4\u5458\u4F1A\uFF08NIC\uFF09\u4E3B\u6743\u6295\u8D44\u6267\u7167\u3001\u4E4C\u59C6\u76D6\u65AF\u5C14\u6E2F\u6D77\u5173\u4FDD\u51FD\u5FEB\u901F\u89E3\u62BC\u4EE5\u53CA\u672C\u5E01\u6E05\u7B97\u8D44\u91D1\u7ED3\u7B97\u8DEF\u5F84\u5408\u89C4\u6838\u9A8C\u3002\u652F\u6301\u5927\u578B\u592E\u56FD\u4F01\u4E0E\u6C11\u8425\u5546\u4F1A\u6309\u5E74\u59D4\u6258\u7B7E\u7EA6\u3002", contentCkb: "\u0644\u06D5\u0644\u0627\u06CC\u06D5\u0646 \u067E\u0627\u0631\u06CE\u0632\u06D5\u0631\u0627\u0646 \u0648 \u067E\u0633\u067E\u06C6\u0695\u0627\u0646\u06CC \u0628\u0627\u0648\u06D5\u0695\u067E\u06CE\u06A9\u0631\u0627\u0648 \u0644\u06D5 \u0628\u06D5\u063A\u062F\u0627 \u0648 \u067E\u06D5\u06A9\u06CC\u0646 \u0628\u06D5\u0695\u06CE\u0648\u06D5\u062F\u06D5\u0628\u0631\u06CE\u062A\u060C \u0628\u06C6 \u062F\u06D5\u0631\u06A9\u0631\u062F\u0646\u06CC \u0645\u06C6\u06B5\u06D5\u062A\u06CC \u062F\u06D5\u0633\u062A\u06D5\u06CC \u0646\u06CC\u0634\u062A\u0645\u0627\u0646\u06CC \u0648\u06D5\u0628\u06D5\u0631\u0647\u06CE\u0646\u0627\u0646 (NIC) \u0648 \u067E\u0627\u06A9\u062A\u0627\u0648\u06CC \u06AF\u0648\u0645\u0631\u06AF\u06CC \u0644\u06D5 \u0626\u0648\u0645 \u0642\u06D5\u0633\u0631.", category: "LEGAL_ADVISORY", sector: "Trade Treaty Compliance & Tariff Immunities", investmentValue: "Institutional Retainer", location: "Baghdad / Beijing Bilateral Chambers", coverImage: "https://images.unsplash.com/photo-1450133064473-71024230f91b?auto=format&fit=crop&w=1200&q=80", featured: false, order: 7, status: "ACTIVE", contactEmail: "legal@iraqi-chineseagency.com" }, { slug: "rmb-iqd-trade-financing-facility", titleEn: "Bilateral RMB / IQD Sovereign Currency Settlement & Letter of Credit Facility", titleAr: "\u062A\u0633\u0647\u064A\u0644\u0627\u062A \u0627\u0644\u0645\u0642\u0627\u0635\u0629 \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u0629 \u0628\u0627\u0644\u064A\u0648\u0627\u0646 \u0648\u0627\u0644\u062F\u064A\u0646\u0627\u0631 \u0648\u062E\u0637\u0627\u0628\u0627\u062A \u0627\u0644\u0627\u0639\u062A\u0645\u0627\u062F \u0627\u0644\u0645\u0633\u062A\u0646\u062F\u064A\u0629 \u0627\u0644\u062B\u0646\u0627\u0626\u064A\u0629", titleZh: "\u4E2D\u4F0A\u672C\u5E01\u76F4\u63A5\u7ED3\u7B97\u4E13\u9879\u901A\u9053\u4E0E\u8DE8\u5883\u4FE1\u7528\u8BC1\u878D\u8D44\u4FBF\u5229\u5316\u673A\u5236", titleCkb: "\u0626\u0627\u0633\u0627\u0646\u06A9\u0627\u0631\u06CC \u067E\u0627\u06A9\u062A\u0627\u0648\u06CC \u062F\u0631\u0627\u0648\u06CC \u06CC\u0648\u0627\u0646 / \u062F\u06CC\u0646\u0627\u0631 \u0648 \u0646\u0627\u0645\u06D5\u06CC \u0645\u062A\u0645\u0627\u0646\u06D5\u06CC \u0628\u0627\u0646\u06A9\u06CC (LC)", summaryEn: "Direct bilateral clearing infrastructure bypassing third-party clearing currencies for heavy industrial machinery, energy EPC contracts, and raw agricultural imports.", summaryAr: "\u0628\u0646\u064A\u0629 \u062A\u062D\u062A\u064A\u0629 \u0644\u0644\u0645\u0642\u0627\u0635\u0629 \u0627\u0644\u062B\u0646\u0627\u0626\u064A\u0629 \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u0629 \u0644\u062A\u062C\u0627\u0648\u0632 \u0627\u0644\u0639\u0645\u0644\u0627\u062A \u0627\u0644\u0648\u0633\u064A\u0637\u0629 \u0641\u064A \u062A\u0645\u0648\u064A\u0644 \u0627\u0644\u0645\u0639\u062F\u0627\u062A \u0627\u0644\u0635\u0646\u0627\u0639\u064A\u0629 \u0627\u0644\u062B\u0642\u064A\u0644\u0629 \u0648\u0639\u0642\u0648\u062F \u0627\u0644\u0637\u0627\u0642\u0629 \u0648\u0627\u0644\u062A\u0648\u0631\u064A\u062F\u0627\u062A \u0627\u0644\u0627\u0633\u062A\u0631\u0627\u062A\u064A\u062C\u064A\u0629.", summaryZh: "\u4F9D\u6258\u4F0A\u62C9\u514B\u4E2D\u592E\u94F6\u884C\u4E0E\u4E2D\u56FD\u4E3B\u8981\u56FD\u6709\u5546\u4E1A\u94F6\u884C\u5EFA\u7ACB\u7684\u4E3B\u6743\u76F4\u901A\u6E05\u7B97\u67B6\u6784\uFF0C\u5168\u9762\u514D\u9664\u7B2C\u4E09\u65B9\u8D27\u5E01\u5BF9\u51B2\u78E8\u635F\uFF0C\u4E3A\u5927\u578B\u5DE5\u7A0B\u603B\u5305\u4E0E\u5927\u5B97\u8FDB\u51FA\u53E3\u63D0\u4F9B\u6781\u901F\u4FE1\u7528\u8BC1\u5F00\u7ACB\u670D\u52A1\u3002", summaryCkb: "\u0698\u06CE\u0631\u062E\u0627\u0646\u06CC \u067E\u0627\u06A9\u062A\u0627\u0648\u06CC \u0695\u0627\u0633\u062A\u06D5\u0648\u062E\u06C6 \u0628\u06D5\u0628\u06CE \u062F\u0631\u0627\u0648\u06D5 \u0646\u0627\u0648\u0628\u06D5\u0646\u062F\u06D5\u06A9\u0627\u0646 \u0628\u06C6 \u06A9\u0695\u06CC\u0646\u06CC \u0626\u0627\u0645\u06CE\u0631\u06D5 \u0642\u0648\u0631\u0633\u06D5 \u067E\u06CC\u0634\u06D5\u0633\u0627\u0632\u06CC\u06CC\u06D5\u06A9\u0627\u0646 \u0648 \u06AF\u0631\u06CE\u0628\u06D5\u0633\u062A\u06D5\u06A9\u0627\u0646\u06CC \u0648\u0632\u06D5 \u0628\u06D5 \u06CC\u0648\u0627\u0646 \u0648 \u062F\u06CC\u0646\u0627\u0631.", contentEn: "Under the supervision of the Central Bank of Iraq and Chinese correspondent partner banks, this financing desk offers issuance of RMB-denominated Letters of Credit (LC), structured supply-chain factoring, and sovereign escrow accounts. Over 35% of bilateral trade volume is supported with reduced transactional overhead and guaranteed settlement execution in under 24 hours.", contentAr: "\u062A\u062D\u062A \u0625\u0634\u0631\u0627\u0641 \u0627\u0644\u0628\u0646\u0643 \u0627\u0644\u0645\u0631\u0643\u0632\u064A \u0627\u0644\u0639\u0631\u0627\u0642\u064A \u0648\u0627\u0644\u0628\u0646\u0648\u0643 \u0627\u0644\u0635\u064A\u0646\u064A\u0629 \u0627\u0644\u0634\u0631\u064A\u0643\u0629\u060C \u064A\u0642\u062F\u0645 \u0647\u0630\u0627 \u0627\u0644\u0645\u0643\u062A\u0628 \u0625\u0635\u062F\u0627\u0631 \u062E\u0637\u0627\u0628\u0627\u062A \u0627\u0639\u062A\u0645\u0627\u062F \u0628\u0627\u0644\u064A\u0648\u0627\u0646\u060C \u0648\u062A\u0645\u0648\u064A\u0644 \u0633\u0644\u0627\u0633\u0644 \u0627\u0644\u0625\u0645\u062F\u0627\u062F\u060C \u0648\u062D\u0633\u0627\u0628\u0627\u062A \u0627\u0644\u0636\u0645\u0627\u0646 \u0627\u0644\u0633\u064A\u0627\u062F\u064A\u0629. \u064A\u0636\u0645\u0646 \u062A\u0633\u0648\u064A\u0629 \u0623\u0643\u062B\u0631 \u0645\u0646 \u0663\u0665\u066A \u0645\u0646 \u0627\u0644\u062A\u062C\u0627\u0631\u0629 \u0627\u0644\u062B\u0646\u0627\u0626\u064A\u0629 \u0628\u0643\u0644\u0641\u0629 \u0645\u0646\u062E\u0641\u0636\u0629 \u0648\u062A\u0646\u0641\u064A\u0630 \u062E\u0644\u0627\u0644 \u0623\u0642\u0644 \u0645\u0646 \u0662\u0664 \u0633\u0627\u0639\u0629.", contentZh: "\u5728\u4F0A\u62C9\u514B\u4E2D\u592E\u94F6\u884C\u4E0E\u4E2D\u56FD\u5927\u578B\u6218\u7565\u5546\u4E1A\u94F6\u884C\u76D1\u7BA1\u6846\u67B6\u4E0B\uFF0C\u672C\u4E1A\u52A1\u4E13\u67DC\u63D0\u4F9B\u4EBA\u6C11\u5E01\u8BA1\u4EF7\u5373\u671F/\u8FDC\u671F\u4FE1\u7528\u8BC1\u5F00\u7ACB\u3001\u4F9B\u5E94\u94FE\u5E94\u6536\u8D26\u6B3E\u4FDD\u7406\u53CA\u4E3B\u6743\u6258\u7BA1\u8D26\u6237\u7BA1\u7406\u3002\u5168\u9762\u652F\u6301\u53CC\u8FB9\u8D38\u6613\u76F4\u63A5\u7ED3\u7B97\uFF0C\u663E\u8457\u964D\u4F4E\u7EFC\u5408\u8D22\u52A1\u624B\u7EED\u8D39\uFF0C\u5E76\u5B9E\u73B024\u5C0F\u65F6\u5185\u6781\u901F\u53CC\u5411\u8D44\u91D1\u6E05\u7B97\u4EA4\u5272\u3002", contentCkb: "\u0644\u06D5\u0698\u06CE\u0631 \u0686\u0627\u0648\u062F\u06CE\u0631\u06CC \u0628\u0627\u0646\u06A9\u06CC \u0646\u0627\u0648\u06D5\u0646\u062F\u06CC \u0639\u06CE\u0631\u0627\u0642 \u0648 \u0628\u0627\u0646\u06A9\u06D5 \u0647\u0627\u0648\u0628\u06D5\u0634\u06D5 \u0686\u06CC\u0646\u06CC\u06CC\u06D5\u06A9\u0627\u0646\u060C \u062F\u06D5\u0631\u06A9\u0631\u062F\u0646\u06CC \u0646\u0627\u0645\u06D5\u06CC \u0645\u062A\u0645\u0627\u0646\u06D5 \u0628\u06D5 \u06CC\u0648\u0627\u0646 \u0648 \u067E\u0627\u0631\u0627\u0633\u062A\u0646\u06CC \u0633\u06D5\u0631\u0645\u0627\u06CC\u06D5 \u062F\u0627\u0628\u06CC\u0646 \u062F\u06D5\u06A9\u0627\u062A \u0628\u06D5 \u062C\u06CE\u0628\u06D5\u062C\u06CE\u06A9\u0631\u062F\u0646 \u0644\u06D5 \u06A9\u06D5\u0645\u062A\u0631 \u0644\u06D5 \u0662\u0664 \u06A9\u0627\u062A\u0698\u0645\u06CE\u0631\u062F\u0627.", category: "FINANCIAL_SERVICES", sector: "Cross-Border Settlement & Trade Finance", investmentValue: "Multi-Tier Sovereign Facility", location: "Central Bank of Iraq / PBOC Corridors", coverImage: "https://images.unsplash.com/photo-1559526324-4b87b5e36e44?auto=format&fit=crop&w=1200&q=80", featured: true, order: 8, status: "ACTIVE", contactEmail: "finance@iraqi-chineseagency.com" }];
async function seedBusinessOpportunities() {
  try {
    const count = await prisma.businessOpportunity.count();
    if (count >= INITIAL_BUSINESS_OPPORTUNITIES.length) {
      return;
    }
    console.log("\u{1F3E2} Seeding ICA Business Opportunities (8 bilateral projects)...");
    for (const item of INITIAL_BUSINESS_OPPORTUNITIES) {
      await prisma.businessOpportunity.upsert({ where: { slug: item.slug }, update: item, create: item });
    }
    console.log("\u2705 ICA Business Opportunities successfully seeded.");
  } catch (error) {
    console.error("\u26A0\uFE0F Error seeding business opportunities:", error);
  }
}
